","position_plan":{"x":640,"y":620},"disponible_si":{"flag":"ch4-depart-fait"},"pnj":[{"id":"morra","si":{"flag":"morra-recrutee"}}],"boutique":[],"etape_seulement":false,"auberge":false},{"id":"karak-trone","nom":"Salle du Roi-sous-la-Montagne","description":"Une salle immense taillée dans la roche, éclairée par des rivières de lave domptées.","decor":"karak-trone","position":{"x":940,"y":460},"ville":"karak-dum","position_plan":{"x":640,"y":150},"disponible_si":{"flag":"ch4-depart-fait"},"pnj":[{"id":"bardrek"},{"id":"elianne","si":{"flag":"elianne-recrutee"}}],"boutique":[],"etape_seulement":false,"auberge":false},{"id":"karak-forge","nom":"La Grande Forge","description":"La forge la plus chaude du monde. Les armes qui en sortent ne rouillent jamais.","decor":"karak-forge","position":{"x":880,"y":510},"ville":"karak-dum","position_plan":{"x":380,"y":400},"disponible_si":{"flag":"ch4-depart-fait"},"pnj":[{"id":"durna"}],"boutique":["potion-soin-grande","potion-soin-supreme","potion-mana-grande","antidote","bombe-feu","bombe-fumee","biere-de-karak","pierre-de-feu","epee-iv","epee-iv-maitre","deux-mains-iv","deux-mains-iv-maitre","masse-iv","masse-iv-maitre","dague-iv","dague-iv-maitre","arc-iv","arc-iv-maitre","arbalete-iv","arbalete-iv-maitre","baton-iv","baton-iv-maitre","sceptre-iv","sceptre-iv-maitre","orbe-iv","orbe-iv-maitre","instrument-iv","instrument-iv-maitre","lourde-iv","lourde-iv-maitre","intermediaire-iv","intermediaire-iv-maitre","legere-iv","legere-iv-maitre","bouclier-iv","bouclier-iv-maitre","anneau-iv","anneau-iv-maitre","amulette-iv","amulette-iv-maitre","talisman-iv","talisman-iv-maitre","carquois-iv","carquois-iv-maitre","sacoche-iv","sacoche-iv-maitre"],"gerant":"durna","etape_seulement":false,"auberge":false},{"id":"karak-taverne","nom":"La Chope Ardente","description":"Une taverne naine : tables de pierre, chopes de bronze, et des chansons qui durent toute la nuit.","decor":"karak-taverne","position":{"x":1000,"y":520},"ville":"karak-dum","