iption":"Une bibliothèque creusée sous les racines du plus vieil arbre du monde. Interdite depuis mille ans.","decor":"bibliotheque-racines","position":{"x":760,"y":700},"disponible_si":{"quete_etape":{"q-ch3-foret":"bibliotheque"}},"pnj":[],"boutique":[],"etape_seulement":false,"auberge":false},{"id":"clairiere-dechirure","nom":"Clairière de la Déchirure","description":"Une clairière où rien ne pousse. Au centre, l'air tremble comme au-dessus d'un feu.","decor":"clairiere-dechirure","position":{"x":420,"y":520},"disponible_si":{"flag":"sylvenoire-ouverte"},"pnj":[],"boutique":[],"etape_seulement":false,"auberge":false},{"id":"marais-de-brume","nom":"Marais de brume","description":"Une eau noire sous une brume bleue, et des champignons partout.","decor":"marais-de-brume","position":{"x":1160,"y":860},"pnj":[],"boutique":[],"etape_seulement":true,"auberge":false},{"id":"cercle-des-dryades","nom":"Cercle des dryades","description":"Sept arbres en cercle, qui murmurent quand on entre.","decor":"cercle-des-dryades","position":{"x":1360,"y":300},"pnj":[],"boutique":[],"etape_seulement":true,"auberge":false},{"id":"vieux-chene","nom":"Le Vieux-Chêne","description":"Un chêne immense, dont l'écorce suinte une sève violette.","decor":"vieux-chene","position":{"x":1240,"y":640},"pnj":[],"boutique":[],"etape_seulement":true,"auberge":false},{"id":"camp-legion-sylve","nom":"Camp avancé de la Légion","description":"Des tentes noires, cachées sous les fougères, à un jour de marche d'Ithrael.","decor":"camp-legion-sylve","position":{"x":300,"y":820},"pnj":[],"boutique":[],"etape_seulement":true,"auberge":false}]}},"pnj":{"ouzram":{"id":"ouzram","nom":"Maître Ouzram Telli","titre":"Armurier du Grand Bazar","description":"Vieil homme sec au turban safran, lunettes d'or, mains couvertes de petites brûlures de forge.","accueil":"Entrez, entrez ! Une lame de Qarzim ne rouille jamais, et mes prix ne mentent qu'à moitié."},"ziyane":{"id":"ziyane","nom":"Mère Ziyane","titre":"Aubergiste de l'Oasis Bleue","description":"Femme ronde au rire sonore, foulard indigo, bracelets qui tintent à chaque geste.","accueil":"De l'eau fraîche, un lit sous les voiles, et pas de questions. Bienvenue à l'Oasis Bleue."},"ibrek":{"id":"ibrek","nom":"Ibrek Sall","titre":"Intendant de la Guilde à Qarzim","description":"Jeune vulpin aux oreilles rousses, lunettes rondes, registre toujours ouvert. Il connaît les tarifs de tous les contrats par cœur.","accueil":"Comptoir de la Rose des Vents ! Les contrats sont au tableau ; le matériel, c'est ici."},"hassad":{"id":"hassad","nom":"Prévôt Hassad Meriyem","titre":"Prévôt de la Concorde","description":"Homme mince en soie blanche, barbe taillée au cordeau, une bague-cristal violette à chaque main. Courtois, glacial."},"vashti":{"id":"vashti","nom":"Conseillère Vashti Orren","titre":"Conseillère de la Concorde","description":"Femme élégante aux yeux maquillés de khôl, toujours un éventail à la main. Elle sourit trop."},"sorha":{"id":"sorha","nom":"L'Ancienne Sorha","titre":"Doyenne de la tribu Lunecroc","description":"Vieille ourvalis aux oreilles grises, aveugle d'un œil, appuyée sur un bâton gravé de loups. La grand-mère de Kaya."},"tavek":{"id":"tavek","nom":"Tavek Lunecroc","titre":"Chef de guerre lunecroc","description":"Grand ourvalis aux oreilles noires, peintures de guerre rouges, griffes de fer aux poings. Le cousin de Kaya."},"kezir":{"id":"kezir","nom":"Kezir","titre":"Maître de la Main de Sable","description":"Silhouette voilée de noir, voix douce, yeux dorés. Personne n'a jamais vu son visage."},"vask":{"id":"vask","nom":"Capitaine Orlen Vask","titre":"Mercenaire de la Concorde","description":"Cuirasse dorée cabossée, crâne rasé, cicatrice du menton à l'oreille."},"faelis":{"id":"faelis","nom":"Faelis Brumevent","titre":"Marchande elfe","description":"Elfe sylvaine aux cheveux d'argent tressés de feuilles, longue cape vert sombre. Elle vend des herbes, et des secrets."},"archiviste":{"id":"archiviste","nom":"Maître Corvin","titre":"Archiviste royal","description":"Petit homme voûté aux doigts tachés d'encre, qui parle aux livres plus qu'aux gens."},"reine-seve":{"id":"reine-seve","nom":"La Reine-Sève","titre":"Reine des elfes de Sylvenoire","description":"Grande, immobile, des cheveux comme des racines blanches et des yeux couleur de mousse. Elle a vu la Déchirure."},"thaliel":{"id":"thaliel","nom":"Thaliel","titre":"Aubergiste de la Feuille d'Argent","description":"Jeune elfe souriant, tablier vert, qui monte et descend les échelles plus vite qu'un écureuil.","accueil":"Bienvenue à la Feuille d'Argent ! Les hamacs sont doux, et la vue est gratuite."},"mirwen":{"id":"mirwen","nom":"Mirwen","titre":"Marchande du Marché des Graines","description":"Elfe âgée aux mains couvertes de terre, qui connaît le nom de chaque graine de la forêt.","accueil":"Une graine bien choisie vaut une épée. Regardez, mais ne marchez pas sur les pousses."},"orsa":{"id":"orsa","nom":"Orsa Brindebois","titre":"Intendante du Relais de la Guilde","description":"Naine trapue aux tresses rousses, hache à la ceinture, seule naine tolérée à Ithrael — et fière de l'être.","accueil":"Des contrats, du matériel, et pas de feuilles dans mon registre. Qu'est-ce qu'il vous faut ?"},"vaelor":{"id":"vaelor","nom":"Vaelor","titre":"Capitaine de la garde d'Ithrael","description":"Elfe au visage fermé, arc long dans le dos, qui n'a jamais souri à un humain."},"intendant-domaine":{"id":"intendant-domaine","nom":"Maître Aubin","titre":"Intendant de votre domaine","description":"Vieil homme aux mains de paysan et au regard d'ancien soldat, qui tient vos comptes mieux que vous."},"morra":{"id":"morra","nom":"Morwenna « Morra »","titre":"Commandante de la Légion Cendrée","description":"Cornes noires, cheveux couleur de braise, épée-faux plus haute qu'elle. Humour noir, fierté, fatigue."},"enfant-ithrael":{"id":"enfant-ithrael","nom":"Lirëa","titre":"Enfant d'Ithrael","description":"Une petite elfe de quarante ans (huit, pour un humain), qui suit tout ce qui brille."},"bardrek":{"id":"bardrek","nom":"Bardrek","titre":"Roi-sous-la-Montagne","description":"Un nain immense (pour un nain), barbe tressée de fils d'or jusqu'aux genoux, couronne de fer noir. Il ne rit jamais avant le troisième tonneau."},"durna":{"id":"durna","nom":"Maîtresse Durna Martelfeu","titre":"Forgeronne de la Grande Forge","description":"Naine aux bras couverts de cicatrices de brûlure, lunettes de forge sur le front, voix qui couvre les marteaux.","accueil":"Une arme de Karak-Dûm, c'est pour la vie. La vôtre, ou celle de votre ennemi."},"grumli":{"id":"grumli","nom":"Grumli","titre":"Tavernier de la Chope Ardente","description":"Nain rond comme un tonneau, tablier taché de bière, qui chante faux et fort.","accueil":"Une chope ? Deux ? Un tonneau ? Ici, on ne compte qu'à partir de trois !"},"hjalmi":{"id":"hjalmi","nom":"Hjalmi l'Éborgnée","titre":"Intendante de la Guilde à Karak-Dûm","description":"Naine borgne au bandeau de cuir, qui a été rang A avant de perdre son œil contre une salamandre.","accueil":"Contrats au tableau. Matériel au comptoir. Et on ne crache pas par terre."},"corsa":{"id":"corsa","nom":"Capitaine Corsa la Rouge","titre":"Capitaine pirate de Port-Vérane","description":"Grande femme aux cheveux rouges tressés de perles, sabre courbe, rire tonitruant. Elle a une jambe de bois et elle s'en vante."},"brann":{"id":"brann","nom":"Vieux Brann","titre":"Tavernier du Requin Ivre","description":"Un ancien pirate couvert de tatouages délavés, un perroquet empaillé sur l'épaule.","accueil":"Bienvenue au Requin ! Le rhum est fort, les hamacs tanguent, et les dettes se paient."},"corail":{"id":"corail","nom":"Corail","titre":"Marchande du Marché aux épaves","description":"Une jeune femme sang-dragon aux écailles nacrées, qui sait d'où vient chaque objet et ne le dit jamais.","accueil":"Tout ce que la mer rapporte, je le vends. Le reste, je le garde."},"maree":{"id":"maree","nom":"Marée","titre":"Intendant de la Guilde à Port-Vérane","description":"Un vulpin roux en chemise de marin, qui a le mal de mer et tient pourtant un comptoir flottant.","accueil":"Contrats sur le mât ! Et si je deviens vert, ne vous inquiétez pas, c'est normal."},"sirene":{"id":"sirene","nom":"Néréa","titre":"Sirène du Récif","description":"Une sirène aux cheveux couleur d'algue et à la voix qui donne envie de se jeter à l'eau."},"aureliath":{"id":"aureliath","nom":"Grand Prieur Auréliath","titre":"Ordre de la Lumière Sereine","description":"Crâne rasé, barbe blanche, sourire bienveillant un peu trop parfait."},"rowena":{"id":"rowena","nom":"Dame Rowena","titre":"Maîtresse de la Guilde","description":"Cheveux gris coupés court, cicatrice sur l'œil, pipe éteinte entre les dents."},"edmund-iv":{"id":"edmund-iv","nom":"Edmund IV","titre":"Roi d'Aubeclaire","description":"Couronne lourde, barbe grise, regard fatigué et dur."},"seraphine":{"id":"seraphine","nom":"Séraphine d'Aubeclaire","titre":"Princesse","description":"Longs cheveux blond pâle, petit diadème, robe blanche et or. Seconde de la lignée, espiègle sous l'étiquette."},"elianne":{"id":"elianne","nom":"Sœur Elianne","titre":"Prêtresse","description":"Cheveux noirs au carré sous un voile clair, chapelet de perles bleues. Douce, patiente, têtue quand il s'agit de justice.","accueil":"Que la Lumière vous garde. Le Temple vend peu de choses, mais elles soignent."},"kaya":{"id":"kaya","nom":"Kaya Lunecroc","titre":"Aventurière ourvalis, rang E","description":"Oreilles et queue de loup argentées, bandeau rouge, épée à la hanche. Franche jusqu'à la gaffe."},"vorthak":{"id":"vorthak","nom":"Vorthak","titre":"Émissaire des Cendres","description":"Démon en armure noire aux flammes violettes."},"ferrand":{"id":"ferrand","nom":"Ferrand","titre":"Marchand de reliques","description":"Moustache noire, bagues à tous les doigts, sourire huileux, manteau violet et or trop beau pour son commerce.","accueil":"Un objet dont vous ignorez tout ? Dix pièces, et je vous dis ce qu'il vaut vraiment.","identifie":10},"halvine":{"id":"halvine","nom":"Dame Halvine Corbelet","titre":"Marchande du Comptoir","description":"Petite femme vive aux lunettes rondes, tablier plein de poches, boulier à la main, compte plus vite que lui.","accueil":"Bienvenue au Comptoir ! Regardez tout, touchez peu, et payez comptant."},"bram":{"id":"bram","nom":"Bram","titre":"Tavernier du Chaudron Fêlé","description":"Colosse jovial au crâne lisse et à la grande barbe brune, tablier taché, chope à la main, cœur d'or.","accueil":"Installez-vous ! Ici on mange chaud, et le lit est à l'étage."},"intendant-guilde":{"id":"intendant-guilde","nom":"Maître Barnoul Kestrin","titre":"Intendant de la Guilde","description":"Costaud, peau mate, barbe brune, tablier de cuir, un registre à la main, l'air sévère. Rien ne sort de la réserve sans sa signature.","accueil":"Nom, rang, et ce qu'il vous faut. Tout est noté dans le registre."},"lina":{"id":"lina","nom":"Lina","titre":"Jeune tanneuse","description":"Disparue du quartier des Tanneurs."},"tobin":{"id":"tobin","nom":"Tobin","titre":"Apprenti de l'Ordre","description":"Dix-neuf ans, cheveux roux en bataille, taches de rousseur, un livre toujours sous le bras. Curieux, trop curieux."},"gareth":{"id":"gareth","nom":"Gareth","titre":"Fermier de la Combe-aux-Saules","description":"Mains calleuses, chapeau de paille, salopette bleue et fourche à la main."},"mentor":{"id":"mentor","nom":"Maître Orlo","titre":"Mentor d'enfance","description":"Vieux bibliothécaire bourru."},"rival":{"id":"rival","nom":"Cassian","titre":"Rival d'enfance","description":"Fils de garde, fier et rapide."},"ami-enfance":{"id":"ami-enfance","nom":"Pipa","titre":"Amie d'enfance","description":"Rieuse, intrépide, toujours une égratignure au genou."}},"scenes":{"av-ronde":{"id":"av-ronde","titre":"Aveline — La ronde de nuit","type":"individuel","lieu":"lysmont-place","decor":"lysmont-place","debut":"debut","disponible_si":{"flag":"examen-reussi"},"repetable":false,"romance":false,"pnj":"aveline","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Vous croisez Aveline pendant sa ronde, une lanterne à la main. « Encore debout ? Les héros ne dorment jamais, c'est ça ? »"}],"effets":[],"choix":[{"texte":"« Je pourrais vous accompagner. Deux paires d'yeux valent mieux qu'une. »","visible_si_bloque":false,"effets":[{"affinite":{"aveline":5}}],"aller":"accompagne"},{"texte":"« Et vous, capitaine ? Vous ne dormez jamais non plus. »","visible_si_bloque":false,"effets":[{"affinite":{"aveline":3}}],"aller":"question"},{"texte":"« Ce n'est pas un peu ennuyeux, de tourner en rond toute la nuit ? »","visible_si_bloque":false,"effets":[{"affinite":{"aveline":-2}}],"aller":"vexee"}],"fin":false},"accompagne":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Elle hésite, puis hoche la tête. Vous marchez longtemps en silence. C'est un silence étonnamment agréable."},{"qui":"aveline","expression":"joie","dit":"Au détour d'une rue, elle s'arrête net devant une pâtisserie fermée, le nez presque collé à la vitre. Puis elle se reprend. « Je… vérifiais les serrures. »"}],"effets":[{"flag":"heros:secret-patisserie"}],"choix":[],"suite":"fin","fin":false},"question":{"repliques":[{"qui":"aveline","expression":"tristesse","dit":"« Pas beaucoup, non. » Elle regarde vers le nord. « Quand je ferme les yeux, je vois Valgrane. » Elle n'en dit pas plus."}],"effets":[],"choix":[],"suite":"fin","fin":false},"vexee":{"repliques":[{"qui":"aveline","expression":"colere","dit":"« C'est ce qui permet à la ville de dormir tranquille. » Elle s'éloigne d'un pas raide."}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[],"effets":[],"choix":[],"fin":true}}},"av-entrainement":{"id":"av-entrainement","titre":"Aveline — Leçon d'escrime","type":"individuel","lieu":"chateau","decor":"chateau-trone","debut":"debut","disponible_si":{"flag":"examen-reussi","affinite_min":{"aveline":10}},"repetable":false,"romance":false,"rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Dans la cour du château, Aveline vous lance une épée de bois. « Votre garde est catastrophique. Montrez-moi ce que vous savez faire. »"}],"effets":[],"choix":[{"texte":"Vous battre sérieusement. (Force, difficulté 16)","visible_si_bloque":false,"test":{"carac":"FOR","difficulte":16,"reussite":"gagne","echec":"perd"},"effets":[]},{"texte":"Esquiver et la faire tourner en bourrique. (Agilité, difficulté 16)","visible_si_bloque":false,"test":{"carac":"AGI","difficulte":16,"reussite":"gagne","echec":"perd"},"effets":[]},{"texte":"Tricher : lui jeter du sable aux yeux.","visible_si_bloque":false,"effets":[{"affinite":{"aveline":-6}}],"aller":"triche"}],"fin":false},"gagne":{"repliques":[{"qui":"aveline","expression":"surprise","dit":"Votre lame de bois s'arrête à un doigt de sa gorge. Elle vous fixe, sidérée… puis éclate de rire. Un vrai rire."},{"qui":"aveline","expression":"joie","dit":"« Encore. Demain. Même heure. » Ce n'est pas une question."}],"effets":[{"affinite":{"aveline":7},"xp":40}],"choix":[],"suite":"fin","fin":false},"perd":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Vous voilà sur le dos, sa lame de bois sur votre poitrine. « Pas mal. Pour un débutant. » Elle vous tend la main pour vous relever."}],"effets":[{"affinite":{"aveline":4},"xp":25}],"choix":[],"suite":"fin","fin":false},"triche":{"repliques":[{"qui":"aveline","expression":"colere","dit":"Elle crache le sable, furieuse. « Sur un champ de bataille, peut-être. Ici, c'est une leçon d'honneur. Recommencez quand vous en aurez. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[],"effets":[],"choix":[],"fin":true}}},"av-confidence":{"id":"av-confidence","titre":"Aveline — Ce qu'on ne dit à personne","type":"individuel","lieu":"taverne","decor":"taverne","debut":"debut","disponible_si":{"affinite_palier":{"aveline":"proche"}},"repetable":false,"romance":false,"rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Aveline vous attend au fond de la taverne, devant deux chopes qu'elle n'a pas touchées. « Asseyez-vous. J'ai… quelque chose à vous dire. »"},{"qui":"aveline","expression":"tristesse","dit":"« Mon père, Gauvain de Castelroc, commandait Valgrane. On l'a accusé d'avoir ouvert les portes aux Cendres. On l'a exécuté sans procès. »"},{"qui":"aveline","expression":"neutre","dit":"« Je n'ai jamais cru à sa trahison. Mais les archives militaires de Valgrane ont été scellées… par l'Ordre. Pourquoi l'Ordre ? »"}],"effets":[],"choix":[{"texte":"« Je vous aiderai à découvrir la vérité. Je vous en fais la promesse. »","visible_si_bloque":false,"effets":[{"flag":"heros:promesse-aveline","affinite":{"aveline":8},"quete":{"id":"q-aveline","etape":"archives"}}],"aller":"promesse"},{"texte":"« Et si la vérité ne vous plaisait pas ? »","visible_si_bloque":false,"effets":[{"affinite":{"aveline":3},"quete":{"id":"q-aveline","etape":"archives"}}],"aller":"prudent"}],"fin":false},"promesse":{"repliques":[{"qui":"aveline","expression":"gene","dit":"Elle vous regarde longtemps. Puis, très doucement, elle pose sa main sur la vôtre. « Merci. » Elle la retire aussitôt, écarlate."}],"effets":[],"choix":[],"suite":"fin","fin":false},"prudent":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"« Alors au moins, je saurai. » Elle lève sa chope. « À la vérité, quelle qu'elle soit. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"(Quête de compagnon « Le Serment brisé » : la suite au chapitre 2.)"}],"effets":[],"choix":[],"fin":true}}},"av-remparts":{"id":"av-remparts","titre":"Aveline — Les remparts au crépuscule","type":"individuel","lieu":"chateau","decor":"chateau-trone","debut":"debut","disponible_si":{"affinite_palier":{"aveline":"amoureuse"}},"repetable":false,"romance":true,"rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Le soleil se couche sur Lysmont. Aveline est assise sur le parapet, les jambes dans le vide, sans armure."},{"qui":"aveline","expression":"gene","dit":"« Je ne suis pas douée pour… ça. Les mots. » Elle fixe l'horizon. « Avec une épée, je sais toujours quoi faire. Avec vous, jamais. »"}],"effets":[],"choix":[{"texte":"Vous asseoir à côté d'elle et prendre sa main.","visible_si_bloque":false,"effets":[{"affinite":{"aveline":5}}],"aller":"main"},{"texte":"« Alors ne dites rien. »","visible_si_bloque":false,"effets":[{"affinite":{"aveline":5}}],"aller":"main"}],"fin":false},"main":{"repliques":[{"qui":"aveline","expression":"joie","dit":"Elle rit doucement, nerveusement, et pose la tête sur votre épaule. Le soleil disparaît derrière les tours blanches…"},{"qui":"narrateur","expression":"neutre","dit":"(Fondu au noir.)"}],"effets":[],"choix":[],"fin":true}}},"ch1-appel":{"id":"ch1-appel","titre":"L'Appel","type":"groupe","lieu":"temple-du-seuil","decor":"temple-du-seuil","debut":"debut","disponible_si":{"pas_flag":"appel-fait"},"repetable":false,"romance":false,"quete":"q-ch1-appel","pnj":"aureliath","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Printemps 1012. Un cercle de lumière bleue embrase le sol du Temple du Seuil. Des chants montent, des vitraux vibrent… puis le silence."},{"qui":"narrateur","expression":"neutre","dit":"Au centre du cercle, des silhouettes se relèvent, hagardes : les invoqués. À la lisière de la lumière, d'autres jeunes gens, attirés ici par une résonance qu'ils ne savent pas nommer : les réincarnés.","si":{"origine":"reincarne"}},{"qui":"aureliath","expression":"neutre","dit":"« Bienvenue à Velmaris, [[Appelé||Appelés]]. Je suis Auréliath, Grand Prieur de l'Ordre de la Lumière Sereine. [[N'aie||N'ayez]] crainte : la Lumière [[t'a choisi||vous a choisis]]. »"},{"qui":"aureliath","expression":"neutre","dit":"« Le Souverain des Cendres s'est éveillé au nord. Le Mur d'Aube faiblit. Le royaume a besoin de héros. »"},{"qui":"aveline","expression":"neutre","dit":"Une jeune femme en armure argentée s'avance, la main sur le pommeau. « Capitaine Aveline de Castelroc. Je suis chargée de [[ta||votre]] sécurité. » Son regard s'attarde sur [[toi||vous]], méfiant."}],"effets":[],"choix":[{"texte":"« Un monde de magie ? Génial. Où est-ce qu'on signe ? » (enthousiaste)","visible_si_bloque":false,"effets":[{"reputation":{"ordre":5},"affinite":{"aveline":2}}],"aller":"enthousiaste"},{"texte":"« Personne ne [[m'a demandé mon||nous a demandé notre]] avis. Qui a décidé de [[m'arracher à ma vie||nous arracher à nos vies]] ? » (méfiant)","visible_si_bloque":false,"effets":[{"flag":"mefiance-ordre","reputation":{"ordre":-5},"affinite":{"aveline":4}}],"aller":"mefiant"},{"texte":"« Excusez-moi, il y a des toilettes dans ce monde ? » (humour)","visible_si_bloque":false,"effets":[{"affinite":{"aveline":3}}],"aller":"humour"}],"fin":false},"enthousiaste":{"repliques":[{"qui":"aureliath","expression":"neutre","dit":"Le Grand Prieur sourit largement. « Voilà l'esprit des héros ! »"},{"qui":"aveline","expression":"neutre","dit":"Aveline soupire. « Les derniers à avoir dit ça sont enterrés sous le Mur d'Aube. »"}],"effets":[],"choix":[],"suite":"question","fin":false},"mefiant":{"repliques":[{"qui":"aureliath","expression":"neutre","dit":"Le sourire du Grand Prieur se fige une fraction de seconde. « La Lumière a ses raisons. [[Tu les comprendras||Vous les comprendrez]]. »"},{"qui":"aveline","expression":"neutre","dit":"Aveline [[te||vous]] jette un regard nouveau. Presque… approbateur."}],"effets":[],"choix":[],"suite":"question","fin":false},"humour":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Un acolyte s'étrangle. Auréliath cligne des yeux."},{"qui":"aveline","expression":"joie","dit":"Aveline détourne la tête, mais [[tu l'as||vous l'avez]] vue : elle a souri. « Par ici. Et oui, il y en a. »"}],"effets":[],"choix":[],"suite":"question","fin":false},"question":{"parole_a":{"regle":{"classe":["arcaniste","invocateur","guerisseur","barde","alchimiste"]},"question":{"qui":"aureliath","expression":"neutre","dit":"« {pseudo}. Je sens quelque chose s'éveiller en toi. Dis-moi : que sais-tu de la magie de ce monde ? »"},"reponses":[{"texte":"« Je la sens crépiter au bout de mes doigts. Le feu, le givre… ils me répondent déjà. »","si":{"classe":"arcaniste"},"effets":[{"reputation":{"ordre":3}}],"aller":"suite"},{"texte":"« Quelque chose m'accompagne depuis mon arrivée. Une présence, à mes côtés. »","si":{"classe":"invocateur"},"effets":[{"reputation":{"ordre":2}}],"aller":"suite"},{"texte":"« Je sais seulement que mes mains apaisent la douleur. Le reste, je l'apprendrai. »","si":{"classe":"guerisseur"},"effets":[{"reputation":{"ordre":4}}],"aller":"suite"},{"texte":"« La magie ? Chez moi, ça s'appelle une bonne chanson au bon moment. »","si":{"classe":"barde"},"effets":[{"affinite":{"aveline":1}}],"aller":"suite"},{"texte":"« De la magie ? Montrez-moi vos fioles, je vous dirai ce que j'en pense. »","si":{"classe":"alchimiste"},"effets":[{"reputation":{"ordre":1}}],"aller":"suite"},{"texte":"« Je préfère l'acier. La magie, je la laisse à ceux qui ont le temps de réciter. »","si":{"classe":["lame-runique","gardien","berserker","ombre","archer"]},"effets":[{"affinite":{"aveline":2}}],"aller":"suite"},{"texte":"« Les anciens parlent du Voile et de ses dangers. Je sais qu'on ne joue pas avec. »","si":{"race":["elfe","demi-elfe"]},"effets":[{"flag":"mefiance-ordre"}],"aller":"suite"},{"texte":"« Rien du tout. Mais j'apprends vite. »","effets":[{"reputation":{"ordre":1}}],"aller":"suite"},{"texte":"« Assez pour me méfier de ceux qui s'en servent sur les autres sans demander. »","effets":[{"reputation":{"ordre":-3},"affinite":{"aveline":2}}],"aller":"suite"},{"texte":"« Ça dépend. Elle fait aussi le café ? »","effets":[{"affinite":{"aveline":1}}],"aller":"suite"}]},"repliques":[{"qui":"aureliath","expression":"neutre","dit":"Le Grand Prieur lève une main. Son regard [[te détaille longuement||parcourt vos visages un à un, puis s'arrête]]."}],"effets":[],"choix":[],"fin":false},"suite":{"repliques":[{"qui":"aureliath","expression":"neutre","dit":"« [[Repose-toi||Reposez-vous]]. Demain, la Couronne [[te||vous]] recevra. En attendant, la Guilde de la Rose des Vents [[t'ouvrira ses portes : tu y apprendras||vous ouvrira ses portes : vous y apprendrez]] à survivre. »"},{"qui":"narrateur","expression":"neutre","dit":"Ce soir-là, en contemplant les tours blanches de Lysmont depuis la fenêtre du temple, [[tu vois flotter devant tes yeux une fenêtre translucide : ton niveau, tes capacités… et ton don.||chacun de vous voit flotter devant ses yeux une fenêtre translucide : votre niveau, vos capacités… et votre don.]]"}],"effets":[{"flag":["appel-fait","aveline-rencontree"],"quete":{"id":"q-ch1-appel","etape":"examen"},"recruter":"aveline","journal":"L'Appel : {groupe} arrivent au Temple du Seuil. La capitaine Aveline de Castelroc est chargée de leur sécurité."}],"choix":[],"fin":true}}},"ch1-examen":{"id":"ch1-examen","titre":"L'examen de la Guilde","type":"groupe","lieu":"guilde","decor":"guilde","debut":"debut","disponible_si":{"quete_etape":{"q-ch1-appel":"examen"}},"repetable":false,"romance":false,"quete":"q-ch1-appel","pnj":"rowena","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le hall de la Guilde de la Rose des Vents sent la bière, le cuir et la sueur. Des dizaines de regards se tournent vers vous."},{"qui":"rowena","expression":"neutre","dit":"« Ah. [[Un Appelé||Les Appelés]]. » Dame Rowena mâchonne sa pipe éteinte. « Ici, [[ton don ne vaut rien tant que tu n'as pas prouvé que tu sais||votre don ne vaut rien tant que vous n'avez pas prouvé que vous savez]] tenir debout. »"},{"qui":"kaya","expression":"neutre","dit":"Une jeune femme aux oreilles de loup argentées [[te||vous]] dévisage, adossée à un pilier. « Pff. [[Il a l'air tout mou||Ils ont l'air tout mous]]. Je parie dix pièces [[qu'il tombe||qu'ils tombent]] au premier coup. »"},{"qui":"kaya","expression":"neutre","dit":"Elle vous fixe un instant de plus, puis son regard s'adoucit. « …Un Ourvalis ? Hé. Bonne chance, alors. »","si":{"race":"ourvalis"}},{"qui":"rowena","expression":"neutre","dit":"« L'examen est simple : [[tu affrontes||vous affrontez]] notre golem d'entraînement. S'il [[te||vous]] met au tapis, [[reviens||revenez]] dans un an. »"}],"effets":[],"choix":[],"suite":"pari","fin":false},"pari":{"pari":{"mise":20,"gain":2,"flag":"pari-kaya","aller":"conseil","personne":"sans-pari"},"repliques":[{"qui":"kaya","expression":"neutre","dit":"Kaya fait sauter une pièce dans sa main. « Allez, soyons joueurs. Vingt pièces, pour [[toi||tout le groupe]], que [[tu ne tiens||vous ne tenez]] pas debout jusqu'au bout. [[Tu suis||Qui suit]] ? »"}],"effets":[],"choix":[],"fin":false},"sans-pari":{"repliques":[{"qui":"kaya","expression":"neutre","dit":"« Personne ne parie ? Tss. Prudent[[||s]], en plus d'être mou[[||s]]. » Elle range sa pièce, presque déçue."}],"effets":[],"choix":[],"suite":"conseil","fin":false},"conseil":{"parole_a":{"regle":{"classe":["lame-runique","gardien","berserker","ombre","archer"]},"question":{"qui":"rowena","expression":"neutre","dit":"Rowena pointe sa pipe vers {nom}. « Toi, {pseudo}. Ce golem fait deux fois ta taille. Tu comptes t'y prendre comment ? »"},"reponses":[{"texte":"« Je me mets devant et j'encaisse. [[Je frapperai quand il fatiguera.||Les autres frapperont pendant ce temps.]] »","si":{"classe":"gardien"},"effets":[{"reputation":{"guilde":3}}],"aller":"combat"},{"texte":"« Je cogne fort. Et s'il tient encore debout, je recommence. »","si":{"classe":["berserker","lame-runique"]},"effets":[{"reputation":{"guilde":2}}],"aller":"combat"},{"texte":"« Je cherche le point faible. Tout le monde en a un, même l'argile. »","si":{"classe":["ombre","archer"]},"effets":[{"reputation":{"guilde":3}}],"aller":"combat"},{"texte":"« De loin. Très loin. Avec quelque chose qui explose. »","si":{"classe":["arcaniste","invocateur","alchimiste"]},"effets":[{"reputation":{"guilde":2}}],"aller":"combat"},{"texte":"« Je tiens debout plus longtemps que lui.[[|| Et je garde les autres debout.]] »","si":{"classe":["guerisseur","barde"]},"effets":[{"reputation":{"guilde":2}}],"aller":"combat"},{"texte":"« Avec prudence. Je regarde d'abord comment il bouge. »","effets":[{"reputation":{"guilde":2}}],"aller":"combat"},{"texte":"« On verra bien une fois dedans. »","effets":[{"reputation":{"guilde":1}}],"aller":"combat"},{"texte":"« Vous n'auriez pas un golem plus petit ? »","effets":[{"reputation":{"guilde":1}}],"aller":"combat"}]},"repliques":[],"effets":[],"choix":[],"fin":false},"combat":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le golem d'argile se met en marche dans un grincement."}],"effets":[],"choix":[],"combat":{"rencontre":"examen-guilde","victoire":"victoire","defaite":"defaite"},"fin":false},"victoire":{"repliques":[{"qui":"rowena","expression":"neutre","dit":"« Pas mal. Pas mal du tout. » Elle tamponne une carte de cuivre. « Rang F. Les contrats sont au tableau. Ne mourez pas bêtement. »"},{"qui":"kaya","expression":"neutre","dit":"Kaya rend la mise et y ajoute vingt pièces de sa poche, en grommelant. « Ouais, bon. [[Tu as||Vous avez]] de la chance. »","si":{"flag":"pari-kaya"}}],"effets":[{"gain_pari":2},{"flag":"examen-reussi","points_guilde":50,"quete":{"id":"q-ch1-appel","etape":"crypte"},"journal":"{groupe} réussissent l'examen de la Guilde : rang F."}],"choix":[],"suite":"ellipse","fin":false},"defaite":{"repliques":[{"qui":"rowena","expression":"neutre","dit":"« Bon. Le golem [[t'a laminé||vous a laminés]]. » Elle soupire. « Mais [[tu t'es relevé||vous vous êtes relevés]]. C'est ce que je cherche. Rang F, à l'essai. »"},{"qui":"kaya","expression":"neutre","dit":"Kaya empoche les vingt pièces avec un grand sourire. « Sans rancune. »","si":{"flag":"pari-kaya"}}],"effets":[{"perte_pari":true},{"flag":"examen-reussi","points_guilde":20,"quete":{"id":"q-ch1-appel","etape":"crypte"},"journal":"{groupe} entrent à la Guilde « à l'essai »."}],"choix":[],"suite":"ellipse","fin":false},"ellipse":{"repliques":[{"qui":"rowena","expression":"neutre","dit":"« Maintenant, au travail : contrats, entraînement, premières cicatrices. Et quand vous voudrez que les mois passent, prenez une chambre au Chaudron Fêlé. Le temps ne file que si vous le décidez. »"},{"qui":"aveline","expression":"neutre","dit":"Aveline passera souvent « par hasard » à la Guilde. Officiellement pour vous surveiller."},{"qui":"narrateur","expression":"neutre","dit":"On raconte que des lueurs étranges apparaissent parfois sous les ruines de la Crypte de la Fontaine, à l'automne. La Guilde vous y enverra en Brumaire 1013."}],"effets":[],"choix":[],"fin":true}}},"ch1-crypte":{"id":"ch1-crypte","titre":"La Crypte de la Fontaine","type":"groupe","lieu":"crypte-fontaine","decor":"crypte-entree","debut":"debut","disponible_si":{"quete_etape":{"q-ch1-appel":"crypte"},"date_min":{"annee":1013,"mois":7,"jour":1}},"repetable":false,"romance":false,"quete":"q-ch1-appel","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"L'automne est là. Des paysans ont vu des lueurs violettes sous les ruines de la Crypte de la Fontaine. Rowena [[t'a||vous a]] confié l'affaire."},{"qui":"aveline","expression":"neutre","dit":"Aveline [[t'attend||vous attend]] à l'entrée, en armure complète. « Ordre du roi : je [[t'accompagne||vous accompagne]]. Et… je n'allais pas [[te laisser descendre seul||vous laisser descendre seuls]]. »"},{"qui":"narrateur","expression":"neutre","dit":"L'escalier s'enfonce dans le noir. Une odeur d'eau croupie et de vieille pierre monte des profondeurs."}],"effets":[],"choix":[{"texte":"Descendre dans la crypte.","visible_si_bloque":false,"effets":[],"aller":"avant-descente"}],"fin":false},"avant-descente":{"parole_a":{"regle":{"classe":["ombre","archer","gardien"]},"question":{"qui":"aveline","expression":"neutre","dit":"Aveline s'arrête sur la première marche et se tourne vers {nom}. « {pseudo}, c'est toi qui ouvres la marche, ou c'est moi ? »"},"reponses":[{"texte":"« Moi. Je passe devant, sans bruit. Si quelque chose bouge, je le verrai avant qu'il nous voie. »","si":{"classe":"ombre"},"effets":[{"affinite":{"aveline":2}}],"aller":"donjon"},{"texte":"« Moi. Mon bouclier d'abord, tout le monde derrière. »","si":{"classe":"gardien"},"effets":[{"affinite":{"aveline":3}}],"aller":"donjon"},{"texte":"« Passe devant. Je couvre depuis l'arrière, une flèche encochée. »","si":{"classe":"archer"},"effets":[{"affinite":{"aveline":1}}],"aller":"donjon"},{"texte":"« Un escalier sous terre ? Laisse faire un nain. »","si":{"race":"nain"},"effets":[{"affinite":{"aveline":2}}],"aller":"donjon"},{"texte":"« Je vois dans le noir. Je guide, tu me suis. »","si":{"race":"elfe"},"effets":[{"affinite":{"aveline":2}}],"aller":"donjon"},{"texte":"« Ensemble, côte à côte. »","effets":[{"affinite":{"aveline":2}}],"aller":"donjon"},{"texte":"« Après toi, capitaine. C'est toi qui as l'armure. »","effets":[{"affinite":{"aveline":1}}],"aller":"donjon"},{"texte":"« On tire à pile ou face ? »","effets":[{"affinite":{"aveline":1}}],"aller":"donjon"}]},"repliques":[],"effets":[],"choix":[],"fin":false},"donjon":{"repliques":[],"effets":[],"choix":[],"donjon":{"id":"crypte-fontaine","sortie":"sortie"},"fin":false},"sortie":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous remontez à la surface, couverts de poussière. Dans votre sac, le sceau cendré pulse d'une lumière violette, comme un cœur."},{"qui":"aveline","expression":"colere","dit":"« Ce symbole… » Aveline pâlit. « On l'a trouvé sur les ruines de Valgrane, il y a dix ans. Le jour où mon père… » Elle se tait."}],"effets":[{"flag":"sceau-trouve","xp":60,"quete":{"id":"q-ch1-appel","etape":"lanternes"},"journal":"Dans la Crypte de la Fontaine, {groupe} découvrent un sceau cendré."}],"choix":[{"texte":"Remettre le sceau à l'Ordre, comme le veut la loi.","visible_si_bloque":false,"effets":[{"flag":"sceau-ordre","reputation":{"ordre":10}}],"aller":"ellipse"},{"texte":"Le confier à la Guilde : Rowena saura quoi en faire.","visible_si_bloque":false,"effets":[{"flag":"sceau-guilde","reputation":{"guilde":10}}],"aller":"ellipse"},{"texte":"Le garder et l'étudier vous-mêmes, en secret.","visible_si_bloque":false,"effets":[{"flag":"sceau-garde","affinite":{"aveline":2}}],"aller":"ellipse"}],"fin":false},"ellipse":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"L'hiver approche. Le sceau ne quitte pas vos pensées. Toute la ville parle déjà de la prochaine Fête des Lanternes, le 15 Floréal 1014."}],"effets":[],"choix":[],"fin":true}}},"ch1-lanternes":{"id":"ch1-lanternes","titre":"La Nuit des Lanternes","type":"groupe","lieu":"lysmont-place","decor":"lysmont-lanternes-nuit","debut":"debut","disponible_si":{"quete_etape":{"q-ch1-appel":"lanternes"},"date_min":{"annee":1014,"mois":2,"jour":15}},"repetable":false,"romance":false,"quete":"q-ch1-appel","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"15 Floréal 1014, Fête des Lanternes. Des milliers de lanternes de papier s'élèvent au-dessus de Lysmont, chacune portant le nom d'un disparu."},{"qui":"bram","expression":"neutre","dit":"Bram, le tavernier, distribue des brochettes en riant. « Ce soir, c'est la maison qui régale ! »","si":{"pas_flag":"mort:bram"}},{"qui":"seraphine","expression":"neutre","dit":"Sur le balcon du château, une jeune femme blonde vous fait un petit signe discret. La princesse Séraphine."},{"qui":"aveline","expression":"neutre","dit":"Aveline est là elle aussi, en civil pour une fois, une lanterne éteinte entre les doigts."},{"qui":"aveline","expression":"gene","dit":"« C'est… pour mon père. » Elle hésite, sans vous regarder. « Vous voulez bien rester un moment ? »","si":{"affinite_min":{"aveline":20}}}],"effets":[],"choix":[{"texte":"Lâcher une lanterne avec Aveline, en silence.","si":{"affinite_min":{"aveline":20}},"visible_si_bloque":false,"effets":[{"flag":"heros:lanterne-aveline","affinite":{"aveline":6}}],"aller":"lanterne"},{"texte":"Profiter de la fête : danses, musique, brochettes.","visible_si_bloque":false,"effets":[{"affinite":{"aveline":1}}],"aller":"attaque"}],"fin":false},"lanterne":{"repliques":[{"qui":"aveline","expression":"tristesse","dit":"Vos lanternes montent côte à côte. Aveline murmure : « Il s'appelait Gauvain. Il n'était pas un traître. » Pour la première fois, sa voix tremble."},{"qui":"aveline","expression":"gene","dit":"Elle s'essuie les yeux d'un revers de main. « …Merci. N'en parlez à personne. »"}],"effets":[],"choix":[],"suite":"attaque","fin":false},"attaque":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Soudain, les lanternes virent au violet. Un cri. Puis une explosion de cendres au centre de la place."},{"qui":"narrateur","expression":"neutre","dit":"Des gobelins cendrés surgissent des égouts, guidés par des cultistes. La foule panique."},{"qui":"aveline","expression":"colere","dit":"« Protégez les civils ! » hurle Aveline en dégainant."}],"effets":[],"choix":[{"texte":"Couvrir la fuite des civils, même si les cultistes s'échappent.","visible_si_bloque":false,"effets":[{"flag":"civils-proteges","reputation":{"couronne":5},"affinite":{"aveline":5}}],"aller":"combat1"},{"texte":"Foncer sur le cultiste qui dirige l'attaque, coûte que coûte.","visible_si_bloque":false,"effets":[{"flag":["heros:civils-abandonnes","cultiste-poursuivi"],"reputation":{"guilde":5}}],"aller":"combat1"}],"fin":false},"combat1":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"lanternes-cultistes","victoire":"vorthak","defaite":"defaite1"},"fin":false},"defaite1":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous tombez sous le nombre. Quand vous rouvrez les yeux, la garde a repoussé les gobelins… mais le Chaudron Fêlé est en flammes."}],"effets":[{"pnj_mort":"bram"}],"choix":[],"suite":"vorthak","fin":false},"vorthak":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les flammes s'ouvrent. Une silhouette en armure noire s'avance, une épée nimbée de feu violet à la main."},{"qui":"vorthak","expression":"neutre","dit":"« Alors c'est vous, les nouveaux jouets de l'Ordre. » Il rit. « Le Souverain m'a demandé de vous saluer. »"},{"qui":"vorthak","expression":"neutre","dit":"« Le sceau. Vous l'avez. Je le sens. Rendez-le-moi, et je laisse vivre cette ville une année de plus. »","si":{"flag":"sceau-garde"}}],"effets":[],"choix":[{"texte":"« Viens le chercher. »","visible_si_bloque":false,"effets":[],"aller":"combat2"},{"texte":"« Pourquoi vous attaquez Lysmont ? Qu'est-ce que vous voulez vraiment ? » (Esprit, difficulté 17)","visible_si_bloque":false,"test":{"carac":"ESP","difficulte":17,"reussite":"revelation","echec":"combat2"},"effets":[]}],"fin":false},"revelation":{"repliques":[{"qui":"vorthak","expression":"neutre","dit":"Il incline la tête, amusé. « Ce que nous voulons ? Demandez à votre Grand Prieur combien coûte un Appel. Demandez-lui qui paie. »"}],"effets":[{"flag":"indice-prix-appel"}],"choix":[],"suite":"combat2","fin":false},"combat2":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"lanternes-vorthak","victoire":"victoire","defaite":"defaite2"},"fin":false},"victoire":{"repliques":[{"qui":"vorthak","expression":"neutre","dit":"Vorthak recule, son armure fendue. « Intéressant… très intéressant. » Il disparaît dans un tourbillon de cendres."},{"qui":"aveline","expression":"joie","dit":"Aveline s'appuie sur son épée, essoufflée, et vous regarde avec un sourire épuisé. « Vous… vous avez été incroyables. »"}],"effets":[{"reputation":{"couronne":10,"guilde":5},"affinite":{"aveline":4}}],"choix":[],"suite":"bilan","fin":false},"defaite2":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vorthak vous balaie comme des fétus de paille, puis s'en va, l'air ennuyé. « Revenez quand vous serez dignes de mon temps. »"}],"effets":[{"reputation":{"couronne":-5}}],"choix":[],"suite":"bilan","fin":false},"bilan":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"À l'aube, Lysmont compte ses morts. Les lanternes calcinées jonchent les pavés."},{"qui":"bram","expression":"neutre","dit":"Bram, couvert de suie, vous serre la main à vous broyer les os. « Vous avez sauvé ma taverne. Ici, vous ne paierez plus jamais une bière. »","si":{"flag":"civils-proteges","pas_flag":"mort:bram"}},{"qui":"narrateur","expression":"neutre","dit":"Le Chaudron Fêlé n'est plus que cendres. Bram n'a pas survécu.","si":{"flag":"mort:bram"}}],"effets":[{"flag":"lanternes-faites","quete":{"id":"q-ch1-appel","etape":"serment"},"journal":"Fête des Lanternes : Vorthak, émissaire des Cendres, attaque Lysmont."}],"choix":[],"fin":true}}},"ch1-serment":{"id":"ch1-serment","titre":"Le Serment","type":"groupe","lieu":"chateau","decor":"chateau-trone","debut":"debut","disponible_si":{"quete_etape":{"q-ch1-appel":"serment"},"date_min":{"annee":1014,"mois":10,"jour":3}},"repetable":false,"romance":false,"quete":"q-ch1-appel","pnj":"edmund-iv","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Nivôse 1014. La salle du trône est glaciale. Le roi Edmund IV vous toise depuis son trône doré."},{"qui":"edmund-iv","expression":"neutre","dit":"« Vous avez défendu ma capitale. Bien. Mais un héros sans maître est une épée sans fourreau : dangereux. »"},{"qui":"edmund-iv","expression":"neutre","dit":"« Agenouillez-vous et jurez fidélité à la Couronne. Vous aurez titres, or, et l'honneur de mourir pour Aubeclaire. »"},{"qui":"seraphine","expression":"neutre","dit":"La princesse Séraphine, debout à côté du trône, serre les poings. Elle croise votre regard et secoue très légèrement la tête."},{"qui":"aveline","expression":"neutre","dit":"Aveline, au garde-à-vous, fixe un point droit devant elle. Mais ses jointures blanchissent sur son épée."}],"effets":[],"choix":[{"texte":"Jurer fidélité à la Couronne.","visible_si_bloque":false,"effets":[{"flag":"serment-couronne","reputation":{"couronne":15,"guilde":-5},"affinite":{"aveline":2}}],"aller":"jure"},{"texte":"Refuser poliment : vous resterez des aventuriers libres, fidèles à la Guilde.","visible_si_bloque":false,"effets":[{"flag":"independants","reputation":{"couronne":-10,"guilde":15}}],"aller":"refus"},{"texte":"Négocier : une alliance d'égal à égal, pas un serment de vassal. (Charisme, difficulté 18)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":18,"reussite":"negociation","echec":"negociation-ratee"},"effets":[]},{"texte":"Faire semblant de jurer, en croisant les doigts dans votre dos.","visible_si_bloque":false,"effets":[{"flag":["serment-couronne","heros:parole-trahie"],"reputation":{"couronne":10}}],"aller":"faux"}],"fin":false},"jure":{"repliques":[{"qui":"edmund-iv","expression":"neutre","dit":"« Relevez-vous, chevaliers d'Aubeclaire. » Le roi sourit enfin. Séraphine détourne les yeux."}],"effets":[],"choix":[],"suite":"epilogue","fin":false},"refus":{"repliques":[{"qui":"edmund-iv","expression":"neutre","dit":"Un silence de mort. « …Soit. La Guilde répondra de vous. Ne me décevez pas. »"},{"qui":"seraphine","expression":"neutre","dit":"En sortant, Séraphine vous rattrape dans un couloir. « C'était courageux. Ou stupide. Les deux me plaisent. »"}],"effets":[],"choix":[],"suite":"epilogue","fin":false},"negociation":{"repliques":[{"qui":"edmund-iv","expression":"neutre","dit":"Le roi plisse les yeux… puis éclate d'un rire bref. « Vous avez du cran. Une alliance, donc. Mais je m'en souviendrai. »"}],"effets":[{"flag":"allies-libres","reputation":{"couronne":5,"guilde":5}}],"choix":[],"suite":"epilogue","fin":false},"negociation-ratee":{"repliques":[{"qui":"edmund-iv","expression":"neutre","dit":"« Des conditions ? À MOI ? » Le roi se lève, furieux. « Hors de ma vue ! »"}],"effets":[{"flag":"independants","reputation":{"couronne":-15,"guilde":10}}],"choix":[],"suite":"epilogue","fin":false},"faux":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous prononcez les mots du serment. Personne ne remarque vos doigts croisés… sauf Aveline, juste derrière vous. Son visage se ferme."}],"effets":[],"choix":[],"suite":"epilogue","fin":false},"epilogue":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Ce soir-là, sur les remparts, vous regardez les étoiles d'un ciel qui n'est pas le vôtre."},{"qui":"aveline","expression":"neutre","dit":"« Le printemps prochain, on m'envoie à la frontière sud. » Aveline hésite. « J'aimerais… que vous veniez. » Elle rougit. « Pour la mission, évidemment. »","si":{"affinite_min":{"aveline":35}}},{"qui":"narrateur","expression":"neutre","dit":"Deux ans ont passé depuis l'Appel. Velmaris n'est plus un monde étranger : c'est le vôtre, désormais. Et il brûle déjà au nord."}],"effets":[{"xp":150,"terminer_quete":"q-ch1-appel"},{"fin_chapitre":1}],"choix":[],"fin":true}}},"sq-loups-guilde":{"id":"sq-loups-guilde","titre":"Les loups de la Combe : l'affaire","type":"groupe","lieu":"guilde","decor":"guilde","debut":"debut","disponible_si":{"flag":"examen-reussi","pas_flag":"loups-acceptes"},"repetable":false,"romance":false,"quete":"q-loups","pnj":"rowena","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"rowena","expression":"neutre","dit":"« Un fermier de la Combe-aux-Saules, Gareth, perd ses moutons. Il n'a pas de quoi payer un vrai contrat, alors personne n'y va. » Rowena [[te||vous]] regarde par-dessus sa pipe. « Sauf si ça [[t'intéresse||vous intéresse]]. »"}],"effets":[],"choix":[{"texte":"« [[J'y vais||On y va]]. »","visible_si_bloque":false,"effets":[{"flag":"loups-acceptes","quete":{"id":"q-loups","etape":"ferme"}}],"aller":"accepte"}],"fin":false},"accepte":{"repliques":[{"qui":"rowena","expression":"neutre","dit":"« La ferme est au sud-ouest, à l'entrée de la Combe. Et [[reviens||revenez]] me dire comment ça s'est fini. »"}],"effets":[],"choix":[],"fin":true}}},"sq-loups-ferme":{"id":"sq-loups-ferme","titre":"Les loups de la Combe : la ferme de Gareth","type":"groupe","lieu":"combe-aux-saules","decor":"combe-aux-saules","debut":"debut","disponible_si":{"quete_etape":{"q-loups":"ferme"}},"repetable":false,"romance":false,"quete":"q-loups","pnj":"gareth","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"gareth","expression":"neutre","dit":"« Trois moutons cette semaine ! Et hier, ma petite Rose a vu des yeux jaunes à la lisière. » Gareth tord son chapeau de paille entre ses mains."},{"qui":"gareth","expression":"neutre","dit":"« Les traces partent de l'enclos vers les ronces, là-bas. Moi, je n'ose plus y aller. »"}],"effets":[{"quete":{"id":"q-loups","etape":"traces"}}],"choix":[],"fin":true}}},"sq-loups-traces":{"id":"sq-loups-traces","titre":"Les loups de la Combe : les traces","type":"groupe","lieu":"combe-lisiere","decor":"combe-aux-saules","debut":"debut","disponible_si":{"quete_etape":{"q-loups":"traces"}},"repetable":false,"romance":false,"quete":"q-loups","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"À la lisière, la terre est retournée. Des empreintes larges comme une main… et d'autres, toutes petites, à côté."}],"effets":[],"choix":[{"texte":"Suivre les grandes empreintes.","visible_si_bloque":false,"effets":[],"aller":"grandes"},{"texte":"Regarder de plus près les petites.","visible_si_bloque":false,"effets":[{"flag":"louveteaux-vus"}],"aller":"petites"}],"fin":false},"grandes":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La piste est franche : elle file droit vers un énorme saule, au fond de la Combe."}],"effets":[{"quete":{"id":"q-loups","etape":"taniere"}}],"choix":[],"fin":true},"petites":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Des louveteaux. La meute ne chasse pas par plaisir : elle nourrit ses petits. La piste mène à un énorme saule, au fond de la Combe."}],"effets":[{"xp":10,"quete":{"id":"q-loups","etape":"taniere"}}],"choix":[],"fin":true}}},"sq-loups":{"id":"sq-loups","titre":"Les loups de la Combe : le vieux saule","type":"groupe","lieu":"combe-taniere","decor":"combe-aux-saules","debut":"debut","disponible_si":{"quete_etape":{"q-loups":"taniere"}},"repetable":false,"romance":false,"quete":"q-loups","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Une tanière s'ouvre sous les racines du vieux saule. Des grognements… et des gémissements plus aigus : des louveteaux."}],"effets":[],"choix":[{"texte":"Attaquer la meute.","visible_si_bloque":false,"effets":[],"aller":"combat"},{"texte":"Utiliser votre don pour parler à la louve. (Langue universelle)","si":{"don":"langue-universelle"},"visible_si_bloque":false,"effets":[],"aller":"parler"},{"texte":"Effrayer la meute avec du feu et du bruit pour la faire partir. (Force, difficulté 16)","visible_si_bloque":false,"test":{"carac":"FOR","difficulte":16,"reussite":"fuite","echec":"combat"},"effets":[]}],"fin":false},"parler":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La louve vous écoute, babines retroussées. Puis, lentement, elle comprend : les fermiers, les pièges, les bois plus au sud où le gibier abonde."},{"qui":"narrateur","expression":"neutre","dit":"À l'aube, la meute est partie. Gareth n'en croit pas ses yeux."}],"effets":[{"flag":"loups-sauves","xp":80}],"choix":[],"suite":"fin","fin":false},"fuite":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Torches, cris, casseroles : la meute détale vers le sud avec ses petits. Aucun sang versé."}],"effets":[{"flag":"loups-sauves","xp":60}],"choix":[],"suite":"fin","fin":false},"combat":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"loups-alpha","victoire":"victoire","defaite":"defaite"},"fin":false},"victoire":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La meute est décimée. Les louveteaux s'enfuient dans les fourrés."}],"effets":[],"choix":[],"suite":"fin","fin":false},"defaite":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les loups vous repoussent. Gareth vous traîne jusqu'à sa ferme et vous soigne avec une soupe épaisse. « On réessaiera. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le calme revient sur la Combe. Il reste à prévenir Gareth… et Rowena, à la Guilde."}],"effets":[{"quete":{"id":"q-loups","etape":"retour"}}],"choix":[],"fin":true}}},"sq-loups-retour":{"id":"sq-loups-retour","titre":"Les loups de la Combe : le compte rendu","type":"groupe","lieu":"guilde","decor":"guilde","debut":"debut","disponible_si":{"quete_etape":{"q-loups":"retour"}},"repetable":false,"romance":false,"quete":"q-loups","pnj":"rowena","rend_quete":true,"noeuds":{"debut":{"repliques":[{"qui":"rowena","expression":"neutre","dit":"« Alors, ces loups ? »"},{"qui":"rowena","expression":"neutre","dit":"« Partis sans une goutte de sang ? » Elle hausse un sourcil. « C'est rare, ça. Et ça me plaît. »","si":{"flag":"loups-sauves"}},{"qui":"gareth","expression":"neutre","dit":"Gareth a fait le chemin jusqu'à la Guilde, son chapeau à la main. « Merci, du fond du cœur. Tenez, c'est pas grand-chose, mais c'est honnête. »"}],"effets":[{"reputation":{"guilde":3},"or":25,"points_guilde":30,"terminer_quete":"q-loups"}],"choix":[],"fin":true}}},"sq-reliques":{"id":"sq-reliques","titre":"Le marchand de reliques","type":"groupe","lieu":"taverne","decor":"taverne","debut":"debut","disponible_si":{"flag":"examen-reussi"},"repetable":false,"romance":false,"quete":"q-reliques","pnj":"ferrand","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"ferrand","expression":"neutre","dit":"« Approchez, approchez ! Un os authentique de Saint Aldebrand, le Premier Appelé ! Il guérit les fièvres et porte chance aux aventuriers. Cent pièces seulement ! »"},{"qui":"bram","expression":"neutre","dit":"Bram lève les yeux au ciel derrière son comptoir. « Ça fait trois semaines qu'il vend des os de poulet. »","si":{"pas_flag":"mort:bram"}}],"effets":[{"quete":{"id":"q-reliques","etape":"enqueter"}}],"choix":[{"texte":"Examiner la « relique » de près. (Intelligence, difficulté 15)","visible_si_bloque":false,"test":{"carac":"INT","difficulte":15,"reussite":"demasque","echec":"rate"},"effets":[]},{"texte":"L'acheter. On ne sait jamais.","si":{"or_min":100},"visible_si_bloque":false,"effets":[{"or":-100,"objet":"relique-douteuse"}],"aller":"achete"},{"texte":"Aller prévenir l'Ordre : vendre de fausses reliques est un crime.","visible_si_bloque":false,"effets":[],"aller":"ordre"}],"fin":false},"demasque":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Un os de poulet, verni et gravé à la hâte. Vous le brandissez sous le nez des clients. Rires, huées : Ferrand s'enfuit sous les quolibets."}],"effets":[{"flag":"ferrand-demasque","reputation":{"guilde":5},"xp":50}],"choix":[],"suite":"fin","fin":false},"rate":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"L'os a l'air… vrai ? Vous n'en êtes pas sûrs. Ferrand vous adresse un clin d'œil satisfait."}],"effets":[],"choix":[],"suite":"fin","fin":false},"achete":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Ferrand empoche l'or avec un sourire radieux. La relique sent vaguement le poulet rôti."}],"effets":[],"choix":[],"suite":"fin","fin":false},"ordre":{"repliques":[{"qui":"elianne","expression":"neutre","dit":"Sœur Elianne arrive en personne, le visage grave. « Ces escrocs salissent la mémoire des Appelés. Merci. » Ferrand est emmené par deux gardes."}],"effets":[{"flag":"ferrand-arrete","reputation":{"ordre":8},"xp":40}],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[],"effets":[{"points_guilde":15,"terminer_quete":"q-reliques"}],"choix":[],"fin":true}}},"sq-tanneurs-plainte":{"id":"sq-tanneurs-plainte","titre":"Les disparus des Tanneurs : la plainte","type":"groupe","lieu":"quartier-tanneurs","decor":"quartier-tanneurs","debut":"debut","disponible_si":{"flag":"examen-reussi","pas_flag":"tanneurs-commence"},"repetable":false,"romance":false,"quete":"q-tanneurs","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les ruelles des Tanneurs sentent l'urine et la teinture. Une mère [[t'agrippe||vous agrippe]] le bras : « Ma fille, Lina. Partie chercher de l'eau il y a trois jours. »"},{"qui":"narrateur","expression":"neutre","dit":"« La garde ne vient plus ici. Je n'ai que [[toi||vous]]. »"}],"effets":[{"flag":"tanneurs-commence","quete":{"id":"q-tanneurs","etape":"piste"}}],"choix":[],"fin":true}}},"sq-tanneurs-piste":{"id":"sq-tanneurs-piste","titre":"Les disparus des Tanneurs : la piste","type":"groupe","lieu":"quartier-tanneurs","decor":"quartier-tanneurs","debut":"debut","disponible_si":{"quete_etape":{"q-tanneurs":"piste"}},"repetable":false,"romance":false,"quete":"q-tanneurs","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Près du puits, un seau renversé. Des traces de pas, une odeur de soufre."},{"qui":"narrateur","expression":"neutre","dit":"Et, gravé sur une porte, un symbole violet que [[tu commences||vous commencez]] à connaître.","si":{"flag":"sceau-trouve"}}],"effets":[],"choix":[{"texte":"Suivre la piste de soufre. (Esprit, difficulté 14)","visible_si_bloque":false,"test":{"carac":"ESP","difficulte":14,"reussite":"piste","echec":"retard"},"effets":[]},{"texte":"Interroger les ivrognes du coin, avec quelques pièces. (Charisme, difficulté 13)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":13,"reussite":"piste","echec":"retard"},"effets":[]}],"fin":false},"piste":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La piste mène à une tannerie abandonnée, au bout de la ruelle. Sous la trappe de la cave : des chants étouffés."}],"effets":[{"flag":"tanneurs-piste-fraiche","quete":{"id":"q-tanneurs","etape":"cave"}}],"choix":[],"fin":true},"retard":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Des heures précieuses sont perdues. À la nuit tombée seulement, quelqu'un parle enfin d'une tannerie abandonnée, au bout de la ruelle."}],"effets":[{"quete":{"id":"q-tanneurs","etape":"cave"}}],"choix":[],"fin":true}}},"sq-tanneurs":{"id":"sq-tanneurs","titre":"Les disparus des Tanneurs : la cave","type":"groupe","lieu":"tannerie-abandonnee","decor":"quartier-tanneurs","debut":"debut","disponible_si":{"quete_etape":{"q-tanneurs":"cave"}},"repetable":false,"romance":false,"quete":"q-tanneurs","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La trappe est lourde, mais ses gonds sont graissés de frais. En bas : des cages, des bougies violettes."}],"effets":[],"choix":[{"texte":"Descendre dans la cave.","si":{"flag":"tanneurs-piste-fraiche"},"visible_si_bloque":false,"effets":[],"aller":"piste"},{"texte":"Descendre dans la cave.","si":{"pas_flag":"tanneurs-piste-fraiche"},"visible_si_bloque":false,"effets":[],"aller":"retard"}],"fin":false},"piste":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les cultistes sont en plein rituel et ne [[t'ont pas entendu||vous ont pas entendus]]. Lina est vivante, dans la cage du fond."}],"effets":[],"choix":[],"combat":{"rencontre":"tanneurs-cultistes","victoire":"sauvee","defaite":"echec"},"fin":false},"retard":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Trop de temps a passé : les cultistes [[t'attendent||vous attendent]] au pied de l'échelle."}],"effets":[],"choix":[],"combat":{"rencontre":"tanneurs-cultistes","victoire":"trop-tard","defaite":"echec"},"fin":false},"sauvee":{"repliques":[{"qui":"lina","expression":"neutre","dit":"Lina se jette dans les bras de sa mère en pleurant. Les deux autres disparus sont là aussi, affaiblis mais vivants."}],"effets":[{"flag":"lina-sauvee","reputation":{"couronne":5,"guilde":5},"xp":70}],"choix":[],"suite":"fin","fin":false},"trop-tard":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les cultistes sont vaincus. Deux prisonniers sont sauvés… mais pour Lina, il est trop tard. Sa mère s'effondre."}],"effets":[{"xp":50,"pnj_mort":"lina"}],"choix":[],"suite":"fin","fin":false},"echec":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous êtes repoussés. Quand la garde investit la cave le lendemain, elle est vide. On ne retrouvera jamais Lina."}],"effets":[{"reputation":{"couronne":-5},"pnj_mort":"lina"}],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Il faut que la Guilde sache ce qui se cachait sous cette tannerie."}],"effets":[{"flag":"cultistes-lysmont","quete":{"id":"q-tanneurs","etape":"retour"}}],"choix":[],"fin":true}}},"sq-tanneurs-retour":{"id":"sq-tanneurs-retour","titre":"Les disparus des Tanneurs : le rapport","type":"groupe","lieu":"guilde","decor":"guilde","debut":"debut","disponible_si":{"quete_etape":{"q-tanneurs":"retour"}},"repetable":false,"romance":false,"quete":"q-tanneurs","pnj":"rowena","rend_quete":true,"noeuds":{"debut":{"repliques":[{"qui":"rowena","expression":"neutre","dit":"Rowena écoute sans un mot, puis repose sa pipe. « Des cultistes des Cendres. Dans MA ville. » Elle griffonne un ordre pour la garde."},{"qui":"rowena","expression":"neutre","dit":"« La petite Lina est rentrée chez elle. C'est grâce à [[toi||vous]]. »","si":{"flag":"lina-sauvee"}}],"effets":[{"points_guilde":30,"terminer_quete":"q-tanneurs"}],"choix":[],"fin":true}}},"sq-apprenti":{"id":"sq-apprenti","titre":"L'apprenti de l'Ordre","type":"groupe","lieu":"temple-du-seuil","decor":"temple-du-seuil","debut":"debut","disponible_si":{"flag":"examen-reussi"},"repetable":false,"romance":false,"quete":"q-apprenti","pnj":"elianne","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"elianne","expression":"neutre","dit":"« Tobin, mon apprenti, passe ses nuits dans les archives interdites. S'il se fait prendre par le Grand Prieur… » Sœur Elianne se mord la lèvre. « Pouvez-vous lui parler ? »"},{"qui":"tobin","expression":"neutre","dit":"Vous trouvez Tobin entre deux rayonnages, une bougie à la main, un vieux registre ouvert. « Regardez ! Les registres de l'Appel. Il manque des pages. Toujours les mêmes : le prix. »"}],"effets":[{"quete":{"id":"q-apprenti","etape":"parler"}}],"choix":[{"texte":"Lire le registre avec lui.","visible_si_bloque":false,"effets":[{"flag":"indice-prix-appel","xp":30}],"aller":"lire"},{"texte":"Le convaincre de remettre le registre en place avant qu'il ne soit trop tard.","visible_si_bloque":false,"effets":[{"reputation":{"ordre":5}}],"aller":"raisonner"},{"texte":"Le dénoncer au Grand Prieur Auréliath.","visible_si_bloque":false,"effets":[{"flag":"tobin-denonce","reputation":{"ordre":10}}],"aller":"denonce"}],"fin":false},"lire":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Une seule ligne a échappé au grattoir : « …et pour chaque Appel, le Voile cède d'un fil, et au nord, les Cendres s'en nourrissent. »"},{"qui":"elianne","expression":"surprise","dit":"Elianne, derrière vous, a tout entendu. Elle est livide."}],"effets":[],"choix":[],"suite":"fin","fin":false},"raisonner":{"repliques":[{"qui":"tobin","expression":"neutre","dit":"Tobin soupire et range le registre. « Vous avez raison. Mais un jour, quelqu'un devra savoir. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"denonce":{"repliques":[{"qui":"aureliath","expression":"neutre","dit":"Le Grand Prieur vous remercie chaleureusement. Le lendemain, Tobin a été « envoyé dans un monastère du nord ». Elianne ne vous adresse plus la parole."}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[],"effets":[{"points_guilde":15,"terminer_quete":"q-apprenti"}],"choix":[],"fin":true}}},"sq-tournoi-inscription":{"id":"sq-tournoi-inscription","titre":"Le tournoi des écuyers : l'inscription","type":"groupe","lieu":"arene","decor":"arene","debut":"debut","disponible_si":{"flag":"examen-reussi","pas_flag":"tournoi-inscrit"},"repetable":false,"romance":false,"quete":"q-tournoi","pnj":"aveline","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Aveline, juge du tournoi, [[t'accueille||vous accueille]]. « Un de nos écuyers s'est cassé la jambe. Il me faut un remplaçant. Et un adversaire coriace pour le finaliste : un mercenaire qui triche. »"},{"qui":"aveline","expression":"gene","dit":"« Si [[tu gagnes… je t'offre||vous gagnez… je vous offre]] une pâtisserie. » Elle se racle la gorge. « C'est une coutume. »"},{"qui":"aveline","expression":"neutre","dit":"« Il traîne sur la place avant chaque combat. [[Va||Allez]] voir comment il s'y prend, puis [[reviens||revenez]] ici. »"}],"effets":[{"flag":"tournoi-inscrit","quete":{"id":"q-tournoi","etape":"reperer"}}],"choix":[],"fin":true}}},"sq-tournoi-reperage":{"id":"sq-tournoi-reperage","titre":"Le tournoi des écuyers : le tricheur","type":"groupe","lieu":"lysmont-place","decor":"lysmont-place","debut":"debut","disponible_si":{"quete_etape":{"q-tournoi":"reperer"}},"repetable":false,"romance":false,"quete":"q-tournoi","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le mercenaire est là, près de la fontaine, entouré de parieurs. Un grand gaillard au sourire trop sûr de lui."}],"effets":[],"choix":[{"texte":"L'observer de loin pendant qu'il s'échauffe.","visible_si_bloque":false,"effets":[],"aller":"observe"},{"texte":"Payer un verre à l'un de ses anciens adversaires.","visible_si_bloque":false,"effets":[],"aller":"verre"}],"fin":false},"observe":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Il glisse quelque chose dans son gant gauche avant chaque passe : une poignée de sable. Maintenant, [[tu sais||vous savez]] d'où viendra le coup bas."}],"effets":[{"xp":10,"quete":{"id":"q-tournoi","etape":"duel"}}],"choix":[],"fin":true},"verre":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"« Il vise les yeux. Du sable, toujours de la main gauche. » L'écuyer vide sa chope. « Et il frappe quand on recule. »"}],"effets":[{"xp":10,"quete":{"id":"q-tournoi","etape":"duel"}}],"choix":[],"fin":true}}},"sq-tournoi":{"id":"sq-tournoi","titre":"Le tournoi des écuyers : le duel","type":"groupe","lieu":"arene","decor":"arene","debut":"debut","disponible_si":{"quete_etape":{"q-tournoi":"duel"}},"repetable":false,"romance":false,"quete":"q-tournoi","pnj":"aveline","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"« [[Te||Vous]] voilà. Le finaliste est prêt. » Aveline baisse la voix. « Méfie-toi de sa main gauche. »"}],"effets":[],"choix":[{"texte":"Entrer en lice.","visible_si_bloque":false,"effets":[],"aller":"combat"}],"fin":false},"combat":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"tournoi-ecuyers","victoire":"victoire","defaite":"defaite"},"fin":false},"victoire":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La foule rugit. Le mercenaire, désarmé, est escorté hors de l'arène."},{"qui":"aveline","expression":"joie","dit":"Aveline vous tend un gâteau de Lysmont, les joues roses. « Coutume. C'est la coutume. »"}],"effets":[{"reputation":{"couronne":5},"affinite":{"aveline":6},"or":40,"objet":"gateau-lysmont"}],"choix":[],"suite":"fin","fin":false},"defaite":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"« Il trichait, je l'ai vu. » Aveline fait disqualifier le mercenaire. « Vous vous êtes battus honnêtement. C'est ce qui compte. »"}],"effets":[{"affinite":{"aveline":3}}],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[],"effets":[{"points_guilde":25,"terminer_quete":"q-tournoi"}],"choix":[],"fin":true}}},"sq-boutique":{"id":"sq-boutique","titre":"Premiers pas au Comptoir","type":"individuel","lieu":"boutique","decor":"boutique","debut":"debut","disponible_si":{"flag":"examen-reussi","pas_flag":"boutique-decouverte"},"repetable":false,"romance":false,"quete":"q-boutique","pnj":"halvine","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"halvine","expression":"neutre","dit":"« Un nouveau visage de la Guilde ! Entrez, entrez. Dame Halvine Corbelet, pour vous servir. Ici, tout a un prix, et le prix est juste. »"},{"qui":"halvine","expression":"neutre","dit":"« C'est simple : l'onglet Acheter montre ce que je vends, l'onglet Vendre montre ce que vous avez dans votre sac. Je reprends tout à moitié prix, sauf les objets de quête. »"},{"qui":"narrateur","expression":"neutre","dit":"En vous penchant vers le comptoir, vous remarquez quelque chose qui brille entre deux pavés : une vieille breloque de cuivre."},{"qui":"halvine","expression":"neutre","dit":"« Tiens, ça traîne là depuis des semaines. Gardez-la. Achetez-moi d'abord quelque chose d'utile, une petite potion par exemple, puis revendez-moi cette breloque : vous saurez tout faire. »"}],"effets":[{"flag":"boutique-decouverte","objet":"breloque-cabossee","quete":{"id":"q-boutique","etape":"acheter"}}],"choix":[],"fin":true}}},"sq-boutique-fin":{"id":"sq-boutique-fin","titre":"Premiers pas au Comptoir : le compte est bon","type":"individuel","lieu":"boutique","decor":"boutique","debut":"debut","disponible_si":{"quete_etape":{"q-boutique":"retour"}},"repetable":false,"romance":false,"quete":"q-boutique","pnj":"halvine","rend_quete":true,"noeuds":{"debut":{"repliques":[{"qui":"halvine","expression":"neutre","dit":"« Acheté, vendu, et sans vous faire rouler : vous apprenez vite. » Elle pousse une petite fiole et quelques pièces vers vous."},{"qui":"halvine","expression":"neutre","dit":"« Cadeau de la maison. Revenez quand votre bourse sera plus lourde : j'ai toujours de quoi l'alléger. »"}],"effets":[{"xp":20,"or":15,"objet":"potion-soin-petite","terminer_quete":"q-boutique"}],"choix":[],"fin":true}}},"cl-lame-runique-1":{"id":"cl-lame-runique-1","titre":"Lame runique — La rune perdue","type":"individuel","lieu":"qarzim-bazar","decor":"qarzim-bazar","debut":"debut","disponible_si":{"flag":"sables-ouverts","pas_flag":"classe-1","classe":"lame-runique"},"repetable":false,"romance":false,"quete":"q-classe-lame-runique","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Au fond du Bazar, un marchand de curiosités vend un morceau de colonne de sel. Une rune y est gravée : un cercle fendu, entouré de sept traits."},{"qui":"narrateur","expression":"neutre","dit":"Votre lame vibre quand vous approchez la main. Les runes que vous gravez en combat ont toujours été les vôtres… mais celle-ci, votre lame la connaît."}],"effets":[],"choix":[{"texte":"Recopier la rune et la graver sur votre lame. (Intelligence, difficulté 20)","visible_si_bloque":false,"test":{"carac":"INT","difficulte":20,"reussite":"gravee","echec":"brulure"},"effets":[]},{"texte":"Acheter le fragment de colonne. (60 or)","si":{"or_min":60},"visible_si_bloque":false,"effets":[{"or":-60}],"aller":"gravee"}],"fin":false},"gravee":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La rune s'imprime dans l'acier comme si elle l'attendait. Pendant une seconde, vous voyez mille sceaux s'allumer le long de la lame, puis s'éteindre."},{"qui":"narrateur","expression":"neutre","dit":"Le marchand murmure : « Les nains de Karak-Dûm savent forger ces runes-là. On dit qu'ils les tiennent des tout premiers Appelés. »"}],"effets":[{"flag":"heros:classe-1","xp":200,"quete":{"id":"q-classe-lame-runique","etape":"etape2"}}],"choix":[],"fin":true},"brulure":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La rune vous brûle la main avant de s'imprimer dans l'acier, de travers. Elle tiendra. Elle n'aime pas qu'on la force."}],"effets":[{"flag":"heros:classe-1","xp":120,"quete":{"id":"q-classe-lame-runique","etape":"etape2"}}],"choix":[],"fin":true}}},"cl-arcaniste-1":{"id":"cl-arcaniste-1","titre":"Arcaniste — Le feu du désert","type":"individuel","lieu":"qarzim-porte","decor":"qarzim-porte","debut":"debut","disponible_si":{"flag":"sables-ouverts","pas_flag":"classe-1","classe":"arcaniste"},"repetable":false,"romance":false,"quete":"q-classe-arcaniste","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Un ermite aux yeux brûlés par le soleil mendie à la Porte des Caravanes. Quand vous passez, des étincelles bleues courent au bout de vos doigts. Il sourit."},{"qui":"narrateur","expression":"neutre","dit":"« Tu sens la foudre des tempêtes, toi. Viens. Je vais te montrer comment on la boit. »"}],"effets":[],"choix":[{"texte":"Le suivre dans le désert, au cœur d'une tempête sèche.","visible_si_bloque":false,"effets":[],"aller":"tempete"}],"fin":false},"tempete":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Au milieu des dunes, l'air crépite. L'ermite lève les bras ; un éclair tombe… dans ses mains, sans le blesser. « À toi. »"}],"effets":[],"choix":[{"texte":"Attraper l'éclair. (Esprit, difficulté 21)","visible_si_bloque":false,"test":{"carac":"ESP","difficulte":21,"reussite":"reussi","echec":"foudroye"},"effets":[]}],"fin":false},"reussi":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La foudre vous traverse sans vous brûler. Vous la sentez couler, comme une rivière, puis se ranger quelque part en vous, à côté du feu et du givre."},{"qui":"narrateur","expression":"neutre","dit":"« Il te manque le feu de la terre, maintenant. Celui des volcans. Va voir les nains, à Grisfer. »"}],"effets":[{"flag":"heros:classe-1","xp":200,"quete":{"id":"q-classe-arcaniste","etape":"etape2"}}],"choix":[],"fin":true},"foudroye":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"L'éclair vous jette dans le sable, les cheveux fumants. Mais quelque chose est resté. Une étincelle qui ne s'éteint pas."}],"effets":[{"flag":"heros:classe-1","xp":120,"quete":{"id":"q-classe-arcaniste","etape":"etape2"}}],"choix":[],"fin":true}}},"cl-invocateur-1":{"id":"cl-invocateur-1","titre":"Invocateur — Le pacte des bêtes","type":"individuel","lieu":"campement-lunecroc","decor":"campement-lunecroc","debut":"debut","disponible_si":{"flag":"sables-ouverts","pas_flag":"classe-1","classe":"invocateur"},"repetable":false,"romance":false,"quete":"q-classe-invocateur","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La nuit, au campement, un fennec translucide s'assoit devant votre tente. Un esprit. Il vous regarde comme on regarde un voleur."},{"qui":"sorha","expression":"neutre","dit":"L'Ancienne Sorha vous chuchote : « Tes créatures obéissent parce que tu les tires du Voile. Lui, il veut savoir si tu sais demander. »"}],"effets":[],"choix":[{"texte":"S'asseoir devant lui et lui parler, longtemps. (Charisme, difficulté 19)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":19,"reussite":"pacte","echec":"fuite"},"effets":[]},{"texte":"Tenter de l'invoquer de force.","visible_si_bloque":false,"effets":[],"aller":"force"}],"fin":false},"pacte":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le fennec écoute toute la nuit. À l'aube, il pose une patte sur votre main. Vos créatures, désormais, vous semblent… plus chaudes. Plus présentes."}],"effets":[{"flag":"heros:classe-1","xp":200,"quete":{"id":"q-classe-invocateur","etape":"etape2"}}],"choix":[],"fin":true},"fuite":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le fennec repart dans la nuit. Mais au loin, il se retourne une fois. Ce n'est pas un non. C'est un « pas encore »."}],"effets":[{"flag":"heros:classe-1","xp":120,"quete":{"id":"q-classe-invocateur","etape":"etape2"}}],"choix":[],"fin":true},"force":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"L'esprit se tord, vous mord la main, et disparaît. Sorha secoue la tête. « On ne met pas un vent en cage. » Vous avez compris la leçon, à vos dépens."}],"effets":[{"flag":"heros:classe-1","xp":80,"quete":{"id":"q-classe-invocateur","etape":"etape2"}}],"choix":[],"fin":true}}},"cl-ombre-1":{"id":"cl-ombre-1","titre":"Ombre — La Main et l'Ombre","type":"individuel","lieu":"qarzim-porte","decor":"qarzim-porte","debut":"debut","disponible_si":{"flag":"sables-ouverts","pas_flag":"classe-1","classe":"ombre"},"repetable":false,"romance":false,"quete":"q-classe-ombre","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Un grain de sable sur votre oreiller, un soir. Puis un mot, glissé sous la porte : « Les toits. Minuit. Seul. »"},{"qui":"narrateur","expression":"neutre","dit":"Sur les toits, trois silhouettes voilées de la Main de Sable vous attendent. « Tu as le talent. Nous avons l'or. Montre-nous ce que vaut une Ombre de l'autre monde. »"}],"effets":[],"choix":[{"texte":"Accepter l'épreuve : leur voler leurs insignes sans être vu. (Agilité, difficulté 21)","visible_si_bloque":false,"test":{"carac":"AGI","difficulte":21,"reussite":"vol","echec":"combat"},"effets":[]},{"texte":"Refuser et combattre.","visible_si_bloque":false,"effets":[],"aller":"combat"}],"fin":false},"vol":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"À l'aube, les trois assassins se réveillent sans leurs insignes, posés en rang sur le toit… avec un mot : « Non merci. »"},{"qui":"narrateur","expression":"neutre","dit":"Une voix, derrière vous, que vous n'avez pas entendue venir : « Pas mal. Kezir avait un maître, autrefois. Il vit dans l'Archipel. Si tu veux devenir meilleur que lui… »"}],"effets":[{"flag":"heros:classe-1","xp":220,"quete":{"id":"q-classe-ombre","etape":"etape2"}}],"choix":[],"fin":true},"combat":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"assassins-banquet","victoire":"fini","defaite":"fini"},"fin":false},"fini":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les assassins disparaissent dans la nuit. L'un d'eux a laissé tomber un mot : « Le maître de Kezir vit dans l'Archipel des Brumes. »"}],"effets":[{"flag":"heros:classe-1","xp":160,"quete":{"id":"q-classe-ombre","etape":"etape2"}}],"choix":[],"fin":true}}},"cl-gardien-1":{"id":"cl-gardien-1","titre":"Gardien — Le serment du bouclier","type":"individuel","lieu":"qarzim-oasis","decor":"qarzim-oasis","debut":"debut","disponible_si":{"flag":"sables-ouverts","pas_flag":"classe-1","classe":"gardien"},"repetable":false,"romance":false,"quete":"q-classe-gardien","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"ziyane","expression":"neutre","dit":"Mère Ziyane vous indique un vieil homme au fond de l'auberge. « Il vient tous les soirs boire de l'eau, rien d'autre. On dit qu'il était paladin de l'Ordre. »"},{"qui":"narrateur","expression":"neutre","dit":"Le vieil homme a un bouclier rond posé contre sa chaise. Pas de blason : on l'a gratté. « Tu portes la lumière de l'Ordre, toi aussi. Sais-tu seulement ce qu'elle protège ? »"}],"effets":[],"choix":[{"texte":"« Les gens. Pas l'Ordre. »","visible_si_bloque":false,"effets":[],"aller":"gens"},{"texte":"« L'Ordre protège les gens. C'est la même chose. »","visible_si_bloque":false,"effets":[],"aller":"ordre"}],"fin":false},"gens":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le vieil homme sourit pour la première fois. Il vous tend son bouclier. « Tiens-le contre moi. » Il frappe, une fois, de toutes ses forces."}],"effets":[],"choix":[{"texte":"Tenir. (Vitalité, difficulté 20)","visible_si_bloque":false,"test":{"carac":"VIT","difficulte":20,"reussite":"tenu","echec":"tombe"},"effets":[]}],"fin":false},"ordre":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"« J'ai cru ça aussi. Jusqu'à Valgrane. » Il se tait, puis vous tend son bouclier. « Tiens-le. Si tu tiens, je te dirai le reste. »"}],"effets":[],"choix":[{"texte":"Tenir. (Vitalité, difficulté 20)","visible_si_bloque":false,"test":{"carac":"VIT","difficulte":20,"reussite":"tenu","echec":"tombe"},"effets":[]}],"fin":false},"tenu":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous tenez. Le vieil homme hoche la tête. « Le vrai serment du bouclier ne se prête pas au temple. Il se prête sur une passe, face à l'ennemi. Il y a une passe, dans les Mille Marches, à Grisfer… »"}],"effets":[{"flag":"heros:classe-1","xp":200,"quete":{"id":"q-classe-gardien","etape":"etape2"}}],"choix":[],"fin":true},"tombe":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous voilà assis par terre. Le vieil homme vous aide à vous relever. « Tu t'es relevé. C'est le début. » Il vous parle d'une passe, dans les Mille Marches, à Grisfer."}],"effets":[{"flag":"heros:classe-1","xp":120,"quete":{"id":"q-classe-gardien","etape":"etape2"}}],"choix":[],"fin":true}}},"cl-alchimiste-1":{"id":"cl-alchimiste-1","titre":"Alchimiste — L'atelier d'airain","type":"individuel","lieu":"qarzim-bazar","decor":"qarzim-bazar","debut":"debut","disponible_si":{"flag":"sables-ouverts","pas_flag":"classe-1","classe":"alchimiste"},"repetable":false,"romance":false,"quete":"q-classe-alchimiste","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Au fond du Bazar, un atelier sent l'huile et le métal chaud. Sur l'établi, les plans d'un automate de la taille d'un homme : un « golem d'airain ». Il manque la page du cœur."},{"qui":"narrateur","expression":"neutre","dit":"Le vieux vulpin qui tient l'atelier soupire. « Mon maître a emporté la page du cœur dans sa tombe. Il disait que seul un cœur de forge nain pouvait faire battre l'airain. »"}],"effets":[],"choix":[{"texte":"Reconstituer la page manquante à partir des autres. (Intelligence, difficulté 21)","visible_si_bloque":false,"test":{"carac":"INT","difficulte":21,"reussite":"plans","echec":"bricolage"},"effets":[]},{"texte":"Racheter les plans tels quels. (80 or)","si":{"or_min":80},"visible_si_bloque":false,"effets":[{"or":-80}],"aller":"bricolage"}],"fin":false},"plans":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"À l'aube, la page est là, recopiée de votre main : les engrenages, les soupapes, et au centre, un cercle vide marqué « cœur de forge — Karak-Dûm »."}],"effets":[{"flag":"heros:classe-1","xp":200,"objet":"bombe-feu","quete":{"id":"q-classe-alchimiste","etape":"etape2"}}],"choix":[],"fin":true},"bricolage":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les plans sous le bras, vous savez ce qu'il vous faut : un cœur de forge, et la seule forge qui en fabrique est à Karak-Dûm, dans les Monts Grisfer."}],"effets":[{"flag":"heros:classe-1","xp":140,"quete":{"id":"q-classe-alchimiste","etape":"etape2"}}],"choix":[],"fin":true}}},"cl-archer-1":{"id":"cl-archer-1","titre":"Archer — Le chant des ancêtres","type":"individuel","lieu":"campement-lunecroc","decor":"campement-lunecroc","debut":"debut","disponible_si":{"flag":"sables-ouverts","pas_flag":"classe-1","classe":"archer"},"repetable":false,"romance":false,"quete":"q-classe-archer","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"sorha","expression":"neutre","dit":"L'Ancienne Sorha pose une plume blanche sur votre arc. « Les ancêtres guident les flèches de ceux qui écoutent le vent. Ferme les yeux. Tire sur le chacal qui rôde là-bas, sans le regarder. »"}],"effets":[],"choix":[{"texte":"Fermer les yeux et tirer. (Esprit, difficulté 20)","visible_si_bloque":false,"test":{"carac":"ESP","difficulte":20,"reussite":"touche","echec":"rate"},"effets":[]}],"fin":false},"touche":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous entendez la flèche chanter. Puis un jappement, au loin : touché. Sorha rit doucement. « Les ancêtres t'aiment bien. »"},{"qui":"sorha","expression":"neutre","dit":"« Il y a, dans l'Archipel des Brumes, une cible que le vent déplace sans cesse. Celui qui la touche entend les ancêtres pour toujours. »"}],"effets":[{"flag":"heros:classe-1","xp":200,"quete":{"id":"q-classe-archer","etape":"etape2"}}],"choix":[],"fin":true},"rate":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La flèche se plante dans le sable. Sorha hausse les épaules. « Le vent n'a pas encore appris ton nom. Il l'apprendra. » Elle vous parle de la cible des vents, dans l'Archipel des Brumes."}],"effets":[{"flag":"heros:classe-1","xp":120,"quete":{"id":"q-classe-archer","etape":"etape2"}}],"choix":[],"fin":true}}},"cl-guerisseur-1":{"id":"cl-guerisseur-1","titre":"Guérisseur — Le souffle des vivants","type":"individuel","lieu":"mines-ether","decor":"mines-ether","debut":"debut","disponible_si":{"flag":"sables-ouverts","pas_flag":"classe-1","classe":"guerisseur"},"repetable":false,"romance":false,"quete":"q-classe-guerisseur","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Aux mines, des mineurs toussent une poussière violette. Les guérisseurs de la Concorde passent devant eux sans s'arrêter : « Ce ne sont que des journaliers. »"},{"qui":"narrateur","expression":"neutre","dit":"Un enfant vous tire par la manche. Son père ne respire presque plus."}],"effets":[],"choix":[{"texte":"Soigner les mineurs toute la nuit. (Esprit, difficulté 21)","visible_si_bloque":false,"test":{"carac":"ESP","difficulte":21,"reussite":"sauves","echec":"epuise"},"effets":[]}],"fin":false},"sauves":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Au matin, les mineurs respirent. Vous, à peine. Mais dans votre lumière, il y a quelque chose de nouveau : un souffle qui ne vient pas de vous."},{"qui":"narrateur","expression":"neutre","dit":"Un vieux mineur vous prend la main. « Ma grand-mère disait qu'il y a une source, dans l'Archipel, où la lumière soigne même les morts. Vous devriez la trouver. »"}],"effets":[{"flag":"heros:classe-1","reputation":{"ourvalis":3},"xp":220,"quete":{"id":"q-classe-guerisseur","etape":"etape2"}}],"choix":[],"fin":true},"epuise":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous en sauvez beaucoup. Pas tous. Le père de l'enfant s'éteint au lever du soleil, votre main sur son front."},{"qui":"narrateur","expression":"neutre","dit":"Un vieux mineur vous parle d'une source sacrée, dans l'Archipel des Brumes. « Pour la prochaine fois. Il y a toujours une prochaine fois. »"}],"effets":[{"flag":"heros:classe-1","xp":140,"quete":{"id":"q-classe-guerisseur","etape":"etape2"}}],"choix":[],"fin":true}}},"cl-berserker-1":{"id":"cl-berserker-1","titre":"Berserker — Le sang qui chante","type":"individuel","lieu":"qarzim-porte","decor":"qarzim-porte","debut":"debut","disponible_si":{"flag":"sables-ouverts","pas_flag":"classe-1","classe":"berserker"},"repetable":false,"romance":false,"quete":"q-classe-berserker","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Dans les fosses de combat, derrière la Porte des Caravanes, un vieux sang-dragon aux écailles grises défie la foule. « Qui a du feu dans les veines ? Personne ? »"}],"effets":[],"choix":[{"texte":"Descendre dans la fosse.","visible_si_bloque":false,"effets":[],"aller":"fosse"}],"fin":false},"fosse":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le vieux combattant vous regarde, renifle. « Toi. Tu as le sang. Montre-moi qu'il chante. »"}],"effets":[],"choix":[{"texte":"Encaisser ses coups sans reculer. (Vitalité, difficulté 20)","visible_si_bloque":false,"test":{"carac":"VIT","difficulte":20,"reussite":"chante","echec":"tombe"},"effets":[]},{"texte":"Frapper de toutes vos forces. (Force, difficulté 21)","visible_si_bloque":false,"test":{"carac":"FOR","difficulte":21,"reussite":"chante","echec":"tombe"},"effets":[]}],"fin":false},"chante":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le sang monte. Vos yeux brûlent. Pendant une seconde, vous voyez des ailes dans votre ombre. Le vieux sang-dragon recule, ravi. « Il chante ! »"},{"qui":"narrateur","expression":"neutre","dit":"« Va au Nid des Wyrms, dans l'Archipel. Écoute les vieux dragons. Ton sang apprendra la chanson entière. »"}],"effets":[{"flag":"heros:classe-1","xp":200,"or":50,"quete":{"id":"q-classe-berserker","etape":"etape2"}}],"choix":[],"fin":true},"tombe":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous voilà dans la poussière. La foule rit. Le vieux sang-dragon ne rit pas. « Il chante faux, mais il chante. » Il vous parle du Nid des Wyrms."}],"effets":[{"flag":"heros:classe-1","xp":120,"quete":{"id":"q-classe-berserker","etape":"etape2"}}],"choix":[],"fin":true}}},"cl-barde-1":{"id":"cl-barde-1","titre":"Barde — La chanson perdue","type":"individuel","lieu":"qarzim-oasis","decor":"qarzim-oasis","debut":"debut","disponible_si":{"flag":"sables-ouverts","pas_flag":"classe-1","classe":"barde"},"repetable":false,"romance":false,"quete":"q-classe-barde","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"ziyane","expression":"neutre","dit":"« Les Dunes chantantes ? » Mère Ziyane hausse les épaules. « Les bardes de passage essaient tous de noter leur chant. Ils repartent tous fous. »"},{"qui":"narrateur","expression":"neutre","dit":"La nuit venue, vous montez sur la terrasse. Au loin, les dunes chantent. Une mélodie impossible, qui change à chaque souffle."}],"effets":[],"choix":[{"texte":"Jouer avec elles, au lieu de les noter. (Charisme, difficulté 20)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":20,"reussite":"accord","echec":"fausse"},"effets":[]}],"fin":false},"accord":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Votre instrument trouve la note. Puis une autre. Les dunes vous répondent, comme un chœur. À l'aube, vous avez trois couplets. Il en manque un : le dernier."},{"qui":"narrateur","expression":"neutre","dit":"Un vieux caravanier, en bas, a tout entendu. « Le dernier couplet, ce sont les sirènes de l'Archipel qui le chantent. Tout le monde sait ça. »"}],"effets":[{"flag":"heros:classe-1","xp":200,"quete":{"id":"q-classe-barde","etape":"etape2"}}],"choix":[],"fin":true},"fausse":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Une fausse note, et les dunes se taisent, vexées. Mais vous avez entendu assez pour savoir : il manque un couplet, que chantent les sirènes de l'Archipel."}],"effets":[{"flag":"heros:classe-1","xp":120,"quete":{"id":"q-classe-barde","etape":"etape2"}}],"choix":[],"fin":true}}},"ky-grillades":{"id":"ky-grillades","titre":"Kaya — Le concours de brochettes","type":"individuel","lieu":"qarzim-oasis","decor":"qarzim-oasis","debut":"debut","disponible_si":{"flag":"kaya-recrutee","affinite_min":{"kaya":5}},"repetable":false,"romance":false,"pnj":"kaya","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"kaya","expression":"neutre","dit":"Kaya pose deux montagnes de brochettes sur la table. « Concours ! Celui qui en mange le plus a gagné. Le perdant paie. Et ne viens pas pleurer après. »"}],"effets":[],"choix":[{"texte":"Relever le défi. (Vitalité, difficulté 19)","visible_si_bloque":false,"test":{"carac":"VIT","difficulte":19,"reussite":"gagne","echec":"perd"},"effets":[]},{"texte":"Tricher en glissant des brochettes sous la table.","visible_si_bloque":false,"effets":[{"flag":"heros:triche-brochettes"}],"aller":"triche"},{"texte":"« Je te regarde manger, ça me suffit. »","visible_si_bloque":false,"effets":[{"affinite":{"kaya":2}}],"aller":"regarde"}],"fin":false},"gagne":{"repliques":[{"qui":"kaya","expression":"surprise","dit":"Kaya fixe votre assiette vide, puis la sienne, à moitié pleine. « Impossible. Tu as un deuxième estomac. Avoue. »"},{"qui":"kaya","expression":"joie","dit":"Elle éclate de rire et vous donne une tape dans le dos à vous décrocher une épaule. « Revanche demain ! »"}],"effets":[{"affinite":{"kaya":7}}],"choix":[],"fin":true},"perd":{"repliques":[{"qui":"kaya","expression":"joie","dit":"« HA ! » Kaya lève les bras au ciel, une brochette dans chaque main. « La reine des brochettes ! Tu paies ! »"}],"effets":[{"affinite":{"kaya":5},"or":-10}],"choix":[],"fin":true},"triche":{"repliques":[{"qui":"kaya","expression":"colere","dit":"Kaya renifle. Une fois. Deux fois. Puis elle se penche sous la table. « Sérieusement ? Tu triches à un concours de brochettes ? » Elle vous jette un os à la figure… mais elle rit à moitié."}],"effets":[{"affinite":{"kaya":-2}}],"choix":[],"fin":true},"regarde":{"repliques":[{"qui":"kaya","expression":"gene","dit":"Kaya s'arrête, une brochette à mi-chemin. Ses oreilles rougissent. « Mange au lieu de dire des bêtises. »"}],"effets":[],"choix":[],"fin":true}}},"ky-hurlement":{"id":"ky-hurlement","titre":"Kaya — Le Hurlement des Ancêtres","type":"individuel","lieu":"campement-lunecroc","decor":"campement-lunecroc","debut":"debut","disponible_si":{"flag":"kaya-recrutee","affinite_palier":{"kaya":"proche"}},"repetable":false,"romance":false,"quete":"q-kaya","pnj":"sorha","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"sorha","expression":"neutre","dit":"La nuit est pleine. L'Ancienne Sorha a allumé un feu bleu au centre du campement. « Kaya veut hurler avec les ancêtres. Elle a choisi qui l'accompagnerait. » Elle vous regarde de son œil valide. « Toi. »"},{"qui":"kaya","expression":"neutre","dit":"Kaya ne plaisante pas, pour une fois. « Quand un Lunecroc hurle sur la falaise, les ancêtres répondent. Ou pas. S'ils ne répondent pas, c'est qu'on ne mérite pas encore. Moi, ils ne m'ont jamais répondu. »"}],"effets":[],"choix":[{"texte":"Hurler avec elle, de toutes vos forces.","visible_si_bloque":false,"effets":[],"aller":"hurle"},{"texte":"Lui prendre la main, en silence, pendant qu'elle hurle.","visible_si_bloque":false,"effets":[],"aller":"main"}],"fin":false},"hurle":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vos deux voix montent dans la nuit, maladroites puis justes. Et du fond du désert… quelque chose répond. Un hurlement immense, qui fait trembler le sable."}],"effets":[],"choix":[],"suite":"reponse","fin":false},"main":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Kaya hurle. Sa main serre la vôtre à vous briser les doigts. Et du fond du désert… quelque chose répond. Un hurlement immense, qui fait trembler le sable."}],"effets":[],"choix":[],"suite":"reponse","fin":false},"reponse":{"repliques":[{"qui":"kaya","expression":"tristesse","dit":"Kaya pleure sans s'en cacher. « Ils ont répondu. Ils ont répondu… » Elle s'essuie les yeux d'un revers de bras. « Je deviendrai rang S. Je reprendrai nos terres. Et tu seras là pour voir ça. C'est un ordre. »"}],"effets":[{"reputation":{"ourvalis":5},"affinite":{"kaya":10},"quete":{"id":"q-kaya","etape":"terres"}}],"choix":[],"fin":true}}},"ky-falaise":{"id":"ky-falaise","titre":"Kaya — La falaise au clair de lune","type":"individuel","lieu":"campement-lunecroc","decor":"campement-lunecroc","debut":"debut","disponible_si":{"flag":"kaya-recrutee","affinite_palier":{"kaya":"amoureuse"}},"repetable":false,"romance":true,"pnj":"kaya","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"kaya","expression":"gene","dit":"Kaya est assise au bord de la falaise, la queue battant nerveusement le rocher. « Chez nous, quand on aime quelqu'un, on le lui dit. Pas de détours. Pas de poèmes. Alors… » Elle inspire. « Je t'aime. Voilà. C'est dit. »"}],"effets":[],"choix":[{"texte":"« Moi aussi, Kaya. Sans détour. »","visible_si_bloque":false,"effets":[{"affinite":{"kaya":6}}],"aller":"oui"},{"texte":"L'embrasser pour toute réponse.","visible_si_bloque":false,"effets":[{"affinite":{"kaya":6}}],"aller":"oui"}],"fin":false},"oui":{"repliques":[{"qui":"kaya","expression":"joie","dit":"Elle rit, un rire qui finit en hurlement de joie lancé à la lune. Puis elle se blottit contre vous, et la nuit du désert devient soudain très chaude…"},{"qui":"narrateur","expression":"neutre","dit":"(Fondu au noir.)"}],"effets":[],"choix":[],"fin":true}}},"nd-marchandage":{"id":"nd-marchandage","titre":"Nadja — Leçon de marchandage","type":"individuel","lieu":"qarzim-bazar","decor":"qarzim-bazar","debut":"debut","disponible_si":{"flag":"nadja-rencontree"},"repetable":false,"romance":false,"pnj":"nadja","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"nadja","expression":"neutre","dit":"Nadja vous entraîne devant un étal de tapis. « Leçon numéro un : on ne paie jamais le premier prix. Montre-moi ce que tu vaux. »"}],"effets":[],"choix":[{"texte":"Marchander avec aplomb. (Charisme, difficulté 18)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":18,"reussite":"bien","echec":"rate"},"effets":[]},{"texte":"Laisser Nadja faire, et prendre des notes.","visible_si_bloque":false,"effets":[{"affinite":{"nadja":3}}],"aller":"notes"},{"texte":"« Ce marchand a l'air pauvre. Payons le prix qu'il demande. »","visible_si_bloque":false,"effets":[{"affinite":{"nadja":1},"or":-15}],"aller":"genereux"}],"fin":false},"bien":{"repliques":[{"qui":"nadja","expression":"surprise","dit":"Le marchand finit par vous offrir le thé ET le tapis. Nadja vous dévisage. « …Tu as déjà fait ça. Avoue. »"}],"effets":[{"affinite":{"nadja":6},"or":30}],"choix":[],"fin":true},"rate":{"repliques":[{"qui":"nadja","expression":"neutre","dit":"Vous repartez avec un tapis hors de prix et un sourire de vainqueur. Nadja se masse les tempes. « On reprendra la leçon. Depuis le début. »"}],"effets":[{"affinite":{"nadja":3},"or":-20}],"choix":[],"fin":true},"notes":{"repliques":[{"qui":"nadja","expression":"neutre","dit":"En trois phrases, Nadja divise le prix par quatre. « Tu vois ? Le secret, c'est de toujours avoir l'air de pouvoir partir. » Elle vous fait un clin d'œil. « Avec les gens aussi. »"}],"effets":[],"choix":[],"fin":true},"genereux":{"repliques":[{"qui":"nadja","expression":"neutre","dit":"Nadja vous regarde comme si vous veniez de jeter de l'or dans un puits. Puis, plus doucement : « …Tu es bizarre. Ça me plaît, bizarrement. »"}],"effets":[],"choix":[],"fin":true}}},"nd-livre":{"id":"nd-livre","titre":"Nadja — Le Grand Livre rouge","type":"individuel","lieu":"qarzim-palais","decor":"qarzim-palais","debut":"debut","disponible_si":{"flag":"nadja-rencontree","affinite_palier":{"nadja":"proche"}},"repetable":false,"romance":false,"quete":"q-nadja","pnj":"nadja","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"nadja","expression":"neutre","dit":"Minuit, au pied du Palais. Nadja a troqué ses voiles contre une tenue noire. « Ma dette est écrite dans le Grand Livre rouge, au dernier étage. Avec celles de la moitié de Qarzim, et le nom de tous les acheteurs de cristaux. Je veux une copie. Tu m'aides ? »"}],"effets":[],"choix":[{"texte":"Grimper par les terrasses. (Agilité, difficulté 21)","visible_si_bloque":false,"test":{"carac":"AGI","difficulte":21,"reussite":"copie","echec":"alerte"},"effets":[]},{"texte":"Faire diversion pendant qu'elle entre. (Charisme, difficulté 20)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":20,"reussite":"copie","echec":"alerte"},"effets":[]}],"fin":false},"copie":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le Grand Livre est un registre de cuir rouge, épais comme un tronc. Nadja recopie à toute vitesse, à la lueur d'un cristal."},{"qui":"nadja","expression":"surprise","dit":"Elle s'arrête sur une page. « Ces cristaux… ils partent vers le nord. Des caisses entières. Payées en or noir, par un acheteur qui signe d'une rune violette. » Elle pâlit. « La Concorde vend aux Cendres. »"}],"effets":[{"flag":"concorde-vend-aux-cendres","affinite":{"nadja":10},"xp":120,"objet":"grand-livre-rouge","quete":{"id":"q-nadja","etape":"acheteurs"}}],"choix":[],"suite":"fin","fin":false},"alerte":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Une cloche sonne. Des gardes ! Vous sautez de terrasse en terrasse, Nadja serrant contre elle les quelques pages qu'elle a pu arracher."},{"qui":"nadja","expression":"neutre","dit":"Dans une ruelle, à bout de souffle, elle déplie les pages. « C'est peu… mais c'est assez. Des caisses de cristaux vers le nord. Signées d'une rune violette. »"}],"effets":[{"flag":"concorde-vend-aux-cendres","reputation":{"concorde":-5},"affinite":{"nadja":7},"objet":"grand-livre-rouge","quete":{"id":"q-nadja","etape":"acheteurs"}}],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"nadja","expression":"neutre","dit":"« Merci. » Nadja range les pages contre son cœur. « Personne n'avait jamais pris de risque pour moi. Personne. » Elle détourne les yeux. « Je n'aime pas avoir des dettes. Celle-là, je la garderai. »"}],"effets":[],"choix":[],"fin":true}}},"nd-terrasse":{"id":"nd-terrasse","titre":"Nadja — Les comptes d'une nuit","type":"individuel","lieu":"qarzim-oasis","decor":"qarzim-oasis","debut":"debut","disponible_si":{"flag":"nadja-rencontree","affinite_palier":{"nadja":"amoureuse"}},"repetable":false,"romance":true,"pnj":"nadja","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"nadja","expression":"neutre","dit":"Sur la terrasse de l'Oasis, Nadja a sorti son carnet. Elle ne compte pas : elle dessine. Votre visage."},{"qui":"nadja","expression":"gene","dit":"Elle referme le carnet trop vite. « Ne dis rien. J'ai calculé tous les risques de cette… chose entre nous. Ils sont énormes. » Elle soupire. « Et je m'en fiche. C'est nouveau. »"}],"effets":[],"choix":[{"texte":"« Alors prenons le risque. Ensemble. »","visible_si_bloque":false,"effets":[{"affinite":{"nadja":6}}],"aller":"oui"}],"fin":false},"oui":{"repliques":[{"qui":"nadja","expression":"joie","dit":"Elle sourit, pour de vrai, sans calcul. Les voiles de la terrasse ondulent dans la brise du soir, et le carnet tombe, oublié, sur les dalles…"},{"qui":"narrateur","expression":"neutre","dit":"(Fondu au noir.)"}],"effets":[],"choix":[],"fin":true}}},"sr-contes":{"id":"sr-contes","titre":"Séraphine — Les contes de l'autre monde","type":"individuel","lieu":"qarzim-residence","decor":"qarzim-residence","debut":"debut","disponible_si":{"flag":"seraphine-recrutee"},"repetable":false,"romance":false,"pnj":"seraphine","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"seraphine","expression":"neutre","dit":"Séraphine vous attend dans le jardin de la Résidence, pieds nus dans l'herbe, un carnet sur les genoux. « Raconte-moi ton monde. Pas les guerres. Les petites choses. Ce que vous mangiez le matin. Les histoires qu'on racontait aux enfants. »"},{"qui":"seraphine","expression":"neutre","dit":"Elle hésite. « Toi, tu as eu une autre vie, avant. Tu t'en souviens ? »","si":{"origine":"reincarne"}}],"effets":[],"choix":[{"texte":"Lui raconter un conte de votre enfance.","visible_si_bloque":false,"effets":[{"affinite":{"seraphine":6}}],"aller":"conte"},{"texte":"Lui décrire une ville de votre monde, avec ses lumières qui ne s'éteignent jamais.","visible_si_bloque":false,"effets":[{"affinite":{"seraphine":5}}],"aller":"ville"},{"texte":"« Ce n'est pas si intéressant, tu sais. »","visible_si_bloque":false,"effets":[{"affinite":{"seraphine":-1}}],"aller":"decue"}],"fin":false},"conte":{"repliques":[{"qui":"seraphine","expression":"joie","dit":"Elle note tout, les yeux brillants, et vous fait répéter la fin trois fois. « Il faut que je l'écrive avant de l'oublier. Un jour, je ferai un livre. « Contes de l'autre côté du Voile ». »"}],"effets":[],"choix":[],"fin":true},"ville":{"repliques":[{"qui":"seraphine","expression":"neutre","dit":"« Des lumières partout, la nuit ? Sans magie ? » Elle reste silencieuse un long moment. « Chez vous, personne n'a besoin d'Appelés. C'est peut-être ça, un monde heureux. »"}],"effets":[],"choix":[],"fin":true},"decue":{"repliques":[{"qui":"seraphine","expression":"neutre","dit":"Elle referme son carnet. « Tout est intéressant, quand on ne l'a jamais vu. » Elle sourit poliment, mais quelque chose s'est éteint."}],"effets":[],"choix":[],"fin":true}}},"sr-anneau":{"id":"sr-anneau","titre":"Séraphine — L'anneau d'Aldric","type":"individuel","lieu":"qarzim-bazar","decor":"qarzim-bazar","debut":"debut","disponible_si":{"flag":"seraphine-recrutee","affinite_palier":{"seraphine":"proche"}},"repetable":false,"romance":false,"quete":"q-seraphine","pnj":"seraphine","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"seraphine","expression":"neutre","dit":"Séraphine vous entraîne au fond du Bazar, chez un prêteur sur gages. Elle tremble. « Un marchand m'a écrit. Il a vu passer un anneau gravé d'un griffon. Celui de mon frère. »"},{"qui":"narrateur","expression":"neutre","dit":"Le prêteur sort l'anneau d'un coffret. Un griffon d'argent, une pierre bleue. Et, à l'intérieur, une inscription : « À A., de S. — reviens-moi »."},{"qui":"seraphine","expression":"tristesse","dit":"« C'est moi qui le lui ai offert. » Sa voix se brise. « Il l'avait au doigt le jour où il a disparu. »"}],"effets":[],"choix":[{"texte":"Demander au prêteur d'où il vient. (Charisme, difficulté 20)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":20,"reussite":"piste","echec":"rachat"},"effets":[]},{"texte":"Racheter l'anneau pour Séraphine. (100 or)","si":{"or_min":100},"visible_si_bloque":false,"effets":[{"affinite":{"seraphine":4},"or":-100}],"aller":"piste"}],"fin":false},"piste":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le prêteur finit par parler : l'anneau a été vendu par un marchand du nord, qui l'avait lui-même échangé contre de l'eau… à un homme en armure noire, sur le Mur d'Aube, il y a deux ans."},{"qui":"seraphine","expression":"neutre","dit":"« Deux ans. » Séraphine serre l'anneau. « Il y a deux ans, il était vivant. » Elle vous regarde, et pour la première fois depuis longtemps, elle sourit à travers ses larmes. « Merci. »"}],"effets":[{"flag":"aldric-vivant-indice","affinite":{"seraphine":10},"xp":100,"quete":{"id":"q-seraphine","etape":"rumeurs"}}],"choix":[],"fin":true},"rachat":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le prêteur ne dira rien de plus. Mais Séraphine repart avec l'anneau au doigt."},{"qui":"seraphine","expression":"neutre","dit":"« Il est vivant quelque part. Je le sens. » Elle serre votre main. « Tu m'aideras à le retrouver ? »"}],"effets":[{"affinite":{"seraphine":8},"quete":{"id":"q-seraphine","etape":"rumeurs"}}],"choix":[],"fin":true}}},"sr-jardin":{"id":"sr-jardin","titre":"Séraphine — Le jardin de nuit","type":"individuel","lieu":"qarzim-residence","decor":"qarzim-residence","debut":"debut","disponible_si":{"flag":"seraphine-recrutee","affinite_palier":{"seraphine":"amoureuse"}},"repetable":false,"romance":true,"pnj":"seraphine","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"seraphine","expression":"gene","dit":"Dans le jardin, sous les palmiers, Séraphine a fait apporter deux coupes d'eau fraîche et un plateau de dattes. « Pas de garde. Pas de protocole. Ce soir, je ne suis pas princesse. » Elle rougit. « Je suis juste… moi. Avec toi. »"}],"effets":[],"choix":[{"texte":"« Alors ce soir, je ne suis pas un Appelé. Juste moi. »","visible_si_bloque":false,"effets":[{"affinite":{"seraphine":6}}],"aller":"oui"}],"fin":false},"oui":{"repliques":[{"qui":"seraphine","expression":"joie","dit":"Elle rit, se lève, et vous tend la main pour une danse sans musique, pieds nus dans l'herbe. Au loin, Qarzim s'endort, et les étoiles du désert veillent sur vous…"},{"qui":"narrateur","expression":"neutre","dit":"(Fondu au noir.)"}],"effets":[],"choix":[],"fin":true}}},"av-archives":{"id":"av-archives","titre":"Aveline — La lettre de Valgrane","type":"individuel","lieu":"qarzim-residence","decor":"qarzim-residence","debut":"debut","disponible_si":{"flag":"seraphine-recrutee","affinite_min":{"aveline":45},"quete_etape":{"q-aveline":"archives"}},"repetable":false,"romance":false,"quete":"q-aveline","pnj":"aveline","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Aveline vous attend dans la bibliothèque de la Résidence, une lettre jaunie entre les mains. « Séraphine l'a fait sortir des archives royales. En secret. Elle a risqué gros. »"},{"qui":"aveline","expression":"colere","dit":"« C'est l'ordre de repli de Valgrane. Signé de mon père, oui. Mais regarde : le sceau du bas. Ce n'est pas celui de la Couronne. C'est celui de l'Ordre de la Lumière. »"},{"qui":"aveline","expression":"neutre","dit":"« Mon père n'a pas ouvert les portes. On lui a ordonné de se replier. L'Ordre a donné l'ordre… puis l'a laissé accuser. »"}],"effets":[],"choix":[{"texte":"« Nous irons jusqu'au bout. Même s'il faut regarder l'Ordre en face. »","visible_si_bloque":false,"effets":[{"affinite":{"aveline":8}}],"aller":"fin"},{"texte":"« Prends ton temps. On ne renverse pas l'Ordre sur une lettre. »","visible_si_bloque":false,"effets":[{"affinite":{"aveline":4}}],"aller":"fin"}],"fin":false},"fin":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Elle replie la lettre et vous la confie. « Garde-la. Si on me fouille, on ne la trouvera pas. » Elle vous regarde. « Je te fais confiance. Plus qu'à moi-même. »"}],"effets":[{"flag":"ordre-valgrane-indice","xp":100,"objet":"lettre-valgrane","quete":{"id":"q-aveline","etape":"verite"}}],"choix":[],"fin":true}}},"ch2-depart":{"id":"ch2-depart","titre":"Le départ","type":"groupe","lieu":"chateau","decor":"chateau-trone","debut":"debut","disponible_si":{"flag":"chapitre-1-fini","pas_flag":"ch2-depart-fait","date_min":{"annee":1015,"mois":1,"jour":1}},"repetable":false,"romance":false,"quete":"q-ch2-routes","pnj":"seraphine","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Germinal 1015. Trois ans ont passé depuis l'Appel. Les cicatrices de la Nuit des Lanternes se sont refermées ; pas celles des souvenirs."},{"qui":"seraphine","expression":"neutre","dit":"La princesse Séraphine [[t'attend||vous attend]] dans la salle des cartes, en tenue de voyage, les cheveux noués comme un soldat. « Enfin ! Mon père m'envoie à Qarzim. Officiellement : signer un traité de commerce avec la Concorde. »"},{"qui":"seraphine","expression":"neutre","dit":"« Officieusement : la Concorde vend des cristaux d'éther à tout le monde… y compris, dit-on, à des gens qui portent des sceaux violets. » Elle pose la main sur la carte du sud. « J'ai demandé [[un Appelé||des Appelés]] pour m'escorter. Je veux [[toi||vous]]. »"},{"qui":"aveline","expression":"neutre","dit":"Aveline se tient près de la porte, bras croisés. « Ordre du roi : j'accompagne la princesse. Et… [[toi||vous]] aussi, apparemment. » Elle ne cache pas tout à fait son sourire."},{"qui":"kaya","expression":"neutre","dit":"La porte s'ouvre à la volée. Kaya, sac au dos, oreilles dressées : « Qarzim ? Vous allez dans le désert sans guide ? Vous allez mourir de soif avant midi. J'en suis ! »"}],"effets":[],"choix":[{"texte":"« Une mission diplomatique ? Nous serons des modèles de politesse. »","visible_si_bloque":false,"effets":[{"reputation":{"couronne":3},"affinite":{"seraphine":3}}],"aller":"politesse"},{"texte":"« Si la Concorde aide les Cendres, je veux le savoir. Le traité, je m'en moque. »","visible_si_bloque":false,"effets":[{"flag":"enquete-concorde","affinite":{"seraphine":4,"aveline":2}}],"aller":"enquete"},{"texte":"« Kaya, c'est chez toi, là-bas ? Tu seras notre guide. »","visible_si_bloque":false,"effets":[{"affinite":{"kaya":5}}],"aller":"kaya"}],"fin":false},"politesse":{"repliques":[{"qui":"seraphine","expression":"joie","dit":"Séraphine éclate de rire. « Des modèles de politesse. Vous. Je garde la phrase pour la raconter à mon père. »"}],"effets":[],"choix":[],"suite":"preparatifs","fin":false},"enquete":{"repliques":[{"qui":"seraphine","expression":"neutre","dit":"« Exactement ce que je voulais entendre. » Elle baisse la voix. « Et pas un mot à la cour. La moitié des nobles a des parts dans les caravanes de la Concorde. »"}],"effets":[],"choix":[],"suite":"preparatifs","fin":false},"kaya":{"repliques":[{"qui":"kaya","expression":"joie","dit":"Kaya bombe le torse. « Chez moi, c'est le désert entier. Enfin… c'était. » Son sourire vacille une seconde. « La Concorde nous a pris nos terres. Mais je connais chaque dune. »"}],"effets":[],"choix":[],"suite":"preparatifs","fin":false},"preparatifs":{"repliques":[{"qui":"rowena","expression":"neutre","dit":"Dame Rowena vous a fait parvenir un mot : « La Guilde a un comptoir à Qarzim. Montrez-vous là-bas, l'intendant Ibrek vous trouvera du travail. Et ramenez la princesse entière. »"},{"qui":"narrateur","expression":"neutre","dit":"Trois jours plus tard, la caravane de la princesse quitte Lysmont par la porte du sud. Devant vous, la Route des Caravanes, et au bout, la Marche des Sables."}],"effets":[{"flag":["ch2-depart-fait","seraphine-recrutee","kaya-recrutee"],"quete":{"id":"q-ch2-routes","etape":"caravane"},"recruter":"seraphine","journal":"Germinal 1015 : {groupe} partent pour Qarzim avec la princesse Séraphine, Aveline et Kaya."},{"recruter":"kaya"}],"choix":[],"fin":true}}},"ch2-caravane":{"id":"ch2-caravane","titre":"La Route des Caravanes","type":"groupe","lieu":"route-des-caravanes","decor":"route-des-caravanes","debut":"debut","disponible_si":{"quete_etape":{"q-ch2-routes":"caravane"}},"repetable":false,"romance":false,"quete":"q-ch2-routes","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Dix jours de route. L'herbe d'Aubeclaire devient poussière, puis sable. Le soleil tape comme un marteau sur une enclume."},{"qui":"nadja","expression":"neutre","dit":"La caravane appartient à une courtière : une femme en voiles ocre, un carnet à la main, qui compte les tonneaux d'eau à voix haute. « Nadja Kesh. Chaque gorgée que vous buvez est notée. Princesse comprise. »"},{"qui":"kaya","expression":"neutre","dit":"Kaya s'arrête net, nez au vent. « Ça sent le cuir et le sang. Des gens nous attendent derrière ces rochers. »"}],"effets":[],"choix":[{"texte":"Préparer une contre-embuscade. (Esprit, difficulté 20)","visible_si_bloque":false,"test":{"carac":"ESP","difficulte":20,"reussite":"contre","echec":"surpris"},"effets":[]},{"texte":"Continuer et laisser venir : la caravane est bien gardée.","visible_si_bloque":false,"effets":[],"aller":"surpris"}],"fin":false},"contre":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous contournez les rochers. Les pillards, le dos tourné, guettent la caravane… et ne vous voient pas venir."}],"effets":[{"xp":40}],"choix":[],"suite":"combat","fin":false},"surpris":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Des cris. Des flèches. Des silhouettes au chèche turquoise dévalent la dune, cimeterres au clair."}],"effets":[],"choix":[],"suite":"combat","fin":false},"combat":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"caravane-pillards","victoire":"victoire","defaite":"defaite"},"fin":false},"victoire":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le dernier pillard lâche son arme. Un jeune, à peine seize ans, qui tremble sous son chèche."},{"qui":"nadja","expression":"neutre","dit":"Nadja enjambe un corps sans le regarder et rouvre son carnet. « Deux chameaux blessés, un tonneau percé. » Elle lève les yeux vers vous. « Et zéro mort de notre côté. Pas mal, pour des étrangers. »"}],"effets":[{"reputation":{"concorde":3},"affinite":{"nadja":3}}],"choix":[],"suite":"prisonnier","fin":false},"defaite":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous reprenez connaissance sous une toile tendue. Les gardes de la caravane ont repoussé les pillards à grand-peine."},{"qui":"nadja","expression":"neutre","dit":"« Trois chameaux, deux tonneaux et ma réputation. » Nadja soupire. « La prochaine fois, laissez-moi négocier. »"}],"effets":[],"choix":[],"suite":"prisonnier","fin":false},"prisonnier":{"repliques":[{"qui":"kaya","expression":"neutre","dit":"Kaya tient le jeune pillard par le col. « Il dit qu'on les a payés. Pas pour voler : pour retarder la princesse. »"}],"effets":[],"choix":[{"texte":"L'emmener à Qarzim : la garde de la ville le fera parler.","visible_si_bloque":false,"effets":[{"flag":"prisonnier-pillard"}],"aller":"arrivee"},{"texte":"Le laisser partir avec de l'eau. Ce n'est qu'un gamin.","visible_si_bloque":false,"effets":[{"flag":["prisonnier-pillard","pillard-epargne"],"affinite":{"kaya":2,"seraphine":3}}],"aller":"arrivee"}],"fin":false},"arrivee":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Au coucher du soleil, Qarzim apparaît : des coupoles bleues, des tours de terre ocre, et au-dessus de la ville, une lueur violette qui ne vient pas du ciel."},{"qui":"nadja","expression":"neutre","dit":"« Les cristaux d'éther. » Nadja range son carnet. « Toute la ville en brille. Si vous avez besoin de quelque chose à Qarzim — n'importe quoi — demandez Nadja Kesh, à la Porte des Caravanes. Pour un prix honnête. » Elle sourit. « Enfin, presque. »"}],"effets":[{"flag":["sables-ouverts","nadja-rencontree"],"xp":120,"quete":{"id":"q-ch2-routes","etape":"palais"},"recruter":"nadja","journal":"{groupe} arrivent à Qarzim avec la caravane de Nadja Kesh, après une embuscade de pillards."}],"choix":[],"fin":true}}},"ch2-palais":{"id":"ch2-palais","titre":"Le Prévôt de la Concorde","type":"groupe","lieu":"qarzim-palais","decor":"qarzim-palais","debut":"debut","disponible_si":{"quete_etape":{"q-ch2-routes":"palais"}},"repetable":false,"romance":false,"quete":"q-ch2-routes","pnj":"hassad","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le Palais de la Concorde est un rêve de marbre et de cristal. Des fontaines coulent dans des vasques violettes. Ici, même l'air sent l'argent."},{"qui":"hassad","expression":"neutre","dit":"Le Prévôt Hassad s'incline juste assez. « Princesse. Et les fameux Appelés. » Ses bagues-cristaux scintillent. « La Concorde est honorée. Elle serait plus honorée encore si le traité ne parlait pas des mines. »"},{"qui":"vashti","expression":"neutre","dit":"Une conseillère à l'éventail sourit derrière lui. « Les mines sont une affaire de Qarzim, Altesse. Les loups du désert les réclament, mais les loups réclament toujours. »"},{"qui":"kaya","expression":"colere","dit":"Kaya serre les poings. Ses oreilles se couchent en arrière."}],"effets":[],"choix":[],"suite":"question","fin":false},"question":{"parole_a":{"regle":{"race":["ourvalis","vulpin","demi-demon","sang-dragon"]},"question":{"qui":"hassad","expression":"neutre","dit":"Le Prévôt se tourne vers {nom}. « Et vous, {pseudo} ? Les Appelés sont-ils venus défendre les traités… ou les tribus ? »"},"reponses":[{"texte":"« Je suis ourvalis, Prévôt. Les « loups du désert », c'est moi. Choisissez mieux vos mots. »","si":{"race":"ourvalis"},"effets":[{"reputation":{"ourvalis":8,"concorde":-5},"affinite":{"kaya":6}}],"aller":"reponse"},{"texte":"« Les vulpins commercent avec vous depuis des siècles. Ne me faites pas croire que vous ignorez qui vit sur ces terres. »","si":{"race":"vulpin"},"effets":[{"reputation":{"ourvalis":4,"concorde":-2},"affinite":{"nadja":2}}],"aller":"reponse"},{"texte":"« On m'a souvent traité de monstre. Je sais reconnaître quand on parle des autres comme ça. »","si":{"race":["demi-demon","sang-dragon"]},"effets":[{"affinite":{"kaya":4,"seraphine":2}}],"aller":"reponse"},{"texte":"« Nous défendons la princesse. Le reste dépendra de ce que nous verrons. »","effets":[{"affinite":{"seraphine":3}}],"aller":"reponse"},{"texte":"« Les tribus vivaient ici avant vos mines. Ça compte, non ? »","effets":[{"reputation":{"ourvalis":5,"concorde":-4},"affinite":{"kaya":4}}],"aller":"reponse"},{"texte":"« Nous sommes là pour le traité. Et pour le buffet. »","effets":[{"affinite":{"seraphine":2}}],"aller":"reponse"}]},"repliques":[],"effets":[],"choix":[],"fin":false},"reponse":{"repliques":[{"qui":"hassad","expression":"neutre","dit":"Le Prévôt sourit sans que ses yeux bougent. « Intéressant. » Il fait un signe : un serviteur vous tend à chacun un petit cristal violet, serti d'argent. « Un présent de la Concorde. Que la lumière de l'éther éclaire vos chemins. »"},{"qui":"seraphine","expression":"neutre","dit":"Séraphine murmure sans remuer les lèvres : « Ne le portez pas sur vous. J'ai un mauvais pressentiment. »"}],"effets":[],"choix":[{"texte":"Accepter le cristal avec un grand sourire.","visible_si_bloque":false,"effets":[{"flag":"cadeau-hassad","reputation":{"concorde":5},"objet":"cristal-ether"}],"aller":"fin"},{"texte":"Refuser poliment : « Nous ne pouvons accepter un tel présent. »","visible_si_bloque":false,"effets":[{"reputation":{"concorde":-3},"affinite":{"seraphine":3,"kaya":2}}],"aller":"fin"},{"texte":"Accepter, et l'examiner discrètement. (Intelligence, difficulté 20)","visible_si_bloque":false,"test":{"carac":"INT","difficulte":20,"reussite":"examen","echec":"fin"},"effets":[]}],"fin":false},"examen":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Dans la lumière, le cristal palpite. Lentement. Comme une veine. À l'intérieur, une minuscule déchirure violette se referme et se rouvre."}],"effets":[{"flag":["cristal-palpite","cadeau-hassad"],"xp":50,"objet":"cristal-ether"}],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les négociations dureront des mois : la Concorde est patiente, et sa patience coûte cher. La princesse s'installe à la Résidence d'Aubeclaire."},{"qui":"seraphine","expression":"neutre","dit":"« Le grand banquet de la Résidence aura lieu le 10 Ardent de l'an prochain. Tout Qarzim y sera. » Elle soupire. « D'ici là, faites-vous connaître : la Guilde, les tribus, le Bazar. J'ai besoin d'yeux partout. »"}],"effets":[{"quete":{"id":"q-ch2-routes","etape":"complot"},"journal":"{groupe} rencontrent le Prévôt Hassad. La Concorde offre des cristaux d'éther en cadeau."}],"choix":[],"fin":true}}},"ch2-complot":{"id":"ch2-complot","titre":"Le banquet","type":"groupe","lieu":"qarzim-residence","decor":"qarzim-residence","debut":"debut","disponible_si":{"quete_etape":{"q-ch2-routes":"complot"},"date_min":{"annee":1016,"mois":6,"jour":10}},"repetable":false,"romance":false,"quete":"q-ch2-routes","pnj":"seraphine","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"10 Ardent 1016. La Résidence d'Aubeclaire brille de mille lanternes. Musiciens, plats d'argent, marchands de la Concorde en soie : tout Qarzim est là."},{"qui":"seraphine","expression":"neutre","dit":"Séraphine, en robe blanche et or, sourit à tout le monde. Mais sous la table, elle [[te||vous]] glisse un mot : « Vashti n'a pas quitté mon verre des yeux. »"},{"qui":"vashti","expression":"neutre","dit":"La conseillère Vashti lève sa coupe. « À l'amitié entre Aubeclaire et la Concorde ! » Les serviteurs remplissent les verres de la princesse."}],"effets":[],"choix":[],"suite":"poison","fin":false},"poison":{"parole_a":{"regle":{"classe":["alchimiste","guerisseur","ombre"]},"question":{"qui":"seraphine","expression":"neutre","dit":"Séraphine porte la coupe à ses lèvres, puis s'arrête et la tend discrètement à {nom}. « {pseudo}… Il y a quelque chose de bizarre avec ce vin, non ? »"},"reponses":[{"texte":"« Ne bois pas ! L'odeur d'amande… c'est du venin de scorpion bleu. »","si":{"classe":"alchimiste"},"effets":[{"flag":"poison-decouvert","affinite":{"seraphine":6}}],"aller":"assassins"},{"texte":"« Je sens une fièvre dans ce liquide. Comme une malédiction. Pose ça. »","si":{"classe":"guerisseur"},"effets":[{"flag":"poison-decouvert","affinite":{"seraphine":6}}],"aller":"assassins"},{"texte":"« Le serviteur qui t'a servie vient de disparaître. Mauvais signe. »","si":{"classe":"ombre"},"effets":[{"flag":"poison-decouvert","affinite":{"seraphine":6}}],"aller":"assassins"},{"texte":"« Dans le doute… » (lui prendre la coupe et la renverser sur la nappe)","effets":[{"flag":"poison-decouvert","affinite":{"seraphine":4}}],"aller":"assassins"},{"texte":"« Il est très bon. Pourquoi ? »","effets":[{"affinite":{"seraphine":1}}],"aller":"assassins"},{"texte":"« Laisse-moi goûter d'abord. » (héroïque, mais imprudent)","effets":[{"affinite":{"seraphine":5}}],"aller":"assassins"}]},"repliques":[],"effets":[],"choix":[],"fin":false},"assassins":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La coupe renversée fume en rongeant la nappe. Un silence glacé tombe sur la salle."},{"qui":"narrateur","expression":"neutre","dit":"Puis les serviteurs lâchent leurs plateaux. Sous les tuniques, des poignards courbes. Des voiles noirs. La Main de Sable."},{"qui":"aveline","expression":"colere","dit":"« Protégez la princesse ! » Aveline renverse une table pour faire barrage."}],"effets":[],"choix":[],"combat":{"rencontre":"assassins-banquet","victoire":"poursuite","defaite":"blessee"},"fin":false},"blessee":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Un poignard a effleuré le bras de Séraphine. La garde de la Résidence repousse les assassins, qui s'enfuient par les toits."}],"effets":[{"flag":"seraphine-blessee","affinite":{"seraphine":-2}}],"choix":[],"suite":"poursuite","fin":false},"poursuite":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Une silhouette voilée de noir vous observe depuis la coupole d'en face. Elle s'incline, moqueuse, et s'éloigne de toit en toit."},{"qui":"kaya","expression":"neutre","dit":"« C'est le chef ! Je le sens d'ici. » Kaya bondit déjà vers la fenêtre."}],"effets":[],"choix":[{"texte":"Le poursuivre sur les toits de Qarzim.","visible_si_bloque":false,"effets":[],"aller":"toits"},{"texte":"Rester auprès de la princesse : c'est peut-être une diversion.","visible_si_bloque":false,"effets":[{"affinite":{"seraphine":4,"aveline":3}}],"aller":"diversion"}],"fin":false},"diversion":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Bien vu : un deuxième groupe d'assassins surgit des cuisines. Vous les attendiez."}],"effets":[],"choix":[],"suite":"toits","fin":false},"toits":{"repliques":[{"qui":"kezir","expression":"neutre","dit":"Sur la plus haute terrasse, l'homme voilé vous attend, deux lames à la main. « Kezir. On m'a payé pour une princesse. Les Appelés seront un bonus. »"}],"effets":[],"choix":[],"combat":{"rencontre":"kezir-toits","victoire":"preuve","defaite":"fuite-kezir"},"fin":false},"fuite-kezir":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Kezir vous laisse au sol et disparaît dans la nuit. Mais dans sa fuite, il a perdu quelque chose."}],"effets":[],"choix":[],"suite":"preuve","fin":false},"preuve":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Sur la terrasse, un insigne de bronze : une main tenant un grain de sable. Et, enroulée autour, une lettre de paiement… scellée du sceau personnel de la conseillère Vashti Orren."},{"qui":"narrateur","expression":"neutre","dit":"Au dos de la lettre, une rune violette griffonnée à la hâte. La même que sur le sceau cendré de la Crypte.","si":{"flag":"sceau-trouve"}}],"effets":[{"xp":150,"objet":"insigne-main-de-sable"}],"choix":[{"texte":"Dénoncer Vashti devant le Conseil de la Concorde, preuve à l'appui.","visible_si_bloque":false,"effets":[{"flag":"vashti-denoncee","reputation":{"concorde":-10,"couronne":10},"affinite":{"seraphine":4}}],"aller":"denonce"},{"texte":"Donner la lettre à Nadja : elle saura quoi en faire, sans bruit.","visible_si_bloque":false,"effets":[{"flag":"preuve-nadja","affinite":{"nadja":8}}],"aller":"nadja"},{"texte":"Aller voir le Prévôt Hassad en privé : qu'il nous doive une faveur.","visible_si_bloque":false,"effets":[{"flag":"hassad-redevable","reputation":{"concorde":8}}],"aller":"hassad"}],"fin":false},"denonce":{"repliques":[{"qui":"vashti","expression":"neutre","dit":"Devant le Conseil, Vashti pâlit, puis rit. « Une lettre ? N'importe qui peut voler un sceau. » Mais personne ne rit avec elle. Elle est arrêtée le soir même… et retrouvée morte dans sa cellule à l'aube."},{"qui":"seraphine","expression":"neutre","dit":"« Quelqu'un ne voulait pas qu'elle parle. » Séraphine fixe la fenêtre. « Quelqu'un de plus haut. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"nadja":{"repliques":[{"qui":"nadja","expression":"neutre","dit":"Nadja lit la lettre deux fois, puis la plie avec un soin infini. « Vashti me doit maintenant beaucoup plus que je ne lui dois. » Pour la première fois, son sourire est vrai. « Merci. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"hassad":{"repliques":[{"qui":"hassad","expression":"neutre","dit":"Le Prévôt brûle la lettre à la flamme d'une bougie sans la lire jusqu'au bout. « La Concorde n'oublie jamais une dette. » Le lendemain, Vashti a quitté Qarzim. Personne ne sait où."}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"seraphine","expression":"neutre","dit":"Plus tard, sur la terrasse de la Résidence, Séraphine tient son verre d'eau à deux mains. « Merci. Vraiment. » Elle hésite. « Le Grand Bazar ouvre le premier jour de Brumaire. Les gens y parlent. On y apprendra peut-être qui a payé Vashti. »"}],"effets":[{"quete":{"id":"q-ch2-routes","etape":"bazar"},"journal":"10 Ardent 1016 : tentative d'assassinat contre la princesse Séraphine à Qarzim. La Main de Sable était payée par la conseillère Vashti."}],"choix":[],"fin":true}}},"ch2-bazar":{"id":"ch2-bazar","titre":"Le Grand Bazar","type":"groupe","lieu":"qarzim-bazar","decor":"qarzim-bazar","debut":"debut","disponible_si":{"quete_etape":{"q-ch2-routes":"bazar"},"date_min":{"annee":1016,"mois":7,"jour":1}},"repetable":false,"romance":false,"quete":"q-ch2-routes","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"1er Brumaire 1016. Le Grand Bazar de Qarzim s'éveille : des caravanes de tout le continent, des tapis volants (qui ne volent pas), des épices en montagnes, des cris dans dix langues."},{"qui":"narrateur","expression":"neutre","dit":"Et partout, des cristaux d'éther : en colliers, en lampes, en poudre « contre la fatigue ». Les marchands de la Concorde les vendent par caisses entières."},{"qui":"faelis","expression":"neutre","dit":"Sous une tente verte, une elfe aux cheveux d'argent vend des herbes. Elle vous fixe longuement. « Des Appelés. Ici. Avec ça plein les poches. » Elle désigne les cristaux d'un geste dégoûté."}],"effets":[],"choix":[{"texte":"« Vous savez quelque chose sur ces cristaux ? »","visible_si_bloque":false,"effets":[],"aller":"faelis"},{"texte":"Montrer le sceau cendré à l'elfe.","si":{"objet":"sceau-cendre"},"visible_si_bloque":false,"effets":[],"aller":"sceau"}],"fin":false},"sceau":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"À l'instant où le sceau sort du sac, tous les cristaux de la tente se mettent à vibrer. Un bourdonnement monte, aigu, et des lueurs violettes dansent sur les toiles."},{"qui":"faelis","expression":"surprise","dit":"L'elfe recule, livide. « Rangez ça. Tout de suite. » Elle respire mieux quand le sceau a disparu. « Ils se reconnaissent. Ils viennent du même endroit. »"}],"effets":[{"flag":"cristaux-resonnent","xp":60}],"choix":[],"suite":"faelis","fin":false},"faelis":{"repliques":[{"qui":"faelis","expression":"neutre","dit":"« Je m'appelle Faelis. Je viens de Sylvenoire. » Elle baisse la voix. « Chez nous, on enseigne que le Voile n'est pas une idée. C'est une chose. Une peau entre les mondes. Et une peau qu'on gratte… finit par saigner. »"},{"qui":"faelis","expression":"neutre","dit":"« Ces cristaux ne poussent pas dans la roche. Ce sont des éclats. Des éclats du Voile, tombés lors de la Déchirure. Chaque cristal qu'on arrache affaiblit ce qui reste. »"}],"effets":[],"choix":[{"texte":"« Comment pouvez-vous en être sûre ? » (Intelligence, difficulté 21)","visible_si_bloque":false,"test":{"carac":"INT","difficulte":21,"reussite":"preuve","echec":"doute"},"effets":[]},{"texte":"« Si c'est vrai, la Concorde doit l'apprendre. »","visible_si_bloque":false,"effets":[],"aller":"concorde"}],"fin":false},"preuve":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Faelis déroule un vieux parchemin : un dessin de cristal, des runes elfiques, et une phrase traduite à la main. « Ce que nous avons déchiré, la terre l'a gardé en éclats. »"},{"qui":"faelis","expression":"neutre","dit":"« Ce parchemin est une copie. L'original est gravé dans les Ruines de Sel, au sud. Les elfes y sont venus il y a mille ans, pour réparer leur faute. Ils ont échoué. »"}],"effets":[{"flag":"indice-dechirure","xp":80}],"choix":[],"suite":"concorde","fin":false},"doute":{"repliques":[{"qui":"faelis","expression":"neutre","dit":"« Vous ne me croyez pas ? » Elle hausse les épaules. « Allez voir les Ruines de Sel, au sud. Les anciens y ont tout écrit. Si les tempêtes vous laissent passer. »"}],"effets":[],"choix":[],"suite":"concorde","fin":false},"concorde":{"repliques":[{"qui":"faelis","expression":"neutre","dit":"« La Concorde le sait. Elle s'en moque. Un cristal vaut plus qu'un village. » Elle range ses herbes. « Les grandes tempêtes viendront au printemps. Les Ruines de Sel ne se montrent qu'après, quand le vent a déplacé les dunes. »"},{"qui":"nadja","expression":"neutre","dit":"Nadja, qui écoutait depuis l'étal voisin, s'approche. « Une carte des Ruines, ça se trouve. Ça se paie, mais ça se trouve. » Elle hésite. « Et si l'elfe dit vrai… je travaille pour les gens qui vendent la fin du monde au détail. »"}],"effets":[{"flag":"carte-ruines","quete":{"id":"q-ch2-routes","etape":"tempete"},"journal":"Grand Bazar de 1016 : une elfe de Sylvenoire affirme que les cristaux d'éther sont des éclats du Voile."}],"choix":[],"fin":true}}},"ch2-tempete":{"id":"ch2-tempete","titre":"La tempête et les Ruines de Sel","type":"groupe","lieu":"ruines-de-sel","decor":"ruines-de-sel","debut":"debut","disponible_si":{"quete_etape":{"q-ch2-routes":"tempete"},"date_min":{"annee":1017,"mois":4,"jour":1}},"repetable":false,"romance":false,"quete":"q-ch2-routes","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Solaire 1017. Grâce à la carte de Nadja, vous êtes à deux jours des Ruines de Sel quand le ciel devient jaune."},{"qui":"kaya","expression":"peur","dit":"Kaya renifle l'air, puis attrape la bride du premier chameau. « La grande tempête ! Il faut un abri. Maintenant ! »"},{"qui":"narrateur","expression":"neutre","dit":"Un mur de sable haut comme une montagne avale l'horizon. Vous courez. Devant vous, des colonnes blanches sortent des dunes : les Ruines."}],"effets":[],"choix":[{"texte":"Se réfugier dans les Ruines.","visible_si_bloque":false,"effets":[],"aller":"entree"}],"fin":false},"entree":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Un escalier de sel cristallisé descend sous la cité morte. Le vent hurle au-dessus de vos têtes. En bas, des yeux turquoise s'allument dans le noir."}],"effets":[],"choix":[],"donjon":{"id":"ruines-de-sel","sortie":"sortie","abandon":"abandon"},"fin":false},"abandon":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Épuisés, vous remontez l'escalier de sel. Le Roi de Sel n'a pas bougé de son trône : il attendra encore mille ans."},{"qui":"narrateur","expression":"neutre","dit":"Mais vous avez vu la fresque. Les elfes en cercle, le ciel déchiré, les éclats violets qui tombent… et la phrase gravée en dessous, que Séraphine a recopiée en tremblant."},{"qui":"seraphine","expression":"neutre","dit":"« « Ce que nous avons déchiré, la terre l'a gardé en éclats. » » Elle range sa copie. « Il faut quelqu'un pour lire ça. Quelqu'un de Sylvenoire. »"}],"effets":[{"flag":"ruines-explorees","xp":100,"quete":{"id":"q-ch2-routes","etape":"revolte"},"journal":"Solaire 1017 : dans les Ruines de Sel, {groupe} découvrent une fresque elfique sur la Déchirure."}],"choix":[],"fin":true},"sortie":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Quand vous remontez, la tempête est passée. Le désert a changé de forme : les dunes ont avancé de cent pas."},{"qui":"narrateur","expression":"neutre","dit":"Dans votre sac, la tablette d'argile pèse plus lourd qu'elle ne devrait. Les mots elfiques gravés dessus brillent faiblement quand on les touche."},{"qui":"seraphine","expression":"neutre","dit":"Séraphine la retourne entre ses mains. « Il faut quelqu'un pour lire ça. Quelqu'un de Sylvenoire. » Elle sourit faiblement. « On dirait que nos routes ne font que commencer. »"}],"effets":[{"flag":"ruines-explorees","xp":200,"quete":{"id":"q-ch2-routes","etape":"revolte"},"journal":"Solaire 1017 : dans les Ruines de Sel, {groupe} trouvent une tablette elfique qui parle de la Déchirure."}],"choix":[],"fin":true}}},"ch2-revolte":{"id":"ch2-revolte","titre":"La révolte des Lunecroc","type":"groupe","lieu":"campement-lunecroc","decor":"campement-lunecroc","debut":"debut","disponible_si":{"quete_etape":{"q-ch2-routes":"revolte"},"date_min":{"annee":1017,"mois":12,"jour":1}},"repetable":false,"romance":false,"quete":"q-ch2-routes","pnj":"sorha","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Aurore 1017. Au campement Lunecroc, les tambours de guerre résonnent depuis trois nuits."},{"qui":"sorha","expression":"neutre","dit":"L'Ancienne Sorha vous reçoit sous sa tente, appuyée sur son bâton gravé de loups. « Mon petit-fils Tavek veut attaquer les mines d'éther demain. Les mercenaires de la Concorde l'attendent. Ce sera un massacre. »"},{"qui":"kaya","expression":"tristesse","dit":"Kaya regarde ses pieds. « Tavek a toujours été le plus courageux. Et le plus têtu. Il dit que si on ne reprend pas la terre maintenant, il n'y aura plus de terre à reprendre. »"},{"qui":"tavek","expression":"neutre","dit":"Le chef de guerre entre sans s'annoncer, griffes de fer aux poings. « Les Appelés de la princesse. Vous êtes venus nous dire d'être sages ? »"},{"qui":"narrateur","expression":"neutre","dit":"Un messager couvert de poussière apporte une lettre : la Concorde promet « une prime généreuse » à quiconque aidera à protéger les mines.","si":{"flag":"hassad-redevable"}}],"effets":[],"choix":[{"texte":"Soutenir la tribu Lunecroc : vous attaquerez les mines avec Tavek.","visible_si_bloque":false,"effets":[{"flag":"soutien-lunecroc","reputation":{"ourvalis":20,"concorde":-20},"affinite":{"kaya":10,"seraphine":-3}}],"aller":"attaque"},{"texte":"Défendre les mines : la paix avec la Concorde avant tout.","visible_si_bloque":false,"effets":[{"flag":["soutien-concorde","heros:trahison-lunecroc"],"reputation":{"concorde":20,"ourvalis":-25},"affinite":{"kaya":-15}}],"aller":"defense"},{"texte":"Négocier une trêve entre Tavek et la Concorde. (Charisme, difficulté 22)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":22,"reussite":"treve","echec":"treve-ratee"},"effets":[]}],"fin":false},"attaque":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"À l'aube, les guerriers lunecroc dévalent la falaise en hurlant. Vous êtes en tête. Aux mines, le capitaine Orlen Vask vous attend, cuirasse dorée au soleil."},{"qui":"vask","expression":"neutre","dit":"« Des Appelés avec des loups. La Concorde va adorer cette histoire. » Il lève son fendoir. « Feu à volonté ! »"}],"effets":[],"choix":[],"combat":{"rencontre":"revolte-vask","victoire":"mines-prises","defaite":"repli"},"fin":false},"mines-prises":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vask s'enfuit à travers le désert. Les mercenaires jettent leurs lances. Sur la plus haute galerie, Tavek plante le bâton de Sorha dans la roche violette."},{"qui":"tavek","expression":"neutre","dit":"« Cette terre est à nous. » Il se tourne vers vous, et pour la première fois, il s'incline. « Merci, Appelés. Les Lunecroc ne l'oublieront jamais. »"}],"effets":[{"flag":"mines-lunecroc","reputation":{"ourvalis":10}}],"choix":[],"suite":"fin","fin":false},"repli":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La charge se brise sur les boucliers dorés. Vous couvrez la retraite des blessés, pas à pas, jusqu'à la falaise."},{"qui":"tavek","expression":"neutre","dit":"Tavek saigne mais vit. « Vous êtes restés. Jusqu'au bout. » Il serre la main de Kaya. « On reviendra. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"defense":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous prenez position sur les galeries des mines, aux côtés des mercenaires. Quand la charge lunecroc arrive, Kaya n'est pas avec vous."},{"qui":"tavek","expression":"neutre","dit":"Tavek vous voit et s'arrête net. « Toi aussi ? » Il crache dans le sable. « Alors tu mourras avec l'or de la Concorde. »"}],"effets":[],"choix":[],"combat":{"rencontre":"revolte-tavek","victoire":"mines-tenues","defaite":"mines-perdues"},"fin":false},"mines-tenues":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Tavek recule, blessé, et ordonne la retraite. La Concorde garde ses mines. Le Prévôt vous fera envoyer une bourse d'or."},{"qui":"kaya","expression":"colere","dit":"Le soir, Kaya vous attend à la porte de l'auberge. Elle ne dit rien. Elle vous regarde seulement, longtemps. Puis elle s'en va."}],"effets":[{"flag":"mines-concorde","or":200}],"choix":[],"suite":"fin","fin":false},"mines-perdues":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les Lunecroc prennent les mines. Tavek vous épargne, avec mépris. « Va dire à tes marchands ce qui arrive quand on vole la terre des loups. »"}],"effets":[{"flag":"mines-lunecroc"}],"choix":[],"suite":"fin","fin":false},"treve":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous parlez toute la nuit. À Tavek, à Sorha, puis au Prévôt Hassad, venu en personne sous un dais de soie."},{"qui":"hassad","expression":"neutre","dit":"« Un tiers des mines rendu aux Lunecroc. Et la Concorde achète leur protection, au lieu de payer des mercenaires. » Le Prévôt plisse les yeux. « Vous feriez de redoutables marchands. »"},{"qui":"sorha","expression":"joie","dit":"L'Ancienne Sorha pose sa main ridée sur votre front. « Le vent se souviendra de ton nom. »"}],"effets":[{"flag":"treve-sables","reputation":{"ourvalis":15,"concorde":5},"affinite":{"kaya":8,"seraphine":5,"nadja":3},"xp":200}],"choix":[],"suite":"fin","fin":false},"treve-ratee":{"repliques":[{"qui":"tavek","expression":"neutre","dit":"Tavek vous coupe la parole. « Des mots. Toujours des mots. » Il sort de la tente. La guerre aura lieu, avec ou sans vous."}],"effets":[],"choix":[{"texte":"Alors combattre avec les Lunecroc.","visible_si_bloque":false,"effets":[{"flag":"soutien-lunecroc","reputation":{"ourvalis":15,"concorde":-15},"affinite":{"kaya":6}}],"aller":"attaque"},{"texte":"Rester à l'écart : ce n'est pas votre guerre.","visible_si_bloque":false,"effets":[{"affinite":{"kaya":-5}}],"aller":"ecart"}],"fin":false},"ecart":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La bataille dure une journée. Les Lunecroc reprennent une galerie, en perdent deux. Au soir, chacun compte ses morts, et rien n'a changé."}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"seraphine","expression":"neutre","dit":"Quelques jours plus tard, une lettre royale arrive à Qarzim : le traité est signé, ou presque. Séraphine la lit, puis la jette sur la table. « Mon père veut que je rentre. Moi, je veux savoir ce que dit cette tablette. »"},{"qui":"aveline","expression":"neutre","dit":"Aveline déplie une carte. « Sylvenoire. La forêt des elfes, à l'ouest d'Aubeclaire. Personne n'y entre sans invitation. » Elle hausse les épaules. « Il faudra donc une invitation. »"},{"qui":"narrateur","expression":"neutre","dit":"La Marche des Sables a changé. Vous aussi. Derrière vous, les dunes effacent vos traces ; devant vous, une forêt qui se souvient."}],"effets":[{"xp":300,"terminer_quete":"q-ch2-routes"},{"fin_chapitre":2}],"choix":[],"fin":true}}},"sq-chacals-guilde":{"id":"sq-chacals-guilde","titre":"La Grande Mère des chacals : l'affaire","type":"groupe","lieu":"guilde-qarzim","decor":"guilde","debut":"debut","disponible_si":{"flag":"sables-ouverts","pas_flag":"matriarche-acceptee"},"repetable":false,"romance":false,"quete":"q-matriarche","pnj":"ibrek","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"ibrek","expression":"neutre","dit":"Ibrek remonte ses lunettes sur son museau roux. « Sept chameaux en un mois, dans le Canyon des Chacals. Les caravaniers parlent d'une matriarche blanche, grande comme un poney. Personne ne veut le contrat : il paie mal. »"},{"qui":"kaya","expression":"neutre","dit":"Kaya ricane. « Il paie mal, mais il paie en gloire. »","si":{"flag":"kaya-recrutee"}}],"effets":[],"choix":[{"texte":"« On prend. »","visible_si_bloque":false,"effets":[{"flag":"matriarche-acceptee","quete":{"id":"q-matriarche","etape":"canyon"}}],"aller":"fin"}],"fin":false},"fin":{"repliques":[{"qui":"ibrek","expression":"neutre","dit":"« Le canyon est au sud-est. Prenez de l'eau, et ne faites pas confiance à l'écho. »"}],"effets":[],"choix":[],"fin":true}}},"sq-chacals-canyon":{"id":"sq-chacals-canyon","titre":"La Grande Mère des chacals : le canyon","type":"groupe","lieu":"canyon-des-chacals","decor":"canyon-des-chacals","debut":"debut","disponible_si":{"quete_etape":{"q-matriarche":"canyon"}},"repetable":false,"romance":false,"quete":"q-matriarche","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les parois rouges se resserrent. Des jappements résonnent de partout et de nulle part à la fois."}],"effets":[],"choix":[{"texte":"Avancer en silence et repérer la meute. (Agilité, difficulté 20)","visible_si_bloque":false,"test":{"carac":"AGI","difficulte":20,"reussite":"discret","echec":"repere"},"effets":[]},{"texte":"Avancer d'un pas ferme : qu'ils viennent.","visible_si_bloque":false,"effets":[],"aller":"repere"}],"fin":false},"discret":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous repérez les guetteurs avant qu'ils ne vous voient. La tanière est au fond du canyon, sous un surplomb."}],"effets":[{"xp":40,"quete":{"id":"q-matriarche","etape":"taniere"}}],"choix":[],"fin":true},"repere":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Une meute surgit des rochers !"}],"effets":[],"choix":[],"combat":{"rencontre":"chacals-dunes","victoire":"apres","defaite":"apres"},"fin":false},"apres":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les survivants fuient vers le fond du canyon, sous un surplomb. Vous savez où aller."}],"effets":[{"quete":{"id":"q-matriarche","etape":"taniere"}}],"choix":[],"fin":true}}},"sq-chacals":{"id":"sq-chacals","titre":"La Grande Mère des chacals : la tanière","type":"groupe","lieu":"canyon-des-chacals","decor":"canyon-des-chacals","debut":"debut","disponible_si":{"quete_etape":{"q-matriarche":"taniere"}},"repetable":false,"romance":false,"quete":"q-matriarche","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Sous le surplomb, une chacale énorme, au pelage presque blanc, se dresse devant ses petits. Ses yeux sont fatigués. Ses côtes saillent."},{"qui":"kaya","expression":"neutre","dit":"Kaya fronce les sourcils. « Elle a faim. Les mines ont fait fuir tout le gibier du canyon. »","si":{"flag":"kaya-recrutee"}}],"effets":[],"choix":[{"texte":"Combattre la matriarche.","visible_si_bloque":false,"effets":[],"aller":"combat"},{"texte":"Lui laisser de la viande et la chasser loin des routes. (Esprit, difficulté 22)","visible_si_bloque":false,"test":{"carac":"ESP","difficulte":22,"reussite":"paix","echec":"combat"},"effets":[]}],"fin":false},"combat":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"chacals-matriarche","victoire":"victoire","defaite":"defaite"},"fin":false},"victoire":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La Grande Mère tombe. Ses petits s'enfuient dans les rochers."}],"effets":[{"flag":"matriarche-tuee","quete":{"id":"q-matriarche","etape":"retour"}}],"choix":[],"fin":true},"defaite":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La matriarche vous laisse au sol et emporte ses petits vers le désert profond. Elle ne reviendra pas."}],"effets":[{"quete":{"id":"q-matriarche","etape":"retour"}}],"choix":[],"fin":true},"paix":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La chacale renifle la viande, vous fixe longuement… puis s'éloigne vers le sud avec toute sa meute. Les routes seront tranquilles."},{"qui":"kaya","expression":"joie","dit":"Kaya vous regarde avec un respect nouveau. « Tu parles aux bêtes, maintenant ? »","si":{"flag":"kaya-recrutee"}}],"effets":[{"flag":"matriarche-epargnee","reputation":{"ourvalis":5},"affinite":{"kaya":5},"xp":120,"quete":{"id":"q-matriarche","etape":"retour"}}],"choix":[],"fin":true}}},"sq-chacals-retour":{"id":"sq-chacals-retour","titre":"La Grande Mère des chacals : le retour","type":"groupe","lieu":"guilde-qarzim","decor":"guilde","debut":"debut","disponible_si":{"quete_etape":{"q-matriarche":"retour"}},"repetable":false,"romance":false,"quete":"q-matriarche","pnj":"ibrek","rend_quete":true,"noeuds":{"debut":{"repliques":[{"qui":"ibrek","expression":"neutre","dit":"« Le canyon est sûr ? Parfait. » Ibrek trempe sa plume. « Je note : contrat rempli, avec… mention. »"}],"effets":[{"xp":250,"or":90,"points_guilde":120,"terminer_quete":"q-matriarche"}],"choix":[],"fin":true}}},"sq-puits-ziyane":{"id":"sq-puits-ziyane","titre":"Les puits asséchés : l'inquiétude de Ziyane","type":"groupe","lieu":"qarzim-oasis","decor":"qarzim-oasis","debut":"debut","disponible_si":{"flag":"sables-ouverts","pas_flag":"puits-acceptes"},"repetable":false,"romance":false,"quete":"q-puits","pnj":"ziyane","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"ziyane","expression":"neutre","dit":"Mère Ziyane trempe la main dans le bassin de l'auberge. « Il baisse. Chaque semaine, un doigt de moins. Le vieux canal de l'Oasis passe par les puits du sud… et mon grand-père disait qu'il n'était jamais à sec. »"}],"effets":[],"choix":[{"texte":"« Nous irons voir. »","visible_si_bloque":false,"effets":[{"flag":"puits-acceptes","quete":{"id":"q-puits","etape":"puits"}}],"aller":"fin"}],"fin":false},"fin":{"repliques":[{"qui":"ziyane","expression":"neutre","dit":"« Que les puits vous soient doux. » Elle vous remplit les gourdes, gratuitement."}],"effets":[{"objet":"eau-d-oasis"}],"choix":[],"fin":true}}},"sq-puits-canal":{"id":"sq-puits-canal","titre":"Les puits asséchés : le vieux canal","type":"groupe","lieu":"puits-asseches","decor":"puits-asseches","debut":"debut","disponible_si":{"quete_etape":{"q-puits":"puits"}},"repetable":false,"romance":false,"quete":"q-puits","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les puits sont à sec. Mais dans le canal, les traces sont fraîches : des pelles, des roues de chariot… et un barrage de planches neuves qui détourne l'eau vers l'est."},{"qui":"narrateur","expression":"neutre","dit":"Vers l'est. Vers les mines d'éther."}],"effets":[{"quete":{"id":"q-puits","etape":"mines"}}],"choix":[],"fin":true}}},"sq-puits-mines":{"id":"sq-puits-mines","titre":"Les puits asséchés : l'eau des mines","type":"groupe","lieu":"mines-ether","decor":"mines-ether","debut":"debut","disponible_si":{"quete_etape":{"q-puits":"mines"}},"repetable":false,"romance":false,"quete":"q-puits","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Aux mines, l'eau du canal sert à laver le minerai violet. Des bassins entiers, troubles, gaspillés, puis rejetés dans le sable."},{"qui":"vask","expression":"neutre","dit":"Un capitaine en cuirasse dorée s'approche. « Propriété de la Concorde. Circulez. »"}],"effets":[],"choix":[{"texte":"Détruire le barrage cette nuit, en silence.","visible_si_bloque":false,"effets":[],"aller":"sabotage"},{"texte":"Exiger que l'eau soit rendue à Qarzim.","visible_si_bloque":false,"effets":[],"aller":"combat"},{"texte":"Acheter les gardes pour qu'ils « oublient » le barrage. (100 or)","si":{"or_min":100},"visible_si_bloque":false,"effets":[{"or":-100}],"aller":"achat"}],"fin":false},"sabotage":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les planches cèdent dans un grand fracas d'eau. Le canal se remplit. Au loin, des cris : on vous a vus."}],"effets":[],"choix":[],"combat":{"rencontre":"mercenaires-mines","victoire":"fini","defaite":"fini"},"fin":false},"combat":{"repliques":[{"qui":"vask","expression":"neutre","dit":"« Exiger ? » Le capitaine rit. « Gardes ! »"}],"effets":[],"choix":[],"combat":{"rencontre":"mercenaires-mines","victoire":"force","defaite":"fini"},"fin":false},"force":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les mercenaires battus démontent eux-mêmes le barrage, sous vos yeux."}],"effets":[],"choix":[],"suite":"fini","fin":false},"achat":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"L'or change de main. Au matin, le barrage a « mystérieusement » disparu."}],"effets":[{"reputation":{"concorde":-3}}],"choix":[],"suite":"fini","fin":false},"fini":{"repliques":[],"effets":[{"flag":"eau-rendue","reputation":{"concorde":-5},"quete":{"id":"q-puits","etape":"retour"}}],"choix":[],"fin":true}}},"sq-puits-retour":{"id":"sq-puits-retour","titre":"Les puits asséchés : le retour","type":"groupe","lieu":"qarzim-oasis","decor":"qarzim-oasis","debut":"debut","disponible_si":{"quete_etape":{"q-puits":"retour"}},"repetable":false,"romance":false,"quete":"q-puits","pnj":"ziyane","rend_quete":true,"noeuds":{"debut":{"repliques":[{"qui":"ziyane","expression":"joie","dit":"Le bassin déborde presque. Mère Ziyane pleure et rit en même temps. « Vous dormirez ici quand vous voudrez. Et la première nuit, c'est la maison qui offre ! »"}],"effets":[{"xp":260,"or":60,"objet":["eau-d-oasis","eau-d-oasis"],"terminer_quete":"q-puits"}],"choix":[],"fin":true}}},"sq-fantome-rumeur":{"id":"sq-fantome-rumeur","titre":"La caravane fantôme : une vieille histoire","type":"groupe","lieu":"qarzim-bazar","decor":"qarzim-bazar","debut":"debut","disponible_si":{"flag":"sables-ouverts","pas_flag":"fantome-acceptee"},"repetable":false,"romance":false,"quete":"q-caravane-fantome","pnj":"ouzram","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"ouzram","expression":"neutre","dit":"Maître Ouzram cesse de polir une lame. « Il y a vingt ans, la caravane de mon frère, Belkhir, s'est perdue dans les Dunes chantantes. Certaines nuits, des caravaniers voient des lanternes là-bas… et entendent des clochettes de chameaux. »"},{"qui":"ouzram","expression":"neutre","dit":"« Je ne crois pas aux fantômes. Mais je voudrais savoir. »"}],"effets":[],"choix":[{"texte":"« Nous irons voir, Maître Ouzram. »","visible_si_bloque":false,"effets":[{"flag":"fantome-acceptee","quete":{"id":"q-caravane-fantome","etape":"dunes"}}],"aller":"fin"}],"fin":false},"fin":{"repliques":[],"effets":[],"choix":[],"fin":true}}},"sq-fantome-dunes":{"id":"sq-fantome-dunes","titre":"La caravane fantôme : les Dunes chantantes","type":"groupe","lieu":"dunes-chantantes","decor":"dunes-chantantes","debut":"debut","disponible_si":{"quete_etape":{"q-caravane-fantome":"dunes"}},"repetable":false,"romance":false,"quete":"q-caravane-fantome","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La nuit tombe. Les dunes chantent, une note longue et triste. Puis, au loin : des clochettes. Des lanternes. Une file de chameaux translucides avance lentement."},{"qui":"narrateur","expression":"neutre","dit":"À la tête de la caravane, un homme sans visage, couvert de sel, lève la main. Les chameaux s'arrêtent. Les chacals sortent de l'ombre."}],"effets":[],"choix":[],"combat":{"rencontre":"caravane-fantome","victoire":"belkhir","defaite":"belkhir"},"fin":false},"belkhir":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les lanternes s'éteignent une à une. Dans le sable, à la place du chef de caravane, une boîte de cuivre gravée du nom « Belkhir Telli », et une poignée de cendres."},{"qui":"narrateur","expression":"neutre","dit":"Une voix, très faible, dans le chant des dunes : « …l'oasis… ramenez-moi à l'oasis… »"}],"effets":[{"quete":{"id":"q-caravane-fantome","etape":"oasis"}}],"choix":[],"fin":true}}},"sq-fantome-oasis":{"id":"sq-fantome-oasis","titre":"La caravane fantôme : l'oasis perdue","type":"groupe","lieu":"oasis-perdue","decor":"oasis-perdue","debut":"debut","disponible_si":{"quete_etape":{"q-caravane-fantome":"oasis"}},"repetable":false,"romance":false,"quete":"q-caravane-fantome","rend_quete":true,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"L'oasis perdue n'est que trois palmiers morts. Vous dispersez les cendres de Belkhir au pied du plus grand."},{"qui":"narrateur","expression":"neutre","dit":"Le lendemain, vous ne l'avez pas rêvé : une pousse verte est sortie du sable. Les dunes, au loin, ne chantent plus."},{"qui":"ouzram","expression":"neutre","dit":"De retour au Bazar, Maître Ouzram écoute toute l'histoire sans un mot. Puis il vous tend une lame qu'il gardait sous son comptoir. « Elle était à mon frère. Elle sera mieux dans vos mains que dans les miennes. »"}],"effets":[{"xp":300,"objet":"crocs-jumeaux-du-canyon","terminer_quete":"q-caravane-fantome"}],"choix":[],"fin":true}}},"sq-pillards-prisonnier":{"id":"sq-pillards-prisonnier","titre":"Le repaire des pillards : le prisonnier","type":"groupe","lieu":"qarzim-porte","decor":"qarzim-porte","debut":"debut","disponible_si":{"flag":"prisonnier-pillard","pas_flag":"pillards-commences"},"repetable":false,"romance":false,"quete":"q-pillards","pnj":"nadja","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le jeune pillard de la Route des Caravanes a été retrouvé à la Porte, mendiant de l'eau.","si":{"flag":"pillard-epargne"}},{"qui":"narrateur","expression":"neutre","dit":"Le jeune pillard de la Route des Caravanes croupit dans la geôle de la Porte.","si":{"pas_flag":"pillard-epargne"}},{"qui":"nadja","expression":"neutre","dit":"Nadja s'accroupit devant lui. « Qui vous a payés pour retarder la princesse ? »"}],"effets":[],"choix":[{"texte":"Le convaincre gentiment. (Charisme, difficulté 19)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":19,"reussite":"parle","echec":"menace"},"effets":[]},{"texte":"Le menacer.","visible_si_bloque":false,"effets":[],"aller":"menace"}],"fin":false},"parle":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le garçon fond en larmes. « Un homme en soie est venu au repaire. Avec une bague violette. Il a payé en cristaux. » Il vous dit où trouver le repaire : entre deux rochers en forme de crocs, à l'est."}],"effets":[{"flag":"pillards-commences","affinite":{"nadja":2},"quete":{"id":"q-pillards","etape":"repaire"}}],"choix":[],"fin":true},"menace":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le garçon se recroqueville et parle, terrorisé. Le repaire est à l'est, entre deux rochers en forme de crocs."}],"effets":[{"flag":"pillards-commences","quete":{"id":"q-pillards","etape":"repaire"}}],"choix":[],"fin":true}}},"sq-pillards-repaire":{"id":"sq-pillards-repaire","titre":"Le repaire des pillards : l'assaut","type":"groupe","lieu":"repaire-pillards","decor":"repaire-pillards","debut":"debut","disponible_si":{"quete_etape":{"q-pillards":"repaire"}},"repetable":false,"romance":false,"quete":"q-pillards","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Des tentes rapiécées, un feu, des chameaux volés. Et des pillards qui vous attendaient."}],"effets":[],"choix":[],"combat":{"rencontre":"pillards-camp","victoire":"fouille","defaite":"fouille"},"fin":false},"fouille":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Dans la tente du chef, un coffret plein de cristaux d'éther… et un reçu, signé d'un « H. » orné d'une bague."}],"effets":[{"or":80,"objet":"cristal-ether","quete":{"id":"q-pillards","etape":"retour"}}],"choix":[],"fin":true}}},"sq-pillards-retour":{"id":"sq-pillards-retour","titre":"Le repaire des pillards : la preuve","type":"groupe","lieu":"qarzim-porte","decor":"qarzim-porte","debut":"debut","disponible_si":{"quete_etape":{"q-pillards":"retour"}},"repetable":false,"romance":false,"quete":"q-pillards","pnj":"nadja","rend_quete":true,"noeuds":{"debut":{"repliques":[{"qui":"nadja","expression":"neutre","dit":"Nadja regarde le reçu longtemps. « Un « H. ». Ça ne prouve rien… et ça dit tout. » Elle le glisse dans son carnet. « Quelqu'un, très haut à la Concorde, ne voulait pas de ce traité. »"}],"effets":[{"flag":"recu-hassad","affinite":{"nadja":4},"xp":240,"terminer_quete":"q-pillards"}],"choix":[],"fin":true}}},"el-priere":{"id":"el-priere","titre":"Elianne — La prière du soir","type":"individuel","lieu":"ithrael-auberge","decor":"ithrael-auberge","debut":"debut","disponible_si":{"flag":"elianne-recrutee"},"repetable":false,"romance":false,"pnj":"elianne","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"elianne","expression":"neutre","dit":"Elianne est agenouillée sur la plateforme de l'auberge, face au soleil couchant, les mains jointes. Elle ne prie pas. Elle regarde ses mains."},{"qui":"elianne","expression":"neutre","dit":"« Avant, les mots venaient tout seuls. Maintenant… » Elle vous fait de la place à côté d'elle. « Tu pries, toi ? Dans ton monde, je veux dire. »"}],"effets":[],"choix":[{"texte":"S'agenouiller à côté d'elle, en silence.","visible_si_bloque":false,"effets":[{"affinite":{"elianne":6}}],"aller":"silence"},{"texte":"« Pas vraiment. Mais je sais écouter. »","visible_si_bloque":false,"effets":[{"affinite":{"elianne":5}}],"aller":"ecoute"},{"texte":"« Prier ne sert à rien. Agir, si. »","visible_si_bloque":false,"effets":[{"affinite":{"elianne":-1}}],"aller":"agir"}],"fin":false},"silence":{"repliques":[{"qui":"elianne","expression":"joie","dit":"Le soleil disparaît. Au bout d'un long moment, elle murmure : « Merci. C'est la première fois depuis des semaines que ce silence ne me fait pas peur. »"}],"effets":[],"choix":[],"fin":true},"ecoute":{"repliques":[{"qui":"elianne","expression":"neutre","dit":"Elle parle longtemps : de l'orphelinat, des chants du Temple, du jour de l'Appel. « J'étais si fière, ce jour-là. » Elle se tait. « Je ne sais plus si je dois l'être. »"}],"effets":[],"choix":[],"fin":true},"agir":{"repliques":[{"qui":"elianne","expression":"neutre","dit":"« Peut-être. » Elle se relève, épousseta sa robe. « Mais il faut savoir pourquoi on agit. C'est à ça que servent les prières. » Elle s'en va, sans colère."}],"effets":[],"choix":[],"fin":true}}},"el-lettres":{"id":"el-lettres","titre":"Elianne — Le tribut du Voile","type":"individuel","lieu":"ithrael-auberge","decor":"ithrael-auberge","debut":"debut","disponible_si":{"flag":"elianne-recrutee","affinite_palier":{"elianne":"proche"}},"repetable":false,"romance":false,"quete":"q-elianne","pnj":"elianne","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"elianne","expression":"neutre","dit":"Elianne sort de son sac un paquet de lettres jaunies, attachées par un ruban gris. « Je les ai trouvées dans les archives du Temple, l'an dernier. Des lettres de Grands Prieurs, sur quatre siècles. »"},{"qui":"elianne","expression":"tristesse","dit":"« Elles parlent toutes du « tribut du Voile ». Chaque Appel a un prix. Personne n'écrit lequel. Mais l'une d'elles dit : « Le Souverain grandit à chaque fois que nous appelons. Qu'importe : nos héros grandissent plus vite. » »"}],"effets":[],"choix":[{"texte":"« Ça veut dire que notre venue a renforcé les Cendres ? »","visible_si_bloque":false,"effets":[],"aller":"prix"},{"texte":"Lui prendre la main. « Ce n'est pas ta faute, Elianne. »","visible_si_bloque":false,"effets":[{"affinite":{"elianne":4}}],"aller":"prix"}],"fin":false},"prix":{"repliques":[{"qui":"elianne","expression":"neutre","dit":"« Je crois, oui. » Elle range les lettres. « Les Grands Prieurs le savaient. Auréliath le sait. Et il a quand même appelé. » Ses mains tremblent. « Il faut une preuve. Une preuve que personne ne pourra brûler. »"},{"qui":"elianne","expression":"neutre","dit":"« On dit que les nains de Grisfer gardent les registres de tous les Appels, gravés dans la pierre des Mille Marches. Les nains ne détruisent jamais rien. » Elle relève la tête. « Tu viendras ? »"}],"effets":[{"flag":"tribut-du-voile","affinite":{"elianne":8},"xp":200,"quete":{"id":"q-elianne","etape":"revelation"}}],"choix":[],"fin":true}}},"el-chapelle":{"id":"el-chapelle","titre":"Elianne — La chapelle des racines","type":"individuel","lieu":"ithrael-auberge","decor":"ithrael-auberge","debut":"debut","disponible_si":{"flag":"elianne-recrutee","affinite_palier":{"elianne":"amoureuse"}},"repetable":false,"romance":true,"pnj":"elianne","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"elianne","expression":"gene","dit":"Elianne vous a emmené(e) dans une petite chapelle de racines, oubliée des elfes. Une seule bougie. « On m'a appris que l'amour ne devait aller qu'à la Lumière. » Elle rit doucement. « On m'a appris beaucoup de choses fausses. »"}],"effets":[],"choix":[{"texte":"« Alors apprenons-en une vraie, ensemble. »","visible_si_bloque":false,"effets":[{"affinite":{"elianne":6}}],"aller":"oui"}],"fin":false},"oui":{"repliques":[{"qui":"elianne","expression":"joie","dit":"Elle souffle la bougie. Dans le noir, il n'y a plus que sa main dans la vôtre, et son rire, enfin libre…"},{"qui":"narrateur","expression":"neutre","dit":"(Fondu au noir.)"}],"effets":[],"choix":[],"fin":true}}},"il-etoiles":{"id":"il-etoiles","titre":"Ilyssë — Les étoiles de l'autre monde","type":"individuel","lieu":"ithrael-racines","decor":"ithrael-racines","debut":"debut","disponible_si":{"flag":"ilysse-recrutee"},"repetable":false,"romance":false,"pnj":"ilysse","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"ilysse","expression":"neutre","dit":"Ilyssë vous attend avec un carnet, une plume, et l'air d'un chat devant une souris. « Assieds-toi. Les étoiles de ton monde. Combien ? Quelles couleurs ? Est-ce qu'elles bougent ? Est-ce que vous avez des dragons ? Non ? Quel dommage. »"}],"effets":[],"choix":[{"texte":"Répondre patiemment à toutes ses questions.","visible_si_bloque":false,"effets":[{"affinite":{"ilysse":6}}],"aller":"patient"},{"texte":"« Et toi ? Pose-moi une question qui ne soit pas une étude. »","visible_si_bloque":false,"effets":[{"affinite":{"ilysse":7}}],"aller":"personnel"}],"fin":false},"patient":{"repliques":[{"qui":"ilysse","expression":"joie","dit":"Elle note trois pages, fébrile. « Des lunes artificielles ? Des voitures sans chevaux ? Tu inventes. » Elle sourit. « Continue d'inventer. »"}],"effets":[],"choix":[],"fin":true},"personnel":{"repliques":[{"qui":"ilysse","expression":"surprise","dit":"Elle pose sa plume. Long silence. « …Est-ce que tu as peur de mourir ici ? Loin de chez toi ? » Elle détourne les yeux. « Moi, j'ai peur de vivre encore cinq cents ans sans avoir compris. »"}],"effets":[],"choix":[],"fin":true}}},"il-notes":{"id":"il-notes","titre":"Ilyssë — Les notes confisquées","type":"individuel","lieu":"ithrael-cour","decor":"ithrael-cour","debut":"debut","disponible_si":{"flag":"ilysse-recrutee","affinite_palier":{"ilysse":"proche"}},"repetable":false,"romance":false,"quete":"q-ilysse","pnj":"ilysse","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"ilysse","expression":"neutre","dit":"« Cinquante ans de travail. » Ilyssë désigne un coffre scellé derrière le trône vide de la Reine. « Confisqués le jour de mon bannissement. La Reine m'a pardonné. Elle ne m'a pas rendu mes notes. »"}],"effets":[],"choix":[{"texte":"Demander les notes à la Reine. (Charisme, difficulté 24)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":24,"reussite":"rendues","echec":"vol"},"effets":[]},{"texte":"Ouvrir le coffre, discrètement. (Agilité, difficulté 23)","visible_si_bloque":false,"test":{"carac":"AGI","difficulte":23,"reussite":"vol-reussi","echec":"vol"},"effets":[]}],"fin":false},"rendues":{"repliques":[{"qui":"reine-seve","expression":"neutre","dit":"La Reine écoute, puis ouvre le coffre elle-même. « Les vérités qu'on enferme pourrissent. Tiens, Ilyssë. »"}],"effets":[],"choix":[],"suite":"notes","fin":false},"vol-reussi":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le coffre s'ouvre sans un bruit. Ilyssë serre ses carnets contre elle comme un enfant."}],"effets":[],"choix":[],"suite":"notes","fin":false},"vol":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Un garde vous surprend… et détourne les yeux. Le capitaine Vaelor, de loin, hausse les épaules. Les carnets sont à vous."}],"effets":[],"choix":[],"suite":"notes","fin":false},"notes":{"repliques":[{"qui":"ilysse","expression":"neutre","dit":"Ilyssë feuillette, fébrile, et s'arrête sur un schéma : un cercle, déchiré, et des fils qui le recousent. « Mon idée d'il y a cinquante ans. Recoudre le Voile depuis l'endroit où il est le plus fin. » Elle vous regarde. « Avec quelqu'un qui vient de l'autre côté. »"},{"qui":"ilysse","expression":"gene","dit":"« Tu… tu crois que ce serait possible ? Avec toi ? » Elle referme le carnet, gênée de son propre espoir."}],"effets":[{"flag":"plan-recoudre","affinite":{"ilysse":10},"xp":200,"quete":{"id":"q-ilysse","etape":"voile"}}],"choix":[],"fin":true}}},"il-branches":{"id":"il-branches","titre":"Ilyssë — Sur la plus haute branche","type":"individuel","lieu":"ithrael-racines","decor":"ithrael-racines","debut":"debut","disponible_si":{"flag":"ilysse-recrutee","affinite_palier":{"ilysse":"amoureuse"}},"repetable":false,"romance":true,"pnj":"ilysse","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"ilysse","expression":"gene","dit":"Sur la plus haute branche d'Ithrael, le ciel est immense. Ilyssë ne regarde pas les étoiles : elle vous regarde. « J'ai étudié des milliers de choses. Jamais celle-là. » Elle soupire. « C'est très mal documenté, l'amour. »"}],"effets":[],"choix":[{"texte":"« Alors étudions-le. Lentement. »","visible_si_bloque":false,"effets":[{"affinite":{"ilysse":6}}],"aller":"oui"}],"fin":false},"oui":{"repliques":[{"qui":"ilysse","expression":"joie","dit":"Elle éclate de rire — un vrai rire, qui fait s'envoler une chouette. Puis elle pose la tête contre votre épaule, et pour une fois, elle ne pose plus aucune question…"},{"qui":"narrateur","expression":"neutre","dit":"(Fondu au noir.)"}],"effets":[],"choix":[],"fin":true}}},"ky-rang-a":{"id":"ky-rang-a","titre":"Kaya — Le rang A","type":"individuel","lieu":"ithrael-auberge","decor":"ithrael-auberge","debut":"debut","disponible_si":{"flag":"sylvenoire-ouverte","affinite_min":{"kaya":30}},"repetable":false,"romance":false,"pnj":"kaya","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"kaya","expression":"joie","dit":"Kaya débarque dans votre hamac en brandissant une carte de cuivre. « RANG A ! Rowena m'a écrit ! Rang A ! » Elle vous secoue comme un prunier. « Encore un rang, et je rentre chez moi la tête haute ! »"}],"effets":[],"choix":[{"texte":"La féliciter et fêter ça. Brochettes à volonté.","visible_si_bloque":false,"effets":[{"affinite":{"kaya":6}}],"aller":"fete"},{"texte":"« Et après le rang S, tu feras quoi ? »","visible_si_bloque":false,"effets":[{"affinite":{"kaya":4}}],"aller":"apres"}],"fin":false},"fete":{"repliques":[{"qui":"kaya","expression":"neutre","dit":"Les elfes n'ont jamais vu personne manger autant. Thaliel, effaré, compte les brochettes sur ses doigts. Kaya hurle à la lune depuis la plus haute branche. Personne ne dort."}],"effets":[],"choix":[],"fin":true},"apres":{"repliques":[{"qui":"kaya","expression":"neutre","dit":"Elle s'arrête, surprise. « Après ? » Elle réfléchit, les oreilles en arrière. « Je n'y avais jamais pensé. » Elle vous regarde. « Peut-être que je resterai avec toi. Si tu veux. »"}],"effets":[],"choix":[],"fin":true}}},"nd-comptes-sylve":{"id":"nd-comptes-sylve","titre":"Nadja — Les comptes des elfes","type":"individuel","lieu":"ithrael-marche","decor":"ithrael-marche","debut":"debut","disponible_si":{"flag":"sylvenoire-ouverte","affinite_min":{"nadja":25}},"repetable":false,"romance":false,"pnj":"nadja","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"nadja","expression":"neutre","dit":"Nadja est désespérée. « Ils n'ont pas de monnaie. Ils échangent. Une graine contre une chanson. Un arc contre « un souvenir agréable ». » Elle se tient la tête. « Comment on fait des affaires avec des gens qui n'ont pas de prix ? »"}],"effets":[],"choix":[{"texte":"« Tu échanges un souvenir. Raconte-leur Qarzim. »","visible_si_bloque":false,"effets":[{"affinite":{"nadja":6}}],"aller":"souvenir"},{"texte":"« Tu respires et tu profites. Pour une fois. »","visible_si_bloque":false,"effets":[{"affinite":{"nadja":4}}],"aller":"respire"}],"fin":false},"souvenir":{"repliques":[{"qui":"nadja","expression":"joie","dit":"Elle raconte le Bazar, les épices, la poussière. Les elfes écoutent, fascinés. Elle repart avec trois arcs, un manteau et l'air ahuri de quelqu'un qui vient de faire la meilleure affaire de sa vie sans dépenser une pièce."}],"effets":[],"choix":[],"fin":true},"respire":{"repliques":[{"qui":"nadja","expression":"neutre","dit":"Elle s'assoit sur une branche, les jambes dans le vide. Au bout d'une heure, elle dit : « C'est la première fois depuis mes seize ans que je ne compte rien. » Elle sourit. « C'est terrifiant. »"}],"effets":[],"choix":[],"fin":true}}},"sr-lettre-mur":{"id":"sr-lettre-mur","titre":"Séraphine — Une lettre du Mur d'Aube","type":"individuel","lieu":"ithrael-marche","decor":"ithrael-marche","debut":"debut","disponible_si":{"flag":"sylvenoire-ouverte","quete_etape":{"q-seraphine":"rumeurs"}},"repetable":false,"romance":false,"pnj":"seraphine","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"seraphine","expression":"neutre","dit":"Séraphine a reçu une lettre d'un officier du Mur d'Aube. Elle la lit pour la dixième fois. « Une patrouille a vu un homme en armure noire, sur les remparts de Valgrane en ruine. Il portait une cape bleue. La cape des princes d'Aubeclaire. »"}],"effets":[],"choix":[{"texte":"« On ira voir. Dès qu'on pourra. Je te le promets. »","visible_si_bloque":false,"effets":[{"flag":"heros:promesse-seraphine","affinite":{"seraphine":6}}],"aller":"fin"},{"texte":"« Une cape, ça se vole. Prépare-toi au pire. »","visible_si_bloque":false,"effets":[{"affinite":{"seraphine":2}}],"aller":"fin"}],"fin":false},"fin":{"repliques":[{"qui":"seraphine","expression":"neutre","dit":"« Une armure noire… » Elle replie la lettre. « S'il est vivant, pourquoi ne revient-il pas ? » Personne ne répond."}],"effets":[],"choix":[],"fin":true}}},"av-domaine":{"id":"av-domaine","titre":"Aveline — Le manoir","type":"individuel","lieu":"domaine-lisiere","decor":"domaine-lisiere","debut":"debut","disponible_si":{"flag":"domaine-obtenu","affinite_min":{"aveline":25}},"repetable":false,"romance":false,"pnj":"aveline","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Aveline a passé la journée à apprendre à vos miliciens à tenir une lance. Elle a de la paille dans les cheveux et l'air heureux. « Castelroc, le domaine de mon père, ressemblait à ça. Avant. »"}],"effets":[],"choix":[{"texte":"« Alors aide-moi à en faire un endroit dont ton père aurait été fier. »","visible_si_bloque":false,"effets":[{"reputation":{"troupes":3},"affinite":{"aveline":6}}],"aller":"fin"},{"texte":"« Tu pourrais rester ici. Être la capitaine de ma garde. »","visible_si_bloque":false,"effets":[{"affinite":{"aveline":5}}],"aller":"capitaine"}],"fin":false},"capitaine":{"repliques":[{"qui":"aveline","expression":"gene","dit":"Elle rougit jusqu'aux oreilles. « Je sers la Couronne. » Un temps. « …Mais la Couronne ne m'a jamais offert un manoir avec des pommiers. » Elle détourne la tête pour cacher son sourire."}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Le soir, elle reste assise sur les marches du manoir à regarder vos gens rentrer des champs. « Je comprends pourquoi on se bat, maintenant. Pas pour un roi. Pour ça. »"}],"effets":[],"choix":[],"fin":true}}},"ch3-domaines":{"id":"ch3-domaines","titre":"Les domaines","type":"groupe","lieu":"chateau","decor":"chateau-trone","debut":"debut","disponible_si":{"flag":"chapitre-2-fini","pas_flag":"ch3-depart-fait","date_min":{"annee":1018,"mois":1,"jour":1}},"repetable":false,"romance":false,"quete":"q-ch3-foret","pnj":"edmund-iv","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Germinal 1018. Six ans depuis l'Appel. À Lysmont, on vous salue dans la rue ; certains enfants jouent aux Appelés avec des épées de bois."},{"qui":"edmund-iv","expression":"neutre","dit":"Le roi Edmund vous reçoit debout, ce qui ne lui arrive jamais. « Qarzim. Le traité. Ma fille vivante. » Il hoche la tête. « La Couronne paie ses dettes. »","si":{"flag":"serment-couronne"}},{"qui":"edmund-iv","expression":"neutre","dit":"« Chevaliers d'Aubeclaire : je vous donne des terres à la lisière de Sylvenoire. Un manoir, des fermes, des gens. Gardez-les bien : la frontière est fragile. »","si":{"flag":"serment-couronne"}},{"qui":"rowena","expression":"neutre","dit":"C'est Dame Rowena qui vous attend dans la salle du trône, un rouleau de parchemin à la main. « Le roi n'aime pas les héros libres. Mais il aime encore moins devoir quelque chose à la Guilde. »","si":{"pas_flag":"serment-couronne"}},{"qui":"rowena","expression":"neutre","dit":"« Alors la Guilde vous offre des terres qu'elle a reçues en paiement il y a cent ans, à la lisière de Sylvenoire. Un manoir en ruine. Des fermes. Des gens qui ont besoin d'être protégés. Considérez ça comme une prime. »","si":{"pas_flag":"serment-couronne"}},{"qui":"elianne","expression":"neutre","dit":"Sœur Elianne s'avance, un voyage dans les yeux et un sac sur l'épaule. « L'Ordre m'envoie avec vous. Officiellement, pour lire la tablette des Ruines avec les elfes. »"},{"qui":"elianne","expression":"tristesse","dit":"Plus bas, quand le roi s'éloigne : « Officieusement… j'ai trouvé des choses, dans les archives du Temple. Des choses qui m'empêchent de dormir. J'ai besoin de savoir. »"}],"effets":[],"choix":[{"texte":"« Bienvenue, Sœur Elianne. Nous chercherons la vérité ensemble. »","visible_si_bloque":false,"effets":[{"affinite":{"elianne":5}}],"aller":"domaine"},{"texte":"« L'Ordre nous espionne, maintenant ? »","visible_si_bloque":false,"effets":[{"reputation":{"ordre":-3},"affinite":{"elianne":-2}}],"aller":"soupcon"}],"fin":false},"soupcon":{"repliques":[{"qui":"elianne","expression":"neutre","dit":"Elle ne s'offense pas. « L'Ordre croit que je l'espionne pour lui. Moi, je crois que je l'espionne pour vous. » Un sourire triste. « Nous verrons bien qui a raison. »"}],"effets":[],"choix":[],"suite":"domaine","fin":false},"domaine":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le sceau de vos terres est de cire verte, frappé d'une feuille et d'une épée. Sur la carte, votre domaine touche la lisière de Sylvenoire : la forêt des elfes, où personne n'entre sans invitation."},{"qui":"seraphine","expression":"neutre","dit":"Séraphine pose un doigt sur la carte. « La tablette des Ruines, la fresque… tout mène à Sylvenoire. Et votre domaine en est la porte. » Elle sourit. « Le hasard fait bien les choses. Ou mon père. »","si":{"flag":"seraphine-recrutee"}}],"effets":[{"flag":["ch3-depart-fait","domaine-obtenu","elianne-recrutee"],"reputation":{"troupes":10},"objet":"sceau-du-domaine","quete":{"id":"q-ch3-foret","etape":"lisiere"},"recruter":"elianne","journal":"Germinal 1018 : {groupe} reçoivent un domaine à la lisière de Sylvenoire. Sœur Elianne les accompagne."}],"choix":[],"fin":true}}},"ch3-lisiere":{"id":"ch3-lisiere","titre":"La lisière de Sylvenoire","type":"groupe","lieu":"lisiere-sylvenoire","decor":"lisiere-sylvenoire","debut":"debut","disponible_si":{"quete_etape":{"q-ch3-foret":"lisiere"}},"repetable":false,"romance":false,"quete":"q-ch3-foret","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les champs s'arrêtent net, comme coupés au couteau. Au-delà, des troncs larges comme des tours, une brume bleue, et un silence qui écoute."},{"qui":"vaelor","expression":"neutre","dit":"Une flèche se plante à vos pieds. Puis dix archers apparaissent dans les branches, comme sortis de l'écorce. « Humains. Faites demi-tour. Sylvenoire n'est pas à vous. »"}],"effets":[],"choix":[{"texte":"Montrer la tablette (ou la copie de la fresque) des Ruines de Sel.","visible_si_bloque":false,"effets":[],"aller":"tablette"},{"texte":"« Nous sommes les voisins : notre domaine touche votre forêt. » (Charisme, difficulté 23)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":23,"reussite":"voisins","echec":"loups"},"effets":[]},{"texte":"Attendre sans bouger, les mains ouvertes.","visible_si_bloque":false,"effets":[],"aller":"loups"}],"fin":false},"tablette":{"repliques":[{"qui":"vaelor","expression":"neutre","dit":"Le capitaine descend d'une branche, lentement. Il regarde l'écriture elfique et pâlit. « Où avez-vous trouvé ça ? Ces mots… ce sont ceux des Anciens. »"}],"effets":[{"reputation":{"elfes":5}}],"choix":[],"suite":"loups","fin":false},"voisins":{"repliques":[{"qui":"vaelor","expression":"neutre","dit":"« Les voisins. » L'elfe pèse le mot. « Il y a cent ans, le seigneur de vos terres brûlait nos arbres pour se chauffer. » Il baisse son arc. « Prouvez que vous êtes différents. »"}],"effets":[{"reputation":{"elfes":8}}],"choix":[],"suite":"loups","fin":false},"loups":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La brume s'épaissit d'un coup. Les archers se figent. Des yeux blancs s'allument entre les troncs : des loups translucides, qui ne font aucun bruit en marchant."},{"qui":"vaelor","expression":"neutre","dit":"« Les loups de brume ! Ils ne sortent jamais à la lisière… » Il n'a pas le temps de finir."}],"effets":[],"choix":[],"combat":{"rencontre":"lisiere-loups","victoire":"ilysse","defaite":"ilysse-sauve"},"fin":false},"ilysse-sauve":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les loups vous renversent. Puis une lumière violette explose au milieu de la meute, et les loups se dissipent comme de la fumée."}],"effets":[],"choix":[],"suite":"ilysse","fin":false},"ilysse":{"repliques":[{"qui":"ilysse","expression":"neutre","dit":"Une elfe en robe de voyage couverte de taches d'encre sort de la brume, un livre ouvert dans une main, une baguette dans l'autre. « Les loups de brume gardent la forêt contre ce qui ne vient pas de ce monde. Ils vous ont pris pour des intrus. » Elle vous détaille. « Ils n'avaient pas tout à fait tort. »"},{"qui":"vaelor","expression":"colere","dit":"« Ilyssë Vaëlnor. Tu es bannie. Tu n'as rien à faire ici. »"},{"qui":"ilysse","expression":"neutre","dit":"« Je suis à la lisière, Vaelor. La lisière, c'est encore à personne. » Elle se tourne vers vous, les yeux brillants. « Des Appelés. Des vrais. Avec une tablette des Anciens. J'ai attendu ce jour pendant cinquante ans. »"}],"effets":[],"choix":[{"texte":"« Vous pouvez la lire ? Venez avec nous. »","visible_si_bloque":false,"effets":[{"affinite":{"ilysse":6}}],"aller":"accord"},{"texte":"« Pourquoi vous a-t-on bannie ? »","visible_si_bloque":false,"effets":[{"affinite":{"ilysse":3}}],"aller":"bannie"}],"fin":false},"bannie":{"repliques":[{"qui":"ilysse","expression":"neutre","dit":"« Pour avoir posé la seule question qui compte : pourquoi le ciel s'est-il déchiré ? » Elle referme son livre d'un coup sec. « La Reine préfère l'oubli. Moi, je préfère savoir. »"}],"effets":[],"choix":[],"suite":"accord","fin":false},"accord":{"repliques":[{"qui":"vaelor","expression":"neutre","dit":"Le capitaine soupire longuement. « La Reine voudra voir la tablette. Et vous. » Il désigne Ilyssë du menton. « Elle, elle reste dehors. »"},{"qui":"ilysse","expression":"neutre","dit":"« Bien sûr. » Ilyssë sourit d'un air qui promet exactement le contraire."}],"effets":[{"flag":["sylvenoire-ouverte","ilysse-recrutee"],"xp":300,"quete":{"id":"q-ch3-foret","etape":"reine"},"recruter":"ilysse","journal":"{groupe} entrent en Sylvenoire. Ilyssë Vaëlnor, mage elfe bannie, se joint à eux."}],"choix":[],"fin":true}}},"ch3-reine":{"id":"ch3-reine","titre":"La Reine-Sève","type":"groupe","lieu":"ithrael-cour","decor":"ithrael-cour","debut":"debut","disponible_si":{"quete_etape":{"q-ch3-foret":"reine"},"date_min":{"annee":1019,"mois":2,"jour":1}},"repetable":false,"romance":false,"quete":"q-ch3-foret","pnj":"reine-seve","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Floréal 1019. Il a fallu près d'un an pour que la Reine accepte de vous recevoir. Les elfes ne sont jamais pressés."},{"qui":"narrateur","expression":"neutre","dit":"La Cour est une salle vivante : des branches tressées pour murs, de la mousse pour tapis, et au fond, une femme si immobile qu'on la prendrait pour une statue."},{"qui":"reine-seve","expression":"neutre","dit":"« Des Appelés. Dans ma Cour. » Sa voix est douce comme le vent dans les feuilles. « La dernière fois que j'ai vu un Appelé, il s'appelait Orvan, et il était venu me demander pardon pour ce que l'Ordre allait faire. C'était il y a six cents ans. »"},{"qui":"ilysse","expression":"neutre","dit":"Ilyssë, qui n'était évidemment pas restée dehors, s'étrangle derrière un pilier.","si":{"flag":"ilysse-recrutee"}}],"effets":[],"choix":[],"suite":"question","fin":false},"question":{"parole_a":{"regle":{"race":["elfe","demi-elfe"]},"question":{"qui":"reine-seve","expression":"neutre","dit":"La Reine tourne ses yeux couleur de mousse vers {nom}. « Toi, {pseudo}. Tu as du sang de la forêt. Dis-moi : faut-il réveiller ce qui dort ? »"},"reponses":[{"texte":"« Je suis elfe, ma Reine. Et je sais que l'oubli n'a jamais guéri personne. »","si":{"race":"elfe"},"effets":[{"reputation":{"elfes":10}}],"aller":"reponse"},{"texte":"« À moitié elfe, à moitié humaine. Je sais ce que c'est, de vivre entre deux mondes qui se taisent. »","si":{"race":"demi-elfe"},"effets":[{"reputation":{"elfes":8},"affinite":{"ilysse":3}}],"aller":"reponse"},{"texte":"« Ce qui dort est en train de se réveiller tout seul, au nord. Mieux vaut savoir pourquoi. »","effets":[{"reputation":{"elfes":6}}],"aller":"reponse"},{"texte":"« Nous ne voulons pas réveiller. Nous voulons comprendre. »","effets":[{"reputation":{"elfes":4}}],"aller":"reponse"},{"texte":"« Avec tout le respect que je vous dois… on n'a pas le temps de dormir. »","effets":[{"affinite":{"ilysse":4}}],"aller":"reponse"}]},"repliques":[],"effets":[],"choix":[],"fin":false},"reponse":{"repliques":[{"qui":"reine-seve","expression":"neutre","dit":"Un long silence. Les branches des murs bougent, comme si la salle respirait."},{"qui":"reine-seve","expression":"neutre","dit":"« Il y a mille ans, les dragons-rois régnaient. Mon peuple a voulu les vaincre. Nous avons ouvert le Voile pour y puiser une force qui n'était pas la nôtre. Le ciel s'est déchiré. Les dragons sont tombés… et le nord est devenu cendres. »"},{"qui":"reine-seve","expression":"neutre","dit":"« Tout le reste est écrit dans la Bibliothèque des Racines. Fermée depuis mille ans. » Elle vous fixe. « Pourquoi devrais-je vous l'ouvrir ? »"}],"effets":[],"choix":[{"texte":"« Parce que la Légion arrive, et que vous ne la vaincrez pas en fermant les yeux. » (Charisme, difficulté 24)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":24,"reussite":"ouverte","echec":"condition"},"effets":[]},{"texte":"« Parce qu'Ilyssë a raison depuis cinquante ans. »","si":{"flag":"ilysse-recrutee"},"visible_si_bloque":false,"effets":[{"reputation":{"elfes":-5},"affinite":{"ilysse":8}}],"aller":"condition"},{"texte":"« Nous protégerons la forêt en échange. Notre domaine sera votre rempart. »","visible_si_bloque":false,"effets":[{"flag":"pacte-lisiere","reputation":{"elfes":10,"troupes":5}}],"aller":"ouverte"}],"fin":false},"condition":{"repliques":[{"qui":"reine-seve","expression":"neutre","dit":"« Alors prouvez-le. » La Reine se lève, et ses cheveux-racines glissent sur le sol. « La Bibliothèque s'ouvre à l'été prochain, quand la sève monte. Si son Gardien vous laisse passer, c'est que la forêt vous accepte. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"ouverte":{"repliques":[{"qui":"reine-seve","expression":"neutre","dit":"Pour la première fois, quelque chose qui ressemble à un sourire. « Soit. La Bibliothèque s'ouvre à l'été prochain, quand la sève monte. Son Gardien décidera du reste. »"},{"qui":"reine-seve","expression":"neutre","dit":"Elle se tourne vers le pilier. « Et toi, Ilyssë Vaëlnor, tu peux sortir de derrière ce pilier. Tu les accompagneras. Ta peine est… suspendue. »","si":{"flag":"ilysse-recrutee"}}],"effets":[{"reputation":{"elfes":5},"affinite":{"ilysse":5}}],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"elianne","expression":"neutre","dit":"En sortant, Elianne vous retient par la manche. « Elle a dit qu'Orvan était venu lui demander pardon pour ce que l'Ordre « allait faire ». Pas ce qu'il avait fait. Ce que l'Ordre allait faire. » Elle est pâle. « Le Premier Appelé… savait. »"}],"effets":[{"flag":"orvan-nomme","quete":{"id":"q-ch3-foret","etape":"bibliotheque"},"journal":"Floréal 1019 : la Reine-Sève raconte la Déchirure et accepte d'ouvrir la Bibliothèque des Racines."}],"choix":[],"fin":true}}},"ch3-bibliotheque":{"id":"ch3-bibliotheque","titre":"La Bibliothèque des Racines","type":"groupe","lieu":"bibliotheque-racines","decor":"bibliotheque-racines","debut":"debut","disponible_si":{"quete_etape":{"q-ch3-foret":"bibliotheque"},"date_min":{"annee":1020,"mois":4,"jour":1}},"repetable":false,"romance":false,"quete":"q-ch3-foret","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Solaire 1020. La sève monte. Sous le plus vieil arbre du monde, une porte de racines s'ouvre pour la première fois depuis mille ans."},{"qui":"ilysse","expression":"joie","dit":"Ilyssë a les mains qui tremblent. « Mille ans de savoir. Ne touchez à rien. Ne respirez pas trop fort. Et si vous devez vous battre… faites-le loin des étagères. »","si":{"flag":"ilysse-recrutee"}}],"effets":[],"choix":[{"texte":"Descendre dans la Bibliothèque.","visible_si_bloque":false,"effets":[],"aller":"donjon"}],"fin":false},"donjon":{"repliques":[],"effets":[],"choix":[],"donjon":{"id":"bibliotheque-racines","sortie":"sortie","abandon":"abandon"},"fin":false},"abandon":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le Gardien vous repousse une dernière fois vers l'escalier. Mais dans votre fuite, Ilyssë a eu le temps de recopier une page entière d'un livre tombé à terre."}],"effets":[],"choix":[],"suite":"revelation","fin":false},"sortie":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le Gardien des Racines s'est rendormi. Au fond de la salle, sur un pupitre de bois vivant, un livre énorme : le Codex de la Déchirure."}],"effets":[],"choix":[],"suite":"revelation","fin":false},"revelation":{"repliques":[{"qui":"ilysse","expression":"neutre","dit":"Ilyssë lit à voix haute, et sa voix se brise par moments. « « Nous avons ouvert le Voile pour vaincre les dragons. Le Voile n'est pas une porte : c'est une peau. Chaque passage la déchire un peu. Chaque déchirure laisse passer des Cendres. » »"},{"qui":"ilysse","expression":"neutre","dit":"« « En l'an 430, des prêtres humains sont venus copier nos rituels. Nous les avons chassés. Trop tard. » » Elle lève les yeux. « L'Ordre. L'Appel vient de nous. C'est notre rituel, recopié par des voleurs. »"},{"qui":"elianne","expression":"tristesse","dit":"Elianne s'assoit sur une marche, sans un mot. Elle serre son chapelet si fort que les perles craquent."},{"qui":"ilysse","expression":"neutre","dit":"« Il y a une dernière phrase, à moitié effacée. « Seul celui qui vient de l'autre côté peut recoudre ce qui a été déchiré. » » Elle vous regarde, tous, longuement. « Celui qui vient de l'autre côté. Vous. »"}],"effets":[{"flag":"codex-lu","xp":400,"quete":{"id":"q-ch3-foret","etape":"nuitlongue"},"journal":"Solaire 1020 : dans la Bibliothèque des Racines, {groupe} apprennent que l'Appel est un rituel elfe volé par l'Ordre, et que chaque passage déchire le Voile."}],"choix":[],"fin":true}}},"ch3-nuitlongue":{"id":"ch3-nuitlongue","titre":"La Nuitlongue","type":"groupe","lieu":"clairiere-dechirure","decor":"clairiere-dechirure","debut":"debut","disponible_si":{"quete_etape":{"q-ch3-foret":"nuitlongue"},"date_min":{"annee":1020,"mois":11,"jour":30}},"repetable":false,"romance":false,"quete":"q-ch3-foret","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"30 Nuitlongue 1020. La nuit la plus longue de l'année. Dans la Clairière de la Déchirure, l'air tremble plus fort que jamais."},{"qui":"vaelor","expression":"neutre","dit":"« Ils arrivent par le nord ! » Le capitaine Vaelor court entre les arbres. « La Légion Cendrée. Des centaines. Ils veulent la Clairière. »"},{"qui":"ilysse","expression":"neutre","dit":"« Bien sûr qu'ils la veulent. » Ilyssë est livide. « C'est l'endroit où le Voile est le plus fin. Avec assez de cristaux d'éther, ils pourraient le déchirer… de l'intérieur. »","si":{"flag":"ilysse-recrutee"}}],"effets":[],"choix":[],"combat":{"rencontre":"nuitlongue-legion","victoire":"morra","defaite":"morra"},"fin":false},"morra":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les soldats de la Légion reculent. Un passage s'ouvre dans leurs rangs. Une femme s'avance : cornes noires, cheveux couleur de braise, une épée-faux plus haute qu'elle."},{"qui":"morra","expression":"neutre","dit":"« Morwenna. Commandante de la Première Légion. Mais on m'appelle Morra. » Elle fait tourner sa faux. « Les Appelés. Le Souverain dit que vous êtes ses enfants. Moi, je dis que vous êtes ses chiens. Voyons qui a raison. »"}],"effets":[],"choix":[],"combat":{"rencontre":"nuitlongue-morra","victoire":"vaincue","defaite":"retraite"},"fin":false},"retraite":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Morra vous domine. Sa faux s'arrête sur votre gorge… puis elle la relève."},{"qui":"morra","expression":"neutre","dit":"« Pas cette nuit. » Elle siffle ; la Légion se retire. « Le Souverain veut que vous viviez. Je ne sais pas pourquoi. Ça m'agace. »"}],"effets":[{"flag":"morra-vivante"}],"choix":[],"suite":"apres","fin":false},"vaincue":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Morra tombe à genoux. Une de ses cornes est brisée. Elle lève les yeux vers vous, et dans ces yeux, il n'y a pas de haine. Il y a… de la fatigue."},{"qui":"morra","expression":"neutre","dit":"« Allez-y. » Elle laisse tomber sa faux. « Finissez. Il me tuera de toute façon, pour avoir perdu. »"}],"effets":[{"objet":"corne-de-morra"}],"choix":[{"texte":"L'achever. C'est une commandante de la Légion.","visible_si_bloque":false,"effets":[{"flag":"morra-tuee","reputation":{"elfes":5,"legion":-20}}],"aller":"achevee"},{"texte":"L'épargner. « Va-t'en. Et ne reviens pas. »","visible_si_bloque":false,"effets":[{"flag":["morra-vivante","morra-epargnee"],"reputation":{"elfes":-5}}],"aller":"epargnee"},{"texte":"« Pourquoi te tuerait-il ? » (Esprit, difficulté 24)","visible_si_bloque":false,"test":{"carac":"ESP","difficulte":24,"reussite":"soeur","echec":"epargnee-silence"},"effets":[]}],"fin":false},"soeur":{"repliques":[{"qui":"morra","expression":"neutre","dit":"Elle vous fixe longtemps. Puis, très bas : « Parce qu'il a ma sœur. Lyss. Elle a seize ans, enfin… l'équivalent. Il la garde dans la Citadelle. Tant que j'obéis, elle vit. »"},{"qui":"morra","expression":"neutre","dit":"« Si je rentre vaincue, il la punira. Si je ne rentre pas… » Elle rit, un rire cassé. « Je ne sais pas ce qu'il fera. »"}],"effets":[{"flag":["morra-vivante","morra-epargnee","morra-soeur-connue"]}],"choix":[],"suite":"epargnee","fin":false},"epargnee-silence":{"repliques":[{"qui":"morra","expression":"neutre","dit":"Elle détourne les yeux. « Ça ne te regarde pas, Appelé. »"}],"effets":[{"flag":["morra-vivante","morra-epargnee"]}],"choix":[],"suite":"epargnee","fin":false},"epargnee":{"repliques":[{"qui":"morra","expression":"neutre","dit":"Morra se relève, ramasse sa faux. Elle hésite, comme si elle allait dire quelque chose. Puis elle disparaît dans la nuit, sans se retourner."},{"qui":"elianne","expression":"neutre","dit":"Elianne la regarde partir. « Elle n'avait pas les yeux d'un monstre. » Elle frissonne. « C'est presque pire. »"}],"effets":[],"choix":[],"suite":"apres","fin":false},"achevee":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La lame tombe. La commandante de la Première Légion ne se relèvera plus. Autour de vous, les derniers soldats cendrés s'enfuient vers le nord."},{"qui":"ilysse","expression":"neutre","dit":"Ilyssë ramasse la corne brisée, pensive. « Une démone qui n'a pas supplié. On en apprend tous les jours. »","si":{"flag":"ilysse-recrutee"}}],"effets":[],"choix":[],"suite":"apres","fin":false},"apres":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"À l'aube, la Clairière est intacte. Le Voile tremble encore, mais il tient. Les elfes sortent des arbres, un par un, et vous regardent comme on regarde des gens qu'on ne connaissait pas."}],"effets":[{"reputation":{"elfes":10},"xp":450,"quete":{"id":"q-ch3-foret","etape":"verdict"},"journal":"30 Nuitlongue 1020 : {groupe} défendent la Clairière de la Déchirure contre la Légion Cendrée et sa commandante, Morra."}],"choix":[],"fin":true}}},"ch3-verdict":{"id":"ch3-verdict","titre":"Le verdict de la Reine","type":"groupe","lieu":"ithrael-cour","decor":"ithrael-cour","debut":"debut","disponible_si":{"quete_etape":{"q-ch3-foret":"verdict"}},"repetable":false,"romance":false,"quete":"q-ch3-foret","pnj":"reine-seve","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"reine-seve","expression":"neutre","dit":"La Reine-Sève vous attend debout, ce qui, chez elle, vaut une ovation. « Vous avez défendu la Clairière. Mon peuple s'en souviendra pendant mille ans. C'est long, mille ans, pour un souvenir. »"},{"qui":"reine-seve","expression":"neutre","dit":"« Les elfes de Sylvenoire seront vos alliés quand viendra la guerre. Nos archers. Nos guérisseurs. Notre mémoire. »"},{"qui":"reine-seve","expression":"neutre","dit":"« Ilyssë Vaëlnor. Ta peine est levée. Tu avais raison, et j'avais peur. Les reines aussi ont le droit d'avoir peur. »","si":{"flag":"ilysse-recrutee"}},{"qui":"ilysse","expression":"tristesse","dit":"Ilyssë ne dit rien. Pour une fois, elle n'a pas de réplique. Elle s'incline, très bas, et ses épaules tremblent.","si":{"flag":"ilysse-recrutee"}}],"effets":[{"flag":"elfes-allies","reputation":{"elfes":5}}],"choix":[{"texte":"« Merci, ma Reine. Nous reviendrons. »","visible_si_bloque":false,"effets":[],"aller":"fin"}],"fin":false},"fin":{"repliques":[{"qui":"elianne","expression":"neutre","dit":"Ce soir-là, sur la plus haute branche d'Ithrael, Elianne regarde vers l'est, vers les Monts Grisfer, et plus loin, la mer. « Si chaque Appel déchire le Voile… alors les invocations doivent cesser. Il faut que quelqu'un le dise. » Elle se tourne vers vous. « Il faut des preuves. »"},{"qui":"seraphine","expression":"neutre","dit":"Séraphine déplie une lettre qui vient d'arriver. « Les nains de Grisfer refusent toute alliance avec la Couronne. Et les dragons de l'Archipel… » Elle hésite. « On dit qu'une dragonne s'est réveillée. »","si":{"flag":"seraphine-recrutee"}},{"qui":"narrateur","expression":"neutre","dit":"La forêt se souvient. Désormais, vous aussi. Et la guerre approche à grands pas."}],"effets":[{"xp":400,"terminer_quete":"q-ch3-foret"},{"fin_chapitre":3}],"choix":[],"fin":true}}},"sq-follets-thaliel":{"id":"sq-follets-thaliel","titre":"Les lumières du bois : l'enfant perdue","type":"groupe","lieu":"ithrael-auberge","decor":"ithrael-auberge","debut":"debut","disponible_si":{"flag":"sylvenoire-ouverte","pas_flag":"follets-acceptes"},"repetable":false,"romance":false,"quete":"q-follets","pnj":"thaliel","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"thaliel","expression":"neutre","dit":"Thaliel n'a plus de sourire. « Ma petite sœur, Lirëa. Elle a suivi les feux follets hier soir, vers le bois. Les gardes disent qu'on ne revient pas du Bois des Feux follets. »"}],"effets":[],"choix":[{"texte":"« Nous la ramènerons. »","visible_si_bloque":false,"effets":[{"flag":"follets-acceptes","quete":{"id":"q-follets","etape":"bois"}}],"aller":"fin"}],"fin":false},"fin":{"repliques":[],"effets":[],"choix":[],"fin":true}}},"sq-follets-bois":{"id":"sq-follets-bois","titre":"Les lumières du bois : dans le bois","type":"groupe","lieu":"bois-des-feux-follets","decor":"bois-des-feux-follets","debut":"debut","disponible_si":{"quete_etape":{"q-follets":"bois"}},"repetable":false,"romance":false,"quete":"q-follets","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Des lumières bleues dansent entre les troncs. Elles vous appellent, doucement. Au loin, une petite voix chante."}],"effets":[],"choix":[{"texte":"Ignorer les lumières et suivre la voix. (Esprit, difficulté 24)","visible_si_bloque":false,"test":{"carac":"ESP","difficulte":24,"reussite":"trouvee","echec":"egares"},"effets":[]},{"texte":"Disperser les feux follets.","visible_si_bloque":false,"effets":[],"aller":"combat"}],"fin":false},"egares":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les lumières vous font tourner en rond. Puis elles s'impatientent… et attaquent."}],"effets":[],"choix":[],"suite":"combat","fin":false},"combat":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"follets-bois","victoire":"trouvee","defaite":"trouvee"},"fin":false},"trouvee":{"repliques":[{"qui":"enfant-ithrael","expression":"neutre","dit":"Au pied d'un arbre, une petite elfe chante aux lumières, ravie. « Elles sont jolies ! Elles m'ont montré plein de choses ! » Elle n'a aucune idée du danger."}],"effets":[{"quete":{"id":"q-follets","etape":"retour"}}],"choix":[],"fin":true}}},"sq-follets-retour":{"id":"sq-follets-retour","titre":"Les lumières du bois : le retour","type":"groupe","lieu":"ithrael-auberge","decor":"ithrael-auberge","debut":"debut","disponible_si":{"quete_etape":{"q-follets":"retour"}},"repetable":false,"romance":false,"quete":"q-follets","pnj":"thaliel","rend_quete":true,"noeuds":{"debut":{"repliques":[{"qui":"thaliel","expression":"joie","dit":"Thaliel serre sa sœur à l'étouffer. « Merci. Merci ! Vos hamacs sont gratuits, pour toujours. Et je vais vous chanter une chanson. Une longue. »"}],"effets":[{"reputation":{"elfes":6},"xp":450,"or":120,"terminer_quete":"q-follets"}],"choix":[],"fin":true}}},"sq-chene-mirwen":{"id":"sq-chene-mirwen","titre":"Le Vieux-Chêne malade : la sève violette","type":"groupe","lieu":"ithrael-marche","decor":"ithrael-marche","debut":"debut","disponible_si":{"flag":"sylvenoire-ouverte","pas_flag":"chene-accepte"},"repetable":false,"romance":false,"quete":"q-vieux-chene","pnj":"mirwen","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"mirwen","expression":"neutre","dit":"Mirwen montre un flacon de sève violette. « Le Vieux-Chêne. Il a trois mille ans. Sa sève devient comme ça depuis que des marchands humains ont enterré des caisses à ses pieds. Et les sylvains autour de lui deviennent fous. »"}],"effets":[],"choix":[{"texte":"« Des caisses… de cristaux d'éther ? Nous allons voir. »","visible_si_bloque":false,"effets":[{"flag":"chene-accepte","quete":{"id":"q-vieux-chene","etape":"chene"}}],"aller":"fin"}],"fin":false},"fin":{"repliques":[],"effets":[],"choix":[],"fin":true}}},"sq-chene":{"id":"sq-chene","titre":"Le Vieux-Chêne malade : les racines","type":"groupe","lieu":"vieux-chene","decor":"vieux-chene","debut":"debut","disponible_si":{"quete_etape":{"q-vieux-chene":"chene"}},"repetable":false,"romance":false,"quete":"q-vieux-chene","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Au pied du Vieux-Chêne, la terre est retournée. Des caisses marquées d'une rune violette dépassent du sol. Les cristaux qu'elles contiennent pulsent comme des cœurs malades."},{"qui":"narrateur","expression":"neutre","dit":"Les sylvains corrompus se dressent autour de l'arbre. Ils ne vous laisseront pas approcher."}],"effets":[],"choix":[],"combat":{"rencontre":"sylvains-corrompus","victoire":"caisses","defaite":"caisses"},"fin":false},"caisses":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous arrachez les caisses une à une. La sève du Vieux-Chêne pâlit lentement, du violet au vert."}],"effets":[],"choix":[{"texte":"Détruire les cristaux sur place.","visible_si_bloque":false,"effets":[{"reputation":{"elfes":6,"concorde":-4}}],"aller":"fini"},{"texte":"Garder les cristaux comme preuve du trafic de la Concorde.","visible_si_bloque":false,"effets":[{"flag":"preuve-cristaux-sylve","objet":["cristal-ether","cristal-ether"]}],"aller":"fini"}],"fin":false},"fini":{"repliques":[],"effets":[{"quete":{"id":"q-vieux-chene","etape":"retour"}}],"choix":[],"fin":true}}},"sq-chene-retour":{"id":"sq-chene-retour","titre":"Le Vieux-Chêne malade : le remède","type":"groupe","lieu":"ithrael-marche","decor":"ithrael-marche","debut":"debut","disponible_si":{"quete_etape":{"q-vieux-chene":"retour"}},"repetable":false,"romance":false,"quete":"q-vieux-chene","pnj":"mirwen","rend_quete":true,"noeuds":{"debut":{"repliques":[{"qui":"mirwen","expression":"neutre","dit":"Mirwen goûte une goutte de sève, ferme les yeux, et sourit. « Il guérira. Dans cent ans, il ne s'en souviendra plus. Nous, si. » Elle vous donne une petite graine dorée. « Plantez-la sur vos terres. »"}],"effets":[{"reputation":{"elfes":8,"troupes":3},"xp":500,"objet":"miel-des-fleurs-d-argent","terminer_quete":"q-vieux-chene"}],"choix":[],"fin":true}}},"sq-graine-vaelor":{"id":"sq-graine-vaelor","titre":"La graine volée : les accusations","type":"groupe","lieu":"ithrael-racines","decor":"ithrael-racines","debut":"debut","disponible_si":{"flag":"sylvenoire-ouverte","pas_flag":"graine-acceptee"},"repetable":false,"romance":false,"quete":"q-graine","pnj":"vaelor","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"vaelor","expression":"neutre","dit":"Le capitaine Vaelor est de mauvaise humeur, ce qui ne change pas de d'habitude. « Les dryades disent qu'un elfe a volé leur graine sacrée. Les elfes disent que c'est un humain. Vous êtes des humains. Vous êtes donc suspects. Ou utiles. Choisissez. »"}],"effets":[],"choix":[{"texte":"« Utiles. Nous trouverons le voleur. »","visible_si_bloque":false,"effets":[{"flag":"graine-acceptee","quete":{"id":"q-graine","etape":"cercle"}}],"aller":"fin"}],"fin":false},"fin":{"repliques":[],"effets":[],"choix":[],"fin":true}}},"sq-graine-cercle":{"id":"sq-graine-cercle","titre":"La graine volée : le Cercle des dryades","type":"groupe","lieu":"cercle-des-dryades","decor":"cercle-des-dryades","debut":"debut","disponible_si":{"quete_etape":{"q-graine":"cercle"}},"repetable":false,"romance":false,"quete":"q-graine","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les sept arbres du Cercle murmurent. Une dryade sort d'une écorce, furieuse, des feuilles plein les cheveux. « La graine de l'Arbre-Premier ! Volée ! Par quelqu'un qui sentait la boue et le champignon ! »"}],"effets":[],"choix":[{"texte":"« La boue et le champignon… le Marais de brume. »","visible_si_bloque":false,"effets":[{"xp":60,"quete":{"id":"q-graine","etape":"marais"}}],"aller":"fin"}],"fin":false},"fin":{"repliques":[],"effets":[],"choix":[],"fin":true}}},"sq-graine-marais":{"id":"sq-graine-marais","titre":"La graine volée : le voleur","type":"groupe","lieu":"marais-de-brume","decor":"marais-de-brume","debut":"debut","disponible_si":{"quete_etape":{"q-graine":"marais"}},"repetable":false,"romance":false,"quete":"q-graine","rend_quete":true,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Au milieu du marais, des champignons géants entourent un petit tas de terre. Dessus, la graine sacrée brille doucement. Les champignons l'ont « volée » pour la faire pousser chez eux."}],"effets":[],"choix":[],"combat":{"rencontre":"champignons-marais","victoire":"graine","defaite":"graine"},"fin":false},"graine":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous rapportez la graine au Cercle. Les dryades chantent ; Vaelor, lui, ne dit rien. Mais le soir même, il vous laisse passer la Porte des Racines sans vous fouiller. Chez lui, c'est presque une accolade."}],"effets":[{"reputation":{"elfes":10},"xp":450,"terminer_quete":"q-graine"}],"choix":[],"fin":true}}},"sq-domaine-arrivee":{"id":"sq-domaine-arrivee","titre":"Les gens du domaine : l'arrivée","type":"groupe","lieu":"domaine-lisiere","decor":"domaine-lisiere","debut":"debut","disponible_si":{"flag":"domaine-obtenu","pas_flag":"domaine-visite"},"repetable":false,"romance":false,"quete":"q-domaine","pnj":"intendant-domaine","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Votre domaine : un manoir au toit à moitié effondré, cinq fermes, un moulin qui ne tourne plus, et une centaine de personnes qui vous regardent arriver en se demandant si vous serez pires que le précédent seigneur."},{"qui":"intendant-domaine","expression":"neutre","dit":"Un vieil homme s'avance, chapeau à la main. « Maître Aubin, intendant. Trois fermes ont été pillées ce mois-ci. Des hommes en armure noire, venus de la forêt. Les gens ont peur, mes seigneurs. »"}],"effets":[],"choix":[{"texte":"« Plus maintenant. Où sont-ils ? »","visible_si_bloque":false,"effets":[{"flag":"domaine-visite","reputation":{"troupes":2},"quete":{"id":"q-domaine","etape":"pillards"}}],"aller":"fin"}],"fin":false},"fin":{"repliques":[{"qui":"intendant-domaine","expression":"neutre","dit":"« Les gardes forestiers ont vu un camp, au sud-ouest de la forêt. » Il hésite. « Revenez vivants. Le dernier seigneur n'est pas revenu. »"}],"effets":[],"choix":[],"fin":true}}},"sq-domaine-pillards":{"id":"sq-domaine-pillards","titre":"Les gens du domaine : le camp avancé","type":"groupe","lieu":"camp-legion-sylve","decor":"camp-legion-sylve","debut":"debut","disponible_si":{"quete_etape":{"q-domaine":"pillards"}},"repetable":false,"romance":false,"quete":"q-domaine","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Sous les fougères, des tentes noires. Des soldats de la Légion, et des diablotins qui rient en comptant des sacs de grain volé : votre grain."}],"effets":[],"choix":[],"combat":{"rencontre":"domaine-brigands","victoire":"victoire","defaite":"defaite"},"fin":false},"victoire":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le camp est vide. Vous rapportez le grain, et des armes noires que les forgerons du domaine pourront refondre."}],"effets":[{"reputation":{"troupes":6},"quete":{"id":"q-domaine","etape":"milice"}}],"choix":[],"fin":true},"defaite":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous battez en retraite, mais la Légion a compris : ces terres ont désormais un seigneur. Le camp est abandonné le lendemain."}],"effets":[{"reputation":{"troupes":2},"quete":{"id":"q-domaine","etape":"milice"}}],"choix":[],"fin":true}}},"sq-domaine-milice":{"id":"sq-domaine-milice","titre":"Les gens du domaine : la milice","type":"groupe","lieu":"domaine-lisiere","decor":"domaine-lisiere","debut":"debut","disponible_si":{"quete_etape":{"q-domaine":"milice"}},"repetable":false,"romance":false,"quete":"q-domaine","pnj":"intendant-domaine","rend_quete":true,"noeuds":{"debut":{"repliques":[{"qui":"intendant-domaine","expression":"neutre","dit":"Maître Aubin a réuni les fermiers dans la cour du manoir. « Ils veulent apprendre à se défendre. Avec vous. » Des fourches, des arcs de chasse, des visages déterminés."}],"effets":[],"choix":[{"texte":"Les entraîner vous-mêmes, chaque matin.","visible_si_bloque":false,"effets":[{"reputation":{"troupes":10}}],"aller":"fin"},{"texte":"Engager des sergents de la Guilde. (150 or)","si":{"or_min":150},"visible_si_bloque":false,"effets":[{"reputation":{"troupes":14},"or":-150}],"aller":"fin"}],"fin":false},"fin":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Quelques mois plus tard, votre domaine a une milice. Petite, mal équipée, mais fière. Et une bannière : la vôtre."},{"qui":"intendant-domaine","expression":"neutre","dit":"« Dans les temps libres, pensez à « Gérer le domaine » : plus vous y passez de temps, plus nous serons nombreux le jour où il faudra marcher au nord. »"}],"effets":[{"xp":400,"terminer_quete":"q-domaine"}],"choix":[],"fin":true}}},"cl-lame-runique-2":{"id":"cl-lame-runique-2","titre":"Lame runique — La forge des runes","type":"individuel","lieu":"karak-forge","decor":"karak-forge","debut":"debut","disponible_si":{"flag":"classe-1","pas_flag":"classe-2","classe":"lame-runique","ou":[{"flag":"karak-recus"}]},"repetable":false,"romance":false,"quete":"q-classe-lame-runique","pnj":"durna","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Maîtresse Durna examine la rune gravée sur votre lame. Elle siffle. « Le cercle fendu aux sept traits. La rune du Premier Sceau. Les tout premiers Appelés l'ont apportée ici, en l'an 430. »"},{"qui":"narrateur","expression":"neutre","dit":"« Gravée, elle tient. Forgée dans l'acier, elle devient une partie de l'arme. Mais il faut frapper au bon moment, quand le métal chante. Et le tenir pendant qu'il chante. »"}],"effets":[],"choix":[{"texte":"Tenir la lame dans le feu pendant que Durna frappe. (Vitalité, difficulté 28)","visible_si_bloque":false,"test":{"carac":"VIT","difficulte":28,"reussite":"reussi","echec":"rate"},"effets":[]},{"texte":"Frapper vous-même, au rythme de Durna. (Force, difficulté 28)","visible_si_bloque":false,"test":{"carac":"FOR","difficulte":28,"reussite":"reussi","echec":"rate"},"effets":[]}],"fin":false},"reussi":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La lame chante. La rune s'enfonce dans l'acier, puis disparaît… et se rallume, de l'intérieur, comme un cœur qui bat. Durna essuie une larme de suie. « Mille ans que je n'avais pas entendu ça. »"},{"qui":"narrateur","expression":"neutre","dit":"« Il reste une dernière rune, celle des Mille Sceaux. Personne ne sait la graver. On dit qu'elle n'apparaît que sur un champ de bataille. »"}],"effets":[{"flag":"heros:classe-2","xp":400,"quete":{"id":"q-classe-lame-runique","etape":"etape3"}}],"choix":[],"fin":true},"rate":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La lame se tord, se fend… puis se ressoude d'elle-même, la rune au cœur de l'acier, de travers. Durna fronce les sourcils. « Elle t'a choisi quand même. Têtue, comme son porteur. »"}],"effets":[{"flag":"heros:classe-2","xp":250,"quete":{"id":"q-classe-lame-runique","etape":"etape3"}}],"choix":[],"fin":true}}},"cl-arcaniste-2":{"id":"cl-arcaniste-2","titre":"Arcaniste — Le feu de la montagne","type":"individuel","lieu":"coulee-de-lave","decor":"coulee-de-lave","debut":"debut","disponible_si":{"flag":"classe-1","pas_flag":"classe-2","classe":"arcaniste","ou":[{"flag":"karak-recus"}]},"repetable":false,"romance":false,"quete":"q-classe-arcaniste","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La Coulée de lave descend lentement. La chaleur vous brûle les cils. Quelque part en vous, la foudre du désert et le givre de vos débuts s'agitent : ils reconnaissent leur cousin."},{"qui":"narrateur","expression":"neutre","dit":"Le feu de la terre ne se capture pas comme un éclair. Il est lent, lourd, patient. Il faut le laisser venir."}],"effets":[],"choix":[{"texte":"Plonger les mains dans la lave et l'appeler. (Intelligence, difficulté 28)","visible_si_bloque":false,"test":{"carac":"INT","difficulte":28,"reussite":"reussi","echec":"rate"},"effets":[]},{"texte":"Méditer au bord de la coulée jusqu'à ce que le feu vienne. (Esprit, difficulté 28)","visible_si_bloque":false,"test":{"carac":"ESP","difficulte":28,"reussite":"reussi","echec":"rate"},"effets":[]}],"fin":false},"reussi":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La lave monte le long de vos bras sans les brûler, puis rentre en vous, comme une rivière qui trouve son lit. Le feu, la foudre, le givre : trois éléments tournent maintenant en vous."},{"qui":"narrateur","expression":"neutre","dit":"Il en manque un. Le quatrième, l'ombre ou la lumière ? Vous le saurez quand vous le verrez. Sur un champ de bataille, peut-être."}],"effets":[{"flag":"heros:classe-2","xp":400,"quete":{"id":"q-classe-arcaniste","etape":"etape3"}}],"choix":[],"fin":true},"rate":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La lave vous rejette, et vous voilà assis dans la cendre, les mains rouges. Mais une braise est restée au creux de votre paume, et elle ne s'éteint pas."}],"effets":[{"flag":"heros:classe-2","xp":250,"quete":{"id":"q-classe-arcaniste","etape":"etape3"}}],"choix":[],"fin":true}}},"cl-invocateur-2":{"id":"cl-invocateur-2","titre":"Invocateur — L'esprit-dragon","type":"individuel","lieu":"nid-des-wyrms","decor":"nid-des-wyrms","debut":"debut","disponible_si":{"flag":"classe-1","pas_flag":"classe-2","classe":"invocateur","ou":[{"flag":"carte-du-nid"}]},"repetable":false,"romance":false,"quete":"q-classe-invocateur","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Dans un nid vide, au sommet de l'île, l'air tremble. Une forme translucide se dresse : un dragon fait de fumée et de lumière, mort depuis des siècles. Un esprit-dragon."},{"qui":"narrateur","expression":"neutre","dit":"Vos créatures se cachent derrière vous. Le fennec du désert, lui, s'assoit à vos pieds et regarde l'esprit sans peur. « Demande », semble-t-il dire."}],"effets":[],"choix":[{"texte":"Demander, au lieu d'ordonner. (Charisme, difficulté 28)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":28,"reussite":"reussi","echec":"rate"},"effets":[]},{"texte":"Lui offrir un peu de votre propre énergie. (Esprit, difficulté 28)","visible_si_bloque":false,"test":{"carac":"ESP","difficulte":28,"reussite":"reussi","echec":"rate"},"effets":[]}],"fin":false},"reussi":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"L'esprit-dragon baisse la tête jusqu'à vous. Il souffle, et votre grimoire se couvre d'une écriture que vous ne connaissiez pas. Un nom. Le sien. Il viendra, si vous l'appelez."},{"qui":"narrateur","expression":"neutre","dit":"Au loin, quelque chose s'ouvre : une porte que vous sentez sans la voir. La Porte du Bestiaire, que seuls les grands invocateurs franchissent."}],"effets":[{"flag":"heros:classe-2","xp":400,"quete":{"id":"q-classe-invocateur","etape":"etape3"}}],"choix":[],"fin":true},"rate":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"L'esprit-dragon vous ignore et s'envole. Mais il tourne trois fois au-dessus du nid avant de disparaître. Ce n'est pas un non. C'est encore un « pas encore »."}],"effets":[{"flag":"heros:classe-2","xp":250,"quete":{"id":"q-classe-invocateur","etape":"etape3"}}],"choix":[],"fin":true}}},"cl-ombre-2":{"id":"cl-ombre-2","titre":"Ombre — Le maître de Kezir","type":"individuel","lieu":"port-taverne","decor":"port-taverne","debut":"debut","disponible_si":{"flag":"classe-1","pas_flag":"classe-2","classe":"ombre","ou":[{"flag":"carte-du-nid"}]},"repetable":false,"romance":false,"quete":"q-classe-ombre","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Au fond du Requin Ivre, un vieillard aveugle joue aux osselets tout seul. Il gagne à chaque fois. Quand vous approchez, il dit, sans lever la tête : « Tu marches comme Kezir. En plus discret. »"},{"qui":"narrateur","expression":"neutre","dit":"« J'ai formé Kezir. Il était doué. Il est devenu cruel. » Il lance les osselets. « Je ne forme plus personne. Sauf ceux qui arrivent à me voler ma bourse. »"}],"effets":[],"choix":[{"texte":"Lui voler sa bourse. (Agilité, difficulté 28)","visible_si_bloque":false,"test":{"carac":"AGI","difficulte":28,"reussite":"reussi","echec":"rate"},"effets":[]},{"texte":"Lui dire qu'on ne veut pas voler sa bourse. (Esprit, difficulté 28)","visible_si_bloque":false,"test":{"carac":"ESP","difficulte":28,"reussite":"reussi","echec":"rate"},"effets":[]}],"fin":false},"reussi":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le vieillard sourit, et vous tend la main. Sa bourse est dedans. Ou alors c'est la vôtre ? « Bien. Je vais t'apprendre la seule chose que je n'ai jamais apprise à Kezir : quand ne pas frapper. »"},{"qui":"narrateur","expression":"neutre","dit":"Il vous parle des Mille Coupures, la technique ultime des Ombres. « On ne l'apprend pas. On la trouve, au milieu d'une bataille, quand on a tout perdu. »"}],"effets":[{"flag":"heros:classe-2","xp":400,"quete":{"id":"q-classe-ombre","etape":"etape3"}}],"choix":[],"fin":true},"rate":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le vieillard vous attrape le poignet avant même que vous ayez bougé. Il rit. « Trop d'envie. » Puis il vous lâche. « Reviens quand tu auras moins envie. Mais tu as du talent. Je t'apprendrai quand même. »"}],"effets":[{"flag":"heros:classe-2","xp":250,"quete":{"id":"q-classe-ombre","etape":"etape3"}}],"choix":[],"fin":true}}},"cl-gardien-2":{"id":"cl-gardien-2","titre":"Gardien — La passe des Marches","type":"individuel","lieu":"karak-porte","decor":"karak-porte","debut":"debut","disponible_si":{"flag":"classe-1","pas_flag":"classe-2","classe":"gardien","ou":[{"flag":"registre-lu"}]},"repetable":false,"romance":false,"quete":"q-classe-gardien","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le vieux paladin de Qarzim vous attendait devant la Porte de Karak-Dûm. Il a fait tout le chemin à pied. « Les nains m'ont laissé passer. Ils disent que tu es descendu au fond. Bien. Maintenant, tiens la passe. »"},{"qui":"narrateur","expression":"neutre","dit":"Il vous mène au premier palier des Mille Marches, là où l'escalier est si étroit qu'un seul homme peut le défendre. Des statues de rois nains, de chaque côté. « Prête le serment ici. Face à l'ennemi. »"}],"effets":[],"choix":[{"texte":"Tenir la passe toute la nuit, bouclier levé, sans reculer d'un pas. (Vitalité, difficulté 28)","visible_si_bloque":false,"test":{"carac":"VIT","difficulte":28,"reussite":"reussi","echec":"rate"},"effets":[]},{"texte":"Prononcer le serment du bouclier devant les rois de pierre. (Charisme, difficulté 28)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":28,"reussite":"reussi","echec":"rate"},"effets":[]}],"fin":false},"reussi":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"À l'aube, le vieux paladin pose la main sur votre bouclier. Une lueur passe de sa main au métal. « Le serment est pris. Il en reste un, le dernier. Celui du Bastion éternel. On le prête une seule fois, et on ne s'en relève pas tout à fait. »"}],"effets":[{"flag":"heros:classe-2","xp":400,"quete":{"id":"q-classe-gardien","etape":"etape3"}}],"choix":[],"fin":true},"rate":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Au milieu de la nuit, vous reculez d'un pas. Un seul. Le vieux paladin ne dit rien. À l'aube, il dit seulement : « Un pas. C'est moins que moi, la première fois. » Et il vous apprend le serment quand même."}],"effets":[{"flag":"heros:classe-2","xp":250,"quete":{"id":"q-classe-gardien","etape":"etape3"}}],"choix":[],"fin":true}}},"cl-alchimiste-2":{"id":"cl-alchimiste-2","titre":"Alchimiste — Le cœur de forge","type":"individuel","lieu":"karak-forge","decor":"karak-forge","debut":"debut","disponible_si":{"flag":"classe-1","pas_flag":"classe-2","classe":"alchimiste","ou":[{"flag":"karak-recus"}]},"repetable":false,"romance":false,"quete":"q-classe-alchimiste","pnj":"durna","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous étalez les plans du golem d'airain sur l'établi de Durna. La forgeronne regarde le cercle vide marqué « cœur de forge ». Elle éclate de rire. « Un cœur de forge ! Pour un jouet de vulpin ! »"},{"qui":"narrateur","expression":"neutre","dit":"« Un cœur de forge, c'est une braise de la Grande Forge, enfermée dans une sphère de bronze. On n'en donne pas. On en gagne. »"}],"effets":[],"choix":[{"texte":"Fabriquer devant elle une potion qui résiste au feu de la forge. (Intelligence, difficulté 28)","visible_si_bloque":false,"test":{"carac":"INT","difficulte":28,"reussite":"reussi","echec":"rate"},"effets":[]},{"texte":"Lui proposer d'échanger vos meilleures recettes. (Charisme, difficulté 28)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":28,"reussite":"reussi","echec":"rate"},"effets":[]}],"fin":false},"reussi":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Durna regarde votre fiole résister au feu. Elle se tait longtemps. Puis elle va chercher, au fond de la forge, une sphère de bronze qui bat comme un cœur. « Ne le gaspille pas. »"},{"qui":"narrateur","expression":"neutre","dit":"Le golem d'airain a maintenant un cœur. Il ne lui manque que la vie. Et ça, aucun plan ne dit comment la donner."}],"effets":[{"flag":"heros:classe-2","xp":400,"quete":{"id":"q-classe-alchimiste","etape":"etape3"}}],"choix":[],"fin":true},"rate":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La fiole éclate. Durna hausse les épaules, puis vous tend quand même un cœur de forge, plus petit. « Pour avoir essayé. Les nains respectent ceux qui ratent bruyamment. »"}],"effets":[{"flag":"heros:classe-2","xp":250,"quete":{"id":"q-classe-alchimiste","etape":"etape3"}}],"choix":[],"fin":true}}},"cl-archer-2":{"id":"cl-archer-2","titre":"Archer — La cible des vents","type":"individuel","lieu":"phare-noye","decor":"phare-noye","debut":"debut","disponible_si":{"flag":"classe-1","pas_flag":"classe-2","classe":"archer","ou":[{"flag":"carte-du-nid"}]},"repetable":false,"romance":false,"quete":"q-classe-archer","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Au sommet du Phare noyé, les vents de l'Archipel se croisent. Sur un rocher, au loin, une cible de bois peinte, que les marins appellent « la cible des vents ». Le vent la fait trembler sans cesse."},{"qui":"narrateur","expression":"neutre","dit":"La plume blanche de l'Ancienne Sorha frémit sur votre arc. « Ferme les yeux », disait-elle."}],"effets":[],"choix":[{"texte":"Fermer les yeux et tirer. (Agilité, difficulté 28)","visible_si_bloque":false,"test":{"carac":"AGI","difficulte":28,"reussite":"reussi","echec":"rate"},"effets":[]},{"texte":"Attendre que le vent se taise, une seconde, et tirer. (Esprit, difficulté 28)","visible_si_bloque":false,"test":{"carac":"ESP","difficulte":28,"reussite":"reussi","echec":"rate"},"effets":[]}],"fin":false},"reussi":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La flèche part. Le vent la porte, la tourne, la ramène… et elle se plante au centre exact. Pendant une seconde, vous entendez des voix : des archers morts depuis mille ans, qui rient. Les ancêtres."},{"qui":"narrateur","expression":"neutre","dit":"« Un jour, dit une des voix, tu nous appelleras tous. Et nous tirerons avec toi. »"}],"effets":[{"flag":"heros:classe-2","xp":400,"quete":{"id":"q-classe-archer","etape":"etape3"}}],"choix":[],"fin":true},"rate":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La flèche se perd dans la brume. Mais le vent vous la rapporte, et la pose à vos pieds. Une voix, très loin : « Pas encore. Mais nous t'avons entendu. »"}],"effets":[{"flag":"heros:classe-2","xp":250,"quete":{"id":"q-classe-archer","etape":"etape3"}}],"choix":[],"fin":true}}},"cl-guerisseur-2":{"id":"cl-guerisseur-2","titre":"Guérisseur — La source sacrée","type":"individuel","lieu":"recif-des-sirenes","decor":"recif-des-sirenes","debut":"debut","disponible_si":{"flag":"classe-1","pas_flag":"classe-2","classe":"guerisseur","ou":[{"flag":"carte-du-nid"}]},"repetable":false,"romance":false,"quete":"q-classe-guerisseur","pnj":"sirene","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Néréa vous attend sur son rocher. « Une source de lumière, sous la mer ? » Elle rit. « Bien sûr qu'elle existe. Nous y soignons nos blessés. Mais un humain s'y noie avant d'y arriver. »"},{"qui":"narrateur","expression":"neutre","dit":"Elle plonge, et ressort avec une bulle d'air enfermée dans un coquillage. « Respire là-dedans. Et suis-moi. Ne lâche pas ma main. »"}],"effets":[],"choix":[{"texte":"Plonger avec elle jusqu'à la source. (Vitalité, difficulté 28)","visible_si_bloque":false,"test":{"carac":"VIT","difficulte":28,"reussite":"reussi","echec":"rate"},"effets":[]},{"texte":"Lui demander de vous apporter l'eau de la source. (Charisme, difficulté 28)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":28,"reussite":"reussi","echec":"rate"},"effets":[]}],"fin":false},"reussi":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Au fond, une source de lumière jaillit du sable, chaude comme un soleil. Vous y plongez les mains, et votre propre lumière change de couleur. Elle a un deuxième souffle, maintenant."},{"qui":"narrateur","expression":"neutre","dit":"Néréa, dans l'eau : « Les sirènes disent que celui qui a bu à la source peut ramener quelqu'un une fois. Une seule fois. Choisis bien. »"}],"effets":[{"flag":"heros:classe-2","xp":400,"quete":{"id":"q-classe-guerisseur","etape":"etape3"}}],"choix":[],"fin":true},"rate":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"L'eau vous chasse, et Néréa vous ramène à la surface, toussant. Mais dans vos mains, il reste un peu de lumière liquide. Elle n'a pas fini de vous parler."}],"effets":[{"flag":"heros:classe-2","xp":250,"quete":{"id":"q-classe-guerisseur","etape":"etape3"}}],"choix":[],"fin":true}}},"cl-berserker-2":{"id":"cl-berserker-2","titre":"Berserker — La chanson du sang","type":"individuel","lieu":"nid-des-wyrms","decor":"nid-des-wyrms","debut":"debut","disponible_si":{"flag":"classe-1","pas_flag":"classe-2","classe":"berserker","ou":[{"flag":"carte-du-nid"}]},"repetable":false,"romance":false,"quete":"q-classe-berserker","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les jeunes wyrms du Nid vous entourent, en sifflant. Ils ne vous attaquent pas. Ils vous reniflent. Votre sang bat plus fort à chaque souffle."},{"qui":"narrateur","expression":"neutre","dit":"Au milieu d'eux, un vieux wyrm aux écailles grises ouvre un œil. Il ne parle pas. Il gronde, et le grondement monte dans votre poitrine comme une chanson."}],"effets":[],"choix":[{"texte":"Gronder avec lui, de toutes vos forces. (Force, difficulté 28)","visible_si_bloque":false,"test":{"carac":"FOR","difficulte":28,"reussite":"reussi","echec":"rate"},"effets":[]},{"texte":"Le laisser chanter, et écouter. (Esprit, difficulté 28)","visible_si_bloque":false,"test":{"carac":"ESP","difficulte":28,"reussite":"reussi","echec":"rate"},"effets":[]}],"fin":false},"reussi":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Votre voix se mêle à la sienne. Les wyrms reprennent tous ensemble. Vos yeux brûlent, et cette fois, vous voyez vraiment vos ailes, dans votre ombre, sur la roche."},{"qui":"narrateur","expression":"neutre","dit":"Le vieux wyrm se rendort. Mais vous savez maintenant que la chanson a une fin. La Forme du Wyrm. Elle viendra quand le sang chantera sa dernière note."}],"effets":[{"flag":"heros:classe-2","xp":400,"quete":{"id":"q-classe-berserker","etape":"etape3"}}],"choix":[],"fin":true},"rate":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Votre voix se casse. Les wyrms s'éloignent, déçus. Mais le vieux wyrm, avant de fermer l'œil, souffle une petite flamme sur votre main. Une promesse."}],"effets":[{"flag":"heros:classe-2","xp":250,"quete":{"id":"q-classe-berserker","etape":"etape3"}}],"choix":[],"fin":true}}},"cl-barde-2":{"id":"cl-barde-2","titre":"Barde — Le dernier couplet","type":"individuel","lieu":"recif-des-sirenes","decor":"recif-des-sirenes","debut":"debut","disponible_si":{"flag":"classe-1","pas_flag":"classe-2","classe":"barde","ou":[{"flag":"carte-du-nid"}]},"repetable":false,"romance":false,"quete":"q-classe-barde","pnj":"sirene","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le soir tombe sur le Récif. Vous jouez les trois couplets des Dunes chantantes. Une à une, des têtes sortent de l'eau. Des sirènes. Elles écoutent, les yeux brillants."},{"qui":"narrateur","expression":"neutre","dit":"Néréa nage jusqu'à vous. « Ce chant-là… Les dunes l'ont volé à nos grands-mères. » Elle sourit. « Le dernier couplet ne se joue pas. Il se chante. À deux voix. »"}],"effets":[],"choix":[{"texte":"Chanter le dernier couplet avec elle. (Charisme, difficulté 28)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":28,"reussite":"reussi","echec":"rate"},"effets":[]},{"texte":"Écouter jusqu'à l'avoir dans la tête, puis le jouer. (Intelligence, difficulté 28)","visible_si_bloque":false,"test":{"carac":"INT","difficulte":28,"reussite":"reussi","echec":"rate"},"effets":[]}],"fin":false},"reussi":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vos deux voix s'élèvent ensemble. La mer se calme. Au loin, les dunes du désert, à des centaines de lieues, se mettent à chanter, elles aussi. Vous le sentez."},{"qui":"narrateur","expression":"neutre","dit":"Quatre couplets. Une chanson complète. Néréa vous chuchote : « Il existe une symphonie. Une seule. On la joue à la fin des guerres. Tu la trouveras. »"}],"effets":[{"flag":"heros:classe-2","xp":400,"quete":{"id":"q-classe-barde","etape":"etape3"}}],"choix":[],"fin":true},"rate":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Votre voix déraille, et les sirènes éclatent de rire. Néréa aussi. Puis elle vous chante le couplet, doucement, trois fois. Vous l'avez. Mal, mais vous l'avez."}],"effets":[{"flag":"heros:classe-2","xp":250,"quete":{"id":"q-classe-barde","etape":"etape3"}}],"choix":[],"fin":true}}},"ys-ecailles":{"id":"ys-ecailles","titre":"Ysoria — Les coutumes humaines","type":"individuel","lieu":"port-taverne","decor":"port-taverne","debut":"debut","disponible_si":{"flag":"ysoria-recrutee"},"repetable":false,"romance":false,"pnj":"ysoria","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"ysoria","expression":"neutre","dit":"Ysoria a commandé « tout ». Le vieux Brann a pris ça au pied de la lettre. Elle mange avec les mains, sur une table couverte de plats, sous les regards horrifiés des pirates."},{"qui":"ysoria","expression":"neutre","dit":"« Pourquoi les humains mettent-ils leur nourriture dans des petites assiettes ? C'est inefficace. » Elle vous tend une cuisse de poulet entière. « Mange. Tu es trop petit. »"}],"effets":[],"choix":[{"texte":"Manger avec les mains, comme elle.","visible_si_bloque":false,"effets":[{"affinite":{"ysoria":6}}],"aller":"fin"},{"texte":"Lui expliquer patiemment à quoi sert une fourchette.","visible_si_bloque":false,"effets":[{"affinite":{"ysoria":3}}],"aller":"fourchette"}],"fin":false},"fourchette":{"repliques":[{"qui":"ysoria","expression":"neutre","dit":"Elle examine la fourchette longtemps, très sérieuse. Puis elle la plie en forme de bague et la met à son doigt. « C'est joli. Ça brille. Merci. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"ysoria","expression":"joie","dit":"Le soir, elle dort sur le comptoir, au milieu des pièces d'or de la caisse, roulée en boule. Brann n'ose pas la réveiller pour récupérer sa recette."}],"effets":[],"choix":[],"fin":true}}},"ys-oeuf":{"id":"ys-oeuf","titre":"Ysoria — La piste de l'œuf","type":"individuel","lieu":"port-marche","decor":"port-marche","debut":"debut","disponible_si":{"flag":"ysoria-recrutee","affinite_palier":{"ysoria":"proche"}},"repetable":false,"romance":false,"quete":"q-ysoria","pnj":"corail","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"ysoria","expression":"neutre","dit":"Ysoria entre au Marché aux épaves et toutes les conversations s'arrêtent. Elle va droit à Corail. « Tu vends tout ce que la mer rapporte. As-tu vendu un œuf ? Rouge et or, gros comme ça, chaud comme une forge ? »"},{"qui":"corail","expression":"neutre","dit":"Corail pâlit, ce qui est difficile pour une sang-dragon. « Je… Je ne l'ai pas vendu. Je l'ai vu passer. Il y a trois ans. Sur un navire de la Concorde, vers le nord. Vers le Mur d'Aube. »"},{"qui":"corail","expression":"neutre","dit":"« Le capitaine disait qu'un acheteur l'attendait de l'autre côté du Mur. Un acheteur qui paie en obsidienne. »"}],"effets":[],"choix":[{"texte":"Poser la main sur l'épaule d'Ysoria. « Nous le retrouverons. »","visible_si_bloque":false,"effets":[{"affinite":{"ysoria":8}}],"aller":"fin"},{"texte":"« De l'autre côté du Mur… La Légion a ton œuf. »","visible_si_bloque":false,"effets":[{"affinite":{"ysoria":5}}],"aller":"fin"}],"fin":false},"fin":{"repliques":[{"qui":"ysoria","expression":"colere","dit":"La température monte dans tout le marché. Les bougies fondent. Puis Ysoria ferme les yeux, et l'air redevient frais. « Le Souverain a mon œuf. » Sa voix est très calme. « Alors j'irai le chercher dans sa Citadelle, et je brûlerai tout ce qui sera entre lui et moi. »"}],"effets":[{"flag":"oeuf-chez-legion","affinite":{"ysoria":4},"xp":300,"quete":{"id":"q-ysoria","etape":"eclosion"}}],"choix":[],"fin":true}}},"ys-vol":{"id":"ys-vol","titre":"Ysoria — Au-dessus des nuages","type":"individuel","lieu":"nid-des-wyrms","decor":"nid-des-wyrms","debut":"debut","disponible_si":{"flag":"ysoria-recrutee","affinite_palier":{"ysoria":"amoureuse"}},"repetable":false,"romance":true,"rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"ysoria","expression":"neutre","dit":"« Monte. » Ysoria a repris sa vraie forme : une dragonne d'or, immense. Elle baisse le cou jusqu'au sol. « Aucun humain n'est jamais monté sur mon dos. Tu seras le premier. Ne le dis à personne. »"},{"qui":"narrateur","expression":"neutre","dit":"Elle s'envole. L'Archipel rétrécit sous vous, puis les nuages, puis il n'y a plus que le ciel, immense, et le soleil couchant sur ses écailles."}],"effets":[],"choix":[{"texte":"« C'est le plus beau cadeau qu'on m'ait jamais fait. »","visible_si_bloque":false,"effets":[{"affinite":{"ysoria":6}}],"aller":"fin"}],"fin":false},"fin":{"repliques":[{"qui":"ysoria","expression":"gene","dit":"Plus tard, au sommet du Nid, elle a repris forme humaine. Elle se blottit contre vous, brûlante. « Chez les dragons, on choisit une fois. Pour mille ans. » Elle ferme les yeux. « J'ai choisi. »"},{"qui":"narrateur","expression":"neutre","dit":"(Fondu au noir.)"}],"effets":[],"choix":[],"fin":true}}},"mo-pain":{"id":"mo-pain","titre":"Morra — Le pain chaud","type":"individuel","lieu":"karak-porte","decor":"karak-porte","debut":"debut","disponible_si":{"flag":"morra-recrutee"},"repetable":false,"romance":false,"pnj":"morra","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"morra","expression":"neutre","dit":"Morra est assise sur les marches de la Porte, un pain entier dans les mains. Elle le regarde comme on regarde un trésor. « Dans les Cendres, on mange de la cendre. Littéralement. Ça, c'est… » Elle mord dedans. Elle ferme les yeux."},{"qui":"morra","expression":"neutre","dit":"« Ne me regarde pas comme ça. Une démone a le droit d'aimer le pain. »"}],"effets":[],"choix":[{"texte":"S'asseoir à côté d'elle et partager le pain.","visible_si_bloque":false,"effets":[{"affinite":{"morra":6}}],"aller":"fin"},{"texte":"« Tu sais qu'il y a aussi des gâteaux, à Lysmont ? »","visible_si_bloque":false,"effets":[{"affinite":{"morra":5}}],"aller":"gateaux"}],"fin":false},"gateaux":{"repliques":[{"qui":"morra","expression":"neutre","dit":"Elle se fige. « Des gâteaux. » Un silence. « Appelé, si tu me mens, je te coupe en deux. » Un autre silence. « … Quel genre de gâteaux ? »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"morra","expression":"neutre","dit":"Les gardes nains la regardent de travers. Elle leur fait un grand sourire plein de dents pointues. Ils regardent ailleurs. Elle rit."}],"effets":[],"choix":[],"fin":true}}},"mo-chaines":{"id":"mo-chaines","titre":"Morra — Les chaînes d'obsidienne","type":"individuel","lieu":"karak-forge","decor":"karak-forge","debut":"debut","disponible_si":{"flag":"morra-recrutee","affinite_palier":{"morra":"proche"}},"repetable":false,"romance":false,"quete":"q-morra","pnj":"durna","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"morra","expression":"neutre","dit":"Morra pose un maillon de chaîne noire sur l'enclume de Durna. « Arraché à la chaîne de Lyss, le jour où je suis partie. Obsidienne des Cendres. Aucune lame ne la coupe. »"},{"qui":"durna","expression":"neutre","dit":"Maîtresse Durna frappe le maillon. Son marteau rebondit. Elle frappe encore, plus fort. Rien. Elle siffle d'admiration. « Une matière qui résiste au feu de mille ans… Il faudrait une clé, pas une lame. Une clé de braise, forgée dans un feu plus vieux que les Cendres. »"},{"qui":"durna","expression":"neutre","dit":"« Le feu d'un dragon, par exemple. » Elle se gratte le menton. « Si votre dragonne veut bien souffler dans ma forge… »"}],"effets":[],"choix":[{"texte":"« Nous trouverons ce feu. Je te le promets, Morra. »","visible_si_bloque":false,"effets":[{"affinite":{"morra":8}}],"aller":"fin"},{"texte":"Prendre la main de Morra, sans rien dire.","visible_si_bloque":false,"effets":[{"affinite":{"morra":6}}],"aller":"fin"}],"fin":false},"fin":{"repliques":[{"qui":"morra","expression":"tristesse","dit":"Morra reprend le maillon et le serre dans son poing. « Trois siècles que je sers le Souverain pour qu'elle vive. » Elle vous regarde. « C'est la première fois que quelqu'un me dit « nous ». »"}],"effets":[{"flag":"cle-de-braise-connue","xp":300,"quete":{"id":"q-morra","etape":"cle"}}],"choix":[],"fin":true}}},"mo-toit":{"id":"mo-toit","titre":"Morra — Sur les toits de Karak-Dûm","type":"individuel","lieu":"karak-taverne","decor":"karak-taverne","debut":"debut","disponible_si":{"flag":"morra-recrutee","affinite_palier":{"morra":"amoureuse"}},"repetable":false,"romance":true,"rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"morra","expression":"neutre","dit":"Morra vous a entraîné sur le toit de la Chope Ardente, au-dessus des cheminées de la cité-forge. Elle regarde les étincelles monter dans la nuit. « Dans les Cendres, il n'y a pas d'étoiles. J'en ai vu pour la première fois cette année. »"},{"qui":"morra","expression":"gene","dit":"« Je ne sais pas faire ça. Les… sentiments. Trois cents ans, et je ne sais pas. » Elle grogne. « C'est ridicule. Arrête de sourire. »"}],"effets":[],"choix":[{"texte":"« On apprendra ensemble. »","visible_si_bloque":false,"effets":[{"affinite":{"morra":6}}],"aller":"fin"}],"fin":false},"fin":{"repliques":[{"qui":"morra","expression":"joie","dit":"Elle vous regarde longtemps. Puis elle pose son front contre le vôtre, ses cornes vous effleurant les cheveux. « D'accord. Ensemble. Mais si tu le racontes à quelqu'un, je nie tout… »"},{"qui":"narrateur","expression":"neutre","dit":"(Fondu au noir.)"}],"effets":[],"choix":[],"fin":true}}},"av-verite":{"id":"av-verite","titre":"Aveline — Le nom de mon père","type":"individuel","lieu":"karak-taverne","decor":"karak-taverne","debut":"debut","disponible_si":{"flag":"registre-lu","affinite_min":{"aveline":40},"quete_etape":{"q-aveline":"verite"}},"repetable":false,"romance":false,"quete":"q-aveline","pnj":"aveline","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Aveline n'a pas touché à sa chope. Elle a l'estampage du Registre étalé devant elle, et la lettre de Valgrane qu'elle garde depuis Qarzim. « Les dates correspondent. Le jour de l'Appel secret, mon père tenait la porte nord de Valgrane. »"},{"qui":"aveline","expression":"tristesse","dit":"« Il a vu le cercle s'ouvrir. Il a vu les Cendres sortir. Il a fait évacuer la ville. Trois mille personnes. » Sa voix se brise. « Et l'Ordre l'a fait exécuter pour trahison, pour que personne ne sache ce qu'il avait vu. »"}],"effets":[],"choix":[{"texte":"« Ton père était un héros, Aveline. Nous le ferons savoir à tout le royaume. »","visible_si_bloque":false,"effets":[{"affinite":{"aveline":8}}],"aller":"fin"},{"texte":"La laisser pleurer contre votre épaule, sans rien dire.","visible_si_bloque":false,"effets":[{"affinite":{"aveline":10}}],"aller":"fin"}],"fin":false},"fin":{"repliques":[{"qui":"aveline","expression":"neutre","dit":"Elle s'essuie les yeux, se redresse, redevient la capitaine. « Gauvain de Castelroc. Je veux entendre ce nom crié sur la place de Lysmont. Pas murmuré. » Elle serre votre main. « Merci de m'avoir suivie jusqu'ici. »"}],"effets":[{"flag":"verite-valgrane","xp":300,"quete":{"id":"q-aveline","etape":"rehabilitation"}}],"choix":[],"fin":true}}},"el-revelation":{"id":"el-revelation","titre":"Elianne — Ce que la Lumière cache","type":"individuel","lieu":"karak-trone","decor":"karak-trone","debut":"debut","disponible_si":{"flag":"registre-lu","affinite_min":{"elianne":40},"quete_etape":{"q-elianne":"revelation"}},"repetable":false,"romance":false,"quete":"q-elianne","pnj":"elianne","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"elianne","expression":"neutre","dit":"Elianne est restée seule dans la salle du trône, devant le feu de lave. Elle a posé son voile de l'Ordre sur ses genoux. « J'ai prié toute la nuit. Pour la première fois de ma vie, personne n'a répondu. »"},{"qui":"elianne","expression":"tristesse","dit":"« J'ai été élevée par l'Ordre. J'ai vu votre Appel. J'ai chanté pendant qu'on vous arrachait à votre monde. » Elle lève les yeux vers vous. « Comment peux-tu encore me regarder ? »"}],"effets":[],"choix":[{"texte":"« Tu ne savais pas. Et maintenant que tu sais, tu te bats pour la vérité. C'est ça qui compte. »","visible_si_bloque":false,"effets":[{"affinite":{"elianne":8}}],"aller":"fin"},{"texte":"« La Lumière n'est pas l'Ordre, Elianne. Ta foi t'appartient. »","visible_si_bloque":false,"effets":[{"affinite":{"elianne":10}}],"aller":"foi"}],"fin":false},"foi":{"repliques":[{"qui":"elianne","expression":"neutre","dit":"Elle vous regarde longtemps. Puis elle remet son voile, lentement, avec soin. « Tu as raison. Ce ne sont pas eux qui m'ont appris à soigner. C'est la Lumière. Ils n'ont pas le droit de me la prendre. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"elianne","expression":"neutre","dit":"« Il faudra choisir, bientôt. Dire la vérité, ou la garder. » Elle se lève. « Quand le moment viendra… je serai à côté de toi. Quoi que tu décides. Ou presque. »"}],"effets":[{"xp":300,"quete":{"id":"q-elianne","etape":"choix"}}],"choix":[],"fin":true}}},"il-voile":{"id":"il-voile","titre":"Ilyssë — Là où le Voile est fin","type":"individuel","lieu":"phare-noye","decor":"phare-noye","debut":"debut","disponible_si":{"flag":"carte-du-nid","affinite_min":{"ilysse":40},"quete_etape":{"q-ilysse":"voile"}},"repetable":false,"romance":false,"quete":"q-ilysse","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"ilysse","expression":"neutre","dit":"Ilyssë a installé ses instruments au sommet du Phare noyé : des lentilles, des fils d'argent, un astrolabe elfique. « La lumière verte, ici, ne vient pas de notre monde. Le Voile est si fin qu'on voit à travers. »"},{"qui":"ilysse","expression":"neutre","dit":"Elle vous tend une lentille. De l'autre côté, flou, comme sous l'eau : des lumières jaunes alignées, des toits plats, un ciel orange. Une ville. Une ville de VOTRE monde."}],"effets":[],"choix":[{"texte":"Regarder longtemps, sans un mot.","visible_si_bloque":false,"effets":[{"affinite":{"ilysse":6}}],"aller":"fin"},{"texte":"« On pourrait… rentrer, par là ? »","visible_si_bloque":false,"effets":[{"affinite":{"ilysse":4}}],"aller":"rentrer"}],"fin":false},"rentrer":{"repliques":[{"qui":"ilysse","expression":"neutre","dit":"Ilyssë ne répond pas tout de suite. « Peut-être. Un jour. Si on comprend comment le Voile se recoud… on comprendra aussi comment il s'ouvre proprement. » Elle détourne les yeux. « Tu voudrais partir ? »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"ilysse","expression":"neutre","dit":"Elle note tout dans son carnet, très vite, l'écriture qui penche. « Le Voile n'est pas déchiré au hasard. Il est déchiré le long des Appels, comme un tissu qu'on a trop percé au même endroit. » Elle relève la tête. « Ça veut dire qu'on peut le recoudre. Je ne sais pas encore comment. Mais on peut. »"}],"effets":[{"flag":"voile-compris","xp":300,"quete":{"id":"q-ilysse","etape":"recoudre"}}],"choix":[],"fin":true}}},"ky-terres":{"id":"ky-terres","titre":"Kaya — Les terres des ancêtres","type":"individuel","lieu":"campement-lunecroc","decor":"campement-lunecroc","debut":"debut","disponible_si":{"flag":"ch4-depart-fait","affinite_min":{"kaya":40},"quete_etape":{"q-kaya":"terres"}},"repetable":false,"romance":false,"quete":"q-kaya","pnj":"sorha","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"sorha","expression":"neutre","dit":"L'Ancienne Sorha déroule une peau tannée où sont dessinées les terres des Lunecroc, avant la Concorde. « Le Prévôt veut rouvrir les mines du canyon. Nos tombes sont dans ce canyon. »"},{"qui":"kaya","expression":"colere","dit":"Kaya montre les crocs. « Ils ne toucheront pas aux tombes. » Elle se tourne vers vous. « J'ai écrit au Prévôt. Avec ton nom à côté du mien. Un héros d'Aubeclaire, ça compte, à Qarzim. »"}],"effets":[],"choix":[{"texte":"« Mon nom est à toi. Utilise-le. »","visible_si_bloque":false,"effets":[{"reputation":{"ourvalis":10,"concorde":-5},"affinite":{"kaya":8}}],"aller":"fin"},{"texte":"« Allons voir le Prévôt ensemble. Il comprendra mieux en face. »","visible_si_bloque":false,"effets":[{"reputation":{"ourvalis":8},"affinite":{"kaya":6}}],"aller":"fin"}],"fin":false},"fin":{"repliques":[{"qui":"kaya","expression":"joie","dit":"Une semaine plus tard, une lettre de Qarzim : le canyon des tombes est rendu aux Lunecroc. Kaya hurle à la lune toute la nuit, et toute la tribu avec elle."},{"qui":"sorha","expression":"neutre","dit":"Sorha vous pose une plume blanche dans les cheveux. « Les ancêtres connaissent ton nom, maintenant. » Kaya, à côté : « Plus qu'un rang. Le rang S. Et ils chanteront nos noms pour toujours. »"}],"effets":[{"flag":"tombes-rendues","xp":300,"quete":{"id":"q-kaya","etape":"rang-s"}}],"choix":[],"fin":true}}},"nd-acheteurs":{"id":"nd-acheteurs","titre":"Nadja — Les acheteurs de cristaux","type":"individuel","lieu":"port-quais","decor":"port-quais","debut":"debut","disponible_si":{"flag":"carte-du-nid","affinite_min":{"nadja":40},"quete_etape":{"q-nadja":"acheteurs"}},"repetable":false,"romance":false,"quete":"q-nadja","pnj":"nadja","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"nadja","expression":"neutre","dit":"Nadja vous entraîne derrière une pile de caisses, sur les quais. « Regarde les marques. » Des caisses de cristaux d'éther, tamponnées du sceau de la Concorde. Destination : « Mur d'Aube, poste 7 »."},{"qui":"nadja","expression":"neutre","dit":"« Il n'y a pas de poste 7 sur le Mur. J'ai vérifié. » Elle sort son Grand Livre rouge. « Les cristaux passent le Mur. La Concorde vend des morceaux du Voile à la Légion. Et ça fait trente ans que ça dure. »"}],"effets":[],"choix":[{"texte":"« Avec ça, tu peux faire tomber la Concorde, Nadja. »","visible_si_bloque":false,"effets":[{"affinite":{"nadja":8}}],"aller":"fin"},{"texte":"« Avec ça, tu peux racheter ta dette. Et la leur faire payer au centuple. »","visible_si_bloque":false,"effets":[{"affinite":{"nadja":6}}],"aller":"dette"}],"fin":false},"dette":{"repliques":[{"qui":"nadja","expression":"neutre","dit":"Nadja sourit, du sourire qu'elle a quand elle négocie. « Je préfère ta version. » Puis, plus bas : « Mais je veux aussi qu'ils tombent. Ma famille, ils l'ont ruinée en souriant. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"nadja","expression":"neutre","dit":"Elle referme le Grand Livre rouge. « Il me faut une dernière preuve : un acheteur, côté Légion, pris la main dans le sac. Quand la guerre commencera, il y en aura. » Elle vous tapote la joue. « Associé. »"}],"effets":[{"flag":"trafic-concorde-prouve","xp":300,"quete":{"id":"q-nadja","etape":"liberte"}}],"choix":[],"fin":true}}},"sr-anneau-vendu":{"id":"sr-anneau-vendu","titre":"Séraphine — L'homme à la cape bleue","type":"individuel","lieu":"port-taverne","decor":"port-taverne","debut":"debut","disponible_si":{"flag":"carte-du-nid","affinite_min":{"seraphine":40},"quete_etape":{"q-seraphine":"rumeurs"}},"repetable":false,"romance":false,"quete":"q-seraphine","pnj":"seraphine","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"seraphine","expression":"neutre","dit":"Séraphine a passé trois jours à faire boire tous les capitaines de Port-Vérane. Elle tient mieux le rhum qu'eux, ce qui l'étonne elle-même. « J'ai trouvé. L'anneau d'Aldric a été vendu ici, il y a quatre ans, par un démon qui payait en obsidienne. »"},{"qui":"seraphine","expression":"neutre","dit":"« Le démon a dit au marchand : « Mon maître n'en a plus besoin. Il a une nouvelle famille. » » Elle serre les poings. « Une nouvelle famille. Aldric est de l'autre côté du Mur. Avec eux. »"}],"effets":[],"choix":[{"texte":"« Prisonnier, peut-être. Pas forcément traître. »","visible_si_bloque":false,"effets":[{"affinite":{"seraphine":8}}],"aller":"fin"},{"texte":"« Quoi qu'il soit devenu, tu n'es pas seule pour l'affronter. »","visible_si_bloque":false,"effets":[{"affinite":{"seraphine":8}}],"aller":"fin"}],"fin":false},"fin":{"repliques":[{"qui":"seraphine","expression":"tristesse","dit":"« L'armure noire. La cape bleue. » Elle ferme les yeux. « Quand la guerre commencera, je le chercherai sur le champ de bataille. Et s'il me lève une épée… » Elle ne finit pas. Elle n'a pas besoin."}],"effets":[{"flag":"aldric-chez-legion","xp":300,"quete":{"id":"q-seraphine","etape":"aldric"}}],"choix":[],"fin":true}}},"ch4-depart":{"id":"ch4-depart","titre":"L'alliance des peuples","type":"groupe","lieu":"chateau","decor":"chateau-trone","debut":"debut","disponible_si":{"flag":"chapitre-3-fini","pas_flag":"ch4-depart-fait","date_min":{"annee":1021,"mois":1,"jour":1}},"repetable":false,"romance":false,"quete":"q-ch4-feu","pnj":"edmund-iv","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Germinal 1021. Neuf ans depuis l'Appel. Sur la grande carte de la salle du trône, le Mur d'Aube est entouré de rouge. Trop de rouge."},{"qui":"edmund-iv","expression":"neutre","dit":"Le roi a vieilli. « Les éclaireurs le disent tous : la Légion se rassemble derrière le Mur. Dans trois ans, peut-être moins, elle attaquera. Et nous ne tiendrons pas seuls. »"},{"qui":"edmund-iv","expression":"neutre","dit":"« Les elfes sont avec nous, grâce à vous. Il nous faut les nains de Grisfer : leurs armes, leurs murailles. Et… » Il hésite. « Les dragons de l'Archipel, s'il en reste. »"},{"qui":"seraphine","expression":"neutre","dit":"Séraphine croise les bras. « Père, les nains ont fermé leur porte à la Couronne il y a cent ans. Ils ne l'ouvriront pas pour un ambassadeur. Ils l'ouvriront peut-être pour des héros. »","si":{"flag":"seraphine-recrutee"}},{"qui":"elianne","expression":"tristesse","dit":"Elianne, à voix basse : « Les nains ont forgé les sceaux de l'Appel, en l'an 430. Si quelqu'un a gardé une trace de ce que l'Ordre a fait… c'est eux. »","si":{"flag":"elianne-recrutee"}}],"effets":[],"choix":[{"texte":"« Nous irons à Karak-Dûm. Puis dans l'Archipel. »","visible_si_bloque":false,"effets":[],"aller":"route"},{"texte":"« Et l'Ordre, Majesté ? Que dit le Grand Prieur de tout ça ? »","visible_si_bloque":false,"effets":[],"aller":"ordre"}],"fin":false},"ordre":{"repliques":[{"qui":"edmund-iv","expression":"neutre","dit":"Le roi détourne le regard. « Le Grand Prieur dit qu'il faut un nouvel Appel. D'autres héros. » Il soupire. « Je lui ai dit d'attendre. Je ne sais pas combien de temps il m'obéira. »"}],"effets":[{"flag":"appel-menace"}],"choix":[],"suite":"route","fin":false},"route":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"On vous remet des lettres scellées, des cartes, et un sac de pièces d'or naines, frappées d'un marteau. « Elles ouvrent plus de portes que les nôtres », dit le trésorier, vexé."}],"effets":[{"flag":"ch4-depart-fait","or":300,"quete":{"id":"q-ch4-feu","etape":"karak"},"journal":"Germinal 1021 : la Couronne envoie {groupe} chercher l'alliance des nains de Grisfer et des dragons de l'Archipel."}],"choix":[],"fin":true}}},"ch4-karak":{"id":"ch4-karak","titre":"Le Roi-sous-la-Montagne","type":"groupe","lieu":"karak-trone","decor":"karak-trone","debut":"debut","disponible_si":{"quete_etape":{"q-ch4-feu":"karak"}},"repetable":false,"romance":false,"quete":"q-ch4-feu","pnj":"bardrek","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La salle du trône de Karak-Dûm est si haute qu'on n'en voit pas le plafond. Des rivières de lave domptées coulent dans des rigoles de bronze, et la chaleur vous sèche les yeux."},{"qui":"bardrek","expression":"neutre","dit":"Le roi Bardrek ne se lève pas. « Des humains. Des Appelés, en plus. » Il boit une longue gorgée. « La dernière fois que des Appelés sont venus à Karak-Dûm, c'était il y a six cents ans. Ils nous ont demandé de forger des sceaux. Nous l'avons fait. Nous le regrettons encore. »"},{"qui":"bardrek","expression":"neutre","dit":"« Une alliance ? Contre la Légion ? » Il rit, sans joie. « La Légion ne nous a jamais rien fait. Ce sont vos prêtres qui nous ont menti. »"}],"effets":[],"choix":[{"texte":"« Alors dites-nous ce qu'ils ont fait. Nous voulons la vérité, nous aussi. »","visible_si_bloque":false,"effets":[{"reputation":{"nains":5}}],"aller":"verite"},{"texte":"Lui offrir un tonnelet de bière de Karak, à la manière naine.","si":{"objet":"biere-de-karak"},"visible_si_bloque":false,"effets":[{"reputation":{"nains":10},"retirer_objet":"biere-de-karak"}],"aller":"biere"},{"texte":"« La Légion ne vous a rien fait… encore. » (Charisme, difficulté 26)","visible_si_bloque":false,"test":{"carac":"CHA","difficulte":26,"reussite":"encore","echec":"verite"},"effets":[]}],"fin":false},"biere":{"repliques":[{"qui":"bardrek","expression":"neutre","dit":"Le roi regarde le tonnelet, puis vous. Puis il éclate d'un rire qui fait trembler la lave. « Des humains qui savent offrir ! Asseyez-vous. Les tonneaux d'abord, les affaires ensuite. »"}],"effets":[],"choix":[],"suite":"verite","fin":false},"encore":{"repliques":[{"qui":"bardrek","expression":"neutre","dit":"Bardrek pose sa chope. Lentement. « … Encore. » Il se gratte la barbe. « Mes éclaireurs ont vu des soldats cendrés dans les Marches. Je croyais qu'ils se perdaient. » Un silence. « Ils ne se perdaient pas. »"}],"effets":[{"reputation":{"nains":8}}],"choix":[],"suite":"verite","fin":false},"verite":{"repliques":[{"qui":"bardrek","expression":"neutre","dit":"« Les Mille Marches. Mille étages sous la montagne. Tout en bas, la Salle des Registres : nos ancêtres y ont gravé chaque Appel depuis l'an 430, et ce que chacun a coûté. »"},{"qui":"bardrek","expression":"neutre","dit":"« Mais il y a vingt ans, le Gardien des Marches s'est réveillé. Un golem que nos ancêtres ont forgé pour protéger les Registres. Il n'obéit plus à personne. »"},{"qui":"bardrek","expression":"neutre","dit":"« Descendez. Faites taire le Gardien. Lisez les Registres. Si vous remontez, vous aurez l'alliance des nains. » Il sourit dans sa barbe. « Si vous ne remontez pas… vous aurez une belle tombe. Nous faisons de très belles tombes. »"}],"effets":[{"flag":"karak-recus","xp":500,"quete":{"id":"q-ch4-feu","etape":"marches"},"journal":"{groupe} sont reçus par Bardrek, Roi-sous-la-Montagne. Il promet l'alliance des nains s'ils reviennent des Mille Marches."}],"choix":[],"fin":true}}},"ch4-marches":{"id":"ch4-marches","titre":"Les Mille Marches","type":"groupe","lieu":"mille-marches","decor":"mille-marches","debut":"debut","disponible_si":{"quete_etape":{"q-ch4-feu":"marches"},"date_min":{"annee":1022,"mois":2,"jour":1}},"repetable":false,"romance":false,"quete":"q-ch4-feu","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Floréal 1022. La porte des Mille Marches s'ouvre dans un grondement. Un escalier plonge dans le noir. Une marche par étage. Un étage par siècle, disent les nains."},{"qui":"elianne","expression":"neutre","dit":"Elianne serre son chapelet. « Si les Registres disent ce que je crois… » Elle ne finit pas sa phrase.","si":{"flag":"elianne-recrutee"}}],"effets":[],"choix":[{"texte":"Descendre les Mille Marches.","visible_si_bloque":false,"effets":[],"aller":"donjon"}],"fin":false},"donjon":{"repliques":[],"effets":[],"choix":[],"donjon":{"id":"mille-marches","sortie":"sortie","abandon":"abandon"},"fin":false},"abandon":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le Gardien vous rejette vers l'escalier. Mais, pendant le combat, une des tables de pierre s'est fendue en deux, et un morceau a roulé à vos pieds. Vous le remontez."}],"effets":[{"objet":"registre-des-appels"}],"choix":[],"suite":"revelation","fin":false},"sortie":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le Gardien des Mille Marches s'est éteint, un genou à terre, comme un chevalier qui salue. Derrière lui, la Salle des Registres : des tables de pierre, du sol au plafond, couvertes de runes naines."}],"effets":[],"choix":[],"suite":"revelation","fin":false},"revelation":{"repliques":[{"qui":"elianne","expression":"neutre","dit":"Elianne lit, avec l'aide d'un vieux scribe nain venu avec vous. « An 430 : premier Appel. Un seul Appelé. Son nom… » Elle plisse les yeux. « Orvan. Le prix : la vallée de Cendre, au nord. Mille âmes. »"},{"qui":"elianne","expression":"neutre","dit":"« An 611 : deuxième Appel. Le prix : la ville de Merran. An 874 : troisième Appel. Le prix : les îles du Levant. » Sa voix tremble. « Chaque Appel ouvre le Voile. Chaque ouverture laisse entrer les Cendres. Chaque fois, une terre meurt. »"},{"qui":"elianne","expression":"tristesse","dit":"Elle s'arrête sur la dernière table, gravée récemment. « An 1003. Appel secret, à Valgrane. Échec. Le prix : Valgrane. » Elle se tourne lentement vers vous. « Et an 1012… » Elle ne lit pas la suite. Elle n'en a pas besoin."},{"qui":"aveline","expression":"colere","dit":"Aveline a pâli. « Valgrane. Ce n'était pas une trahison. Ce n'était pas mon père. C'était l'Ordre. Un Appel raté. » Sa main tremble sur la garde de son épée.","si":{"flag":"aveline-rencontree"}},{"qui":"elianne","expression":"neutre","dit":"Elianne referme son carnet. « Chaque invocation nourrit les Cendres. Votre venue, à vous tous, a nourri la Légion. » Elle ferme les yeux. « Et l'Ordre le sait depuis six cents ans. »"}],"effets":[{"flag":["registre-lu","nains-allies","verite-ordre"],"reputation":{"nains":20},"xp":700,"quete":{"id":"q-ch4-feu","etape":"port"},"journal":"Floréal 1022 : dans la Salle des Registres, {groupe} découvrent que chaque Appel nourrit les Cendres, et que l'Ordre le sait depuis l'an 430."}],"choix":[{"texte":"Remonter et annoncer la nouvelle à Bardrek.","visible_si_bloque":false,"effets":[],"aller":"bardrek"}],"fin":false},"bardrek":{"repliques":[{"qui":"bardrek","expression":"neutre","dit":"Bardrek écoute sans un mot. Puis il pose son marteau sur la table. « Les nains de Karak-Dûm marcheront avec vous. Pas pour la Couronne. Pas pour l'Ordre. Pour vous, qui êtes descendus. »"},{"qui":"bardrek","expression":"neutre","dit":"« Et pour les dragons… Il y a une capitaine pirate, à Port-Vérane, qui connaît la route du Nid. Corsa la Rouge. Elle me doit une jambe. Enfin, une jambe de bois : c'est moi qui l'ai fabriquée. »"}],"effets":[],"choix":[],"fin":true}}},"ch4-port":{"id":"ch4-port","titre":"Corsa la Rouge","type":"groupe","lieu":"port-quais","decor":"port-quais","debut":"debut","disponible_si":{"quete_etape":{"q-ch4-feu":"port"}},"repetable":false,"romance":false,"quete":"q-ch4-feu","pnj":"corsa","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Port-Vérane sent le sel, le goudron et le rhum renversé. Sur le pont d'une frégate rouge, une femme à la jambe de bois fait tourner un sabre autour de son doigt."},{"qui":"corsa","expression":"neutre","dit":"« Le Nid des Wyrms ? » La capitaine Corsa rit si fort que son perroquet (vivant, lui) s'envole. « Personne n'y va, mes jolis. Les récifs mangent les coques, et les dragons mangent ce qui reste. »"},{"qui":"corsa","expression":"neutre","dit":"« Et puis il y a déjà un client, cette saison. Un certain Orlen Vask, chasseur de la Concorde. Il a payé cher pour la route. Il a dit qu'il cherchait… un œuf. »"}],"effets":[],"choix":[{"texte":"« Bardrek dit que vous lui devez une jambe. »","visible_si_bloque":false,"effets":[],"aller":"jambe"},{"texte":"« Nous vous payons le double de Vask. » (500 or)","si":{"or_min":500},"visible_si_bloque":false,"effets":[{"or":-500}],"aller":"carte"},{"texte":"« Un duel. Si nous gagnons, la carte est à nous. »","visible_si_bloque":false,"effets":[],"aller":"duel"}],"fin":false},"jambe":{"repliques":[{"qui":"corsa","expression":"neutre","dit":"Corsa regarde sa jambe de bois, puis vous. « Ce vieux grincheux… » Elle soupire. « D'accord. Mais mon équipage veut s'amuser un peu d'abord. Montrez-leur ce que valent des Appelés. »"}],"effets":[],"choix":[],"suite":"duel","fin":false},"duel":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"L'équipage forme un cercle sur le quai. Deux pirates aux sabres courbes s'avancent en souriant."}],"effets":[],"choix":[],"combat":{"rencontre":"archipel-pirates","victoire":"carte","defaite":"carte-perdu"},"fin":false},"carte-perdu":{"repliques":[{"qui":"corsa","expression":"neutre","dit":"Vous voilà dans l'eau du port. Corsa vous repêche elle-même, hilare. « Vous perdez avec panache. J'aime ça. » Elle vous jette la carte. « Ne la mouillez pas plus que vous. »"}],"effets":[],"choix":[],"suite":"carte","fin":false},"carte":{"repliques":[{"qui":"corsa","expression":"neutre","dit":"Corsa déroule une carte marine couverte de croix rouges. « Le Nid est là. On n'y passe qu'en été, quand la brume se lève. Revenez à Solaire, et ne dites à personne que c'est moi. »"}],"effets":[{"flag":"carte-du-nid","xp":500,"objet":"carte-marine","quete":{"id":"q-ch4-feu","etape":"nid"},"journal":"À Port-Vérane, la capitaine Corsa la Rouge confie à {groupe} la route du Nid des Wyrms."}],"choix":[],"fin":true}}},"ch4-nid":{"id":"ch4-nid","titre":"Le Nid des Wyrms","type":"groupe","lieu":"nid-des-wyrms","decor":"nid-des-wyrms","debut":"debut","disponible_si":{"quete_etape":{"q-ch4-feu":"nid"},"date_min":{"annee":1023,"mois":4,"jour":1}},"repetable":false,"romance":false,"quete":"q-ch4-feu","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Solaire 1023. La brume s'ouvre comme un rideau. L'île est noire, fumante, couverte de nids de pierre grands comme des maisons. Ils sont presque tous vides."},{"qui":"narrateur","expression":"neutre","dit":"Dans les rochers, de jeunes wyrms (des dragons pas plus grands que des chevaux, sans ailes, furieux) se tournent vers vous en sifflant."}],"effets":[],"choix":[{"texte":"Se défendre sans les tuer : les repousser.","visible_si_bloque":false,"effets":[],"aller":"wyrms"},{"texte":"Leur montrer qu'on ne leur veut aucun mal. (Esprit, difficulté 27)","visible_si_bloque":false,"test":{"carac":"ESP","difficulte":27,"reussite":"calmes","echec":"wyrms"},"effets":[]}],"fin":false},"wyrms":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"nid-wyrms","victoire":"vask","defaite":"vask"},"fin":false},"calmes":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vous vous agenouillez, les mains ouvertes. Les wyrms reniflent, hésitent… puis se couchent, la tête basse. Ils n'ont pas peur de vous. Ils ont peur de quelqu'un d'autre."}],"effets":[{"reputation":{"dragons":10}}],"choix":[],"suite":"vask","fin":false},"vask":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Au sommet de l'île, dans le plus grand nid, un homme en manteau de cuir pose le pied sur une immense tête dorée, endormie. Des chasseurs l'entourent, des harpons à la main."},{"qui":"narrateur","expression":"neutre","dit":"« Orlen Vask, chasseur de la Concorde. » Il ne se retourne pas. « L'œuf est déjà vendu, Appelés. Il ne reste que la mère. Une dragonne endormie depuis trois siècles… savez-vous combien vaut une seule de ses écailles ? »"}],"effets":[],"choix":[{"texte":"« Écarte-toi de cette dragonne. »","visible_si_bloque":false,"effets":[],"aller":"combat"}],"fin":false},"combat":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"nid-vask","victoire":"reveil","defaite":"reveil-dur"},"fin":false},"reveil-dur":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vask vous jette à terre. Son harpon se lève au-dessus de la dragonne… et la dragonne ouvre un œil. Un œil d'or, grand comme un bouclier."},{"qui":"narrateur","expression":"neutre","dit":"Le souffle qui suit ne laisse aux chasseurs que le temps de sauter à la mer. Vask, en flammes, plonge le dernier."}],"effets":[],"choix":[],"suite":"ysoria","fin":false},"reveil":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Vask recule jusqu'au bord de la falaise, saute à la mer et disparaît dans la brume. Derrière vous, la tête dorée remue. Un œil s'ouvre. Un œil d'or, grand comme un bouclier."}],"effets":[],"choix":[],"suite":"ysoria","fin":false},"ysoria":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La dragonne se déplie. Elle est immense. Puis elle rapetisse, rapetisse, et à sa place se tient une femme grande, aux cheveux d'or et aux yeux de braise, vêtue seulement d'écailles."},{"qui":"ysoria","expression":"neutre","dit":"« Je suis Ysoria. Je dormais. » Elle regarde le nid vide, et sa voix devient très calme, ce qui est pire qu'un cri. « Mon œuf. Où est mon œuf. »"},{"qui":"ysoria","expression":"neutre","dit":"Elle vous écoute raconter, sans cligner des yeux. Puis : « Vous m'avez défendue pendant mon sommeil. Chez les dragons, cela fait de vous… » Elle cherche le mot humain. « … de la famille. Je viens avec vous. Je retrouverai mon œuf. Et je mangerai ce Vask. »"},{"qui":"ysoria","expression":"neutre","dit":"« Et votre guerre contre les Cendres ? » Elle hausse les épaules. « Les Cendres ont dévoré les miens avant vous. Les dragons qui restent écouteront ma voix. »"}],"effets":[{"flag":["ysoria-recrutee","dragons-allies"],"reputation":{"dragons":25},"xp":800,"quete":{"id":"q-ch4-feu","etape":"deserteur"},"recruter":"ysoria","journal":"Solaire 1023 : au Nid des Wyrms, {groupe} sauvent la dragonne Ysoria des chasseurs de la Concorde. Elle les rejoint, et les dragons avec elle."}],"choix":[],"fin":true}}},"ch4-deserteur":{"id":"ch4-deserteur","titre":"Celle qui a déserté","type":"groupe","lieu":"karak-porte","decor":"karak-porte","debut":"debut","disponible_si":{"quete_etape":{"q-ch4-feu":"deserteur"},"date_min":{"annee":1023,"mois":7,"jour":1}},"repetable":false,"romance":false,"quete":"q-ch4-feu","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Brumaire 1023. Les gardes de la Porte de Karak-Dûm vous font appeler en pleine nuit. « Quelqu'un vous demande. Quelqu'un avec des cornes. »"},{"qui":"narrateur","expression":"neutre","dit":"Dans la neige, devant la porte de bronze, une silhouette encapuchonnée tient à peine debout. Une corne est brisée.","si":{"flag":"morra-vivante"}},{"qui":"morra","expression":"neutre","dit":"Morra relève la tête. « Bonsoir, Appelés. » Elle sourit, avec du sang aux dents. « J'ai déserté. Ils me suivent. Vous avez cinq secondes pour décider si vous m'aidez. »","si":{"flag":"morra-vivante"}},{"qui":"narrateur","expression":"neutre","dit":"Dans la neige, devant la porte de bronze, un jeune soldat cendré lève les mains. Il a jeté son épée. « Je… je déserte. J'ai des nouvelles du Mur. Ils me suivent ! »","si":{"flag":"morra-tuee"}}],"effets":[],"choix":[{"texte":"Se battre contre les chasseurs de la Légion.","visible_si_bloque":false,"effets":[],"aller":"combat"}],"fin":false},"combat":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"deserteuse-poursuite","victoire":"apres","defaite":"apres-dur"},"fin":false},"apres-dur":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les chasseurs de la Légion vous submergent… jusqu'à ce que les portes de bronze s'ouvrent et que cinquante nains en armure en sortent en hurlant. Les soldats cendrés s'enfuient dans la neige."}],"effets":[],"choix":[],"suite":"apres","fin":false},"apres":{"repliques":[{"qui":"morra","expression":"neutre","dit":"Morra s'assoit dans la neige, essoufflée. « Le Souverain prépare l'assaut du Mur d'Aube. Au printemps 1025. Il a… » Elle ferme les yeux. « Il a dit qu'il ferait de Lyss sa nouvelle commandante. Elle a seize ans. »","si":{"flag":"morra-vivante"}},{"qui":"narrateur","expression":"neutre","dit":"Le jeune déserteur claque des dents. « Au printemps 1025, ils attaqueront le Mur d'Aube. Toute la Légion. La commandante Morra… avant de mourir, elle disait que le Souverain gardait les Appelés pour la fin. »","si":{"flag":"morra-tuee"}}],"effets":[],"choix":[{"texte":"« Viens avec nous, Morra. Nous libérerons ta sœur. »","si":{"flag":"morra-vivante"},"visible_si_bloque":false,"effets":[{"flag":["morra-recrutee","morra-alliee"],"reputation":{"legion":10},"recruter":"morra"}],"aller":"morra-oui"},{"texte":"« Tu peux rester à Karak-Dûm, à l'abri. Mais pas avec nous. »","si":{"flag":"morra-vivante"},"visible_si_bloque":false,"effets":[{"flag":"morra-refugiee"}],"aller":"morra-non"},{"texte":"Confier le déserteur aux nains et repartir.","si":{"flag":"morra-tuee"},"visible_si_bloque":false,"effets":[],"aller":"fin"}],"fin":false},"morra-oui":{"repliques":[{"qui":"morra","expression":"neutre","dit":"Morra vous regarde longtemps. Puis elle rit, un vrai rire cette fois. « Une démone parmi les Appelés. Le Souverain va en faire une attaque. » Elle tend la main. « D'accord. Mais je garde ma faux. Et je mange quand je veux. »"},{"qui":"elianne","expression":"neutre","dit":"Elianne la fixe, et Morra soutient son regard. Puis la prêtresse lui tend une couverture. « Tu trembles. » « Je ne tremble jamais. » « Tu trembles. »","si":{"flag":"elianne-recrutee"}}],"effets":[],"choix":[],"suite":"fin","fin":false},"morra-non":{"repliques":[{"qui":"morra","expression":"neutre","dit":"« À l'abri. » Morra hoche la tête, sans surprise. « Vous avez raison. On ne fait pas confiance à une démone. » Elle se détourne. « Moi non plus, je ne me ferais pas confiance. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[],"effets":[{"flag":"assaut-connu","xp":700,"quete":{"id":"q-ch4-feu","etape":"conseil"},"journal":"Brumaire 1023 : à la Porte de Karak-Dûm, {groupe} apprennent que la Légion attaquera le Mur d'Aube au printemps 1025."}],"choix":[],"fin":true}}},"ch4-conseil":{"id":"ch4-conseil","titre":"Le secret de l'Ordre","type":"groupe","lieu":"temple-du-seuil","decor":"temple-du-seuil","debut":"debut","disponible_si":{"quete_etape":{"q-ch4-feu":"conseil"},"date_min":{"annee":1023,"mois":12,"jour":1}},"repetable":false,"romance":false,"quete":"q-ch4-feu","pnj":"aureliath","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Aurore 1023. Le Temple du Seuil, où tout a commencé. Le grand cercle de l'Appel brille toujours au sol. Le Grand Prieur Auréliath vous attend devant l'autel, seul."},{"qui":"aureliath","expression":"neutre","dit":"« Les Registres des nains. » Il ne fait même pas semblant d'être surpris. « Je savais qu'un jour, quelqu'un descendrait. J'espérais que ce serait après ma mort. »"},{"qui":"aureliath","expression":"neutre","dit":"« Oui, chaque Appel nourrit les Cendres. Oui, l'Ordre le sait. Mais sans Appel, il y a six cents ans, les dragons nous auraient tous brûlés. Et sans vous, la Légion serait déjà à Lysmont. » Il ouvre les mains. « Nous avons choisi le moindre mal. Six cents ans de moindre mal. »"},{"qui":"aureliath","expression":"neutre","dit":"« Et maintenant, il faut un nouvel Appel. Vingt Appelés, cent peut-être. Pour gagner la guerre. » Il vous regarde. « Je vous demande de vous taire. Le peuple ne comprendrait pas. »"},{"qui":"elianne","expression":"colere","dit":"Elianne, d'une voix que vous ne lui connaissiez pas : « Le peuple comprendrait très bien. C'est pour ça que vous avez peur. »","si":{"flag":"elianne-recrutee"}},{"qui":"aveline","expression":"colere","dit":"Aveline a la main sur son épée. « Valgrane. Vous avez laissé exécuter mon père pour cacher votre échec. »","si":{"flag":"aveline-rencontree"}},{"qui":"morra","expression":"neutre","dit":"Morra, appuyée contre une colonne, ricane. « Et c'est nous, les démons. »","si":{"flag":"morra-recrutee"}}],"effets":[],"choix":[{"texte":"Tout révéler : convoquer le peuple sur la place de Lysmont et lire les Registres à voix haute.","visible_si_bloque":false,"effets":[{"flag":"secret-revele","reputation":{"ordre":-40,"couronne":-5}}],"aller":"revele"},{"texte":"Garder le secret, pour ne pas briser le royaume avant la guerre. Mais exiger : plus aucun Appel.","visible_si_bloque":false,"effets":[{"flag":["secret-garde","appels-suspendus"],"reputation":{"ordre":15}}],"aller":"garde"},{"texte":"Garder le secret, et laisser l'Ordre préparer un nouvel Appel pour gagner la guerre.","visible_si_bloque":false,"effets":[{"flag":["secret-garde","nouvel-appel"],"reputation":{"ordre":25,"couronne":5}}],"aller":"appel"}],"fin":false},"revele":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le lendemain, sur la place de Lysmont, vous lisez les Registres devant des milliers de gens. Le silence est total. Puis quelqu'un jette une pierre contre la porte du Temple. Puis une autre."},{"qui":"aureliath","expression":"neutre","dit":"Le soir même, le Grand Prieur est démis par le roi. On dit qu'il a quitté la ville, seul, vers le nord. Il n'a rien dit en partant. Sauf une phrase, à Elianne : « Tu feras mieux que moi. »"},{"qui":"elianne","expression":"neutre","dit":"Elianne pleure, et sourit en même temps. « L'Ordre ne sera plus jamais le même. Il faudra le reconstruire. Sans mensonges, cette fois. »","si":{"flag":"elianne-recrutee"}}],"effets":[{"flag":"aureliath-demis"}],"choix":[],"suite":"fin","fin":false},"garde":{"repliques":[{"qui":"aureliath","expression":"neutre","dit":"Auréliath vous regarde longtemps. Puis il s'incline. « Plus aucun Appel. Vous avez ma parole. » Il soupire. « Je ne sais pas si vous venez de sauver le monde ou de le perdre. »"},{"qui":"elianne","expression":"tristesse","dit":"Elianne ne dit rien sur le chemin du retour. Le soir, elle vous demande seulement : « Vous croyez qu'on peut bâtir quelque chose de juste sur un mensonge ? »","si":{"flag":"elianne-recrutee"}}],"effets":[{"affinite":{"elianne":-5}}],"choix":[],"suite":"fin","fin":false},"appel":{"repliques":[{"qui":"aureliath","expression":"neutre","dit":"Le Grand Prieur sourit, soulagé. « Vous êtes sages. Plus sages que je ne l'étais à votre âge. » Il pose la main sur le cercle de l'Appel. « Dans un an, de nouveaux héros arriveront. »"},{"qui":"elianne","expression":"colere","dit":"Elianne se lève et sort du Temple sans un mot. Sur le parvis, elle arrache le voile de l'Ordre de ses cheveux.","si":{"flag":"elianne-recrutee"}},{"qui":"ilysse","expression":"colere","dit":"Ilyssë, glaciale : « Vous venez de décider d'ouvrir une nouvelle déchirure. J'espère que vous aimerez le monde qui en sortira. »","si":{"flag":"ilysse-recrutee"}}],"effets":[{"affinite":{"elianne":-15,"ilysse":-10}}],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"L'hiver finit. Au nord, derrière le Mur d'Aube, des milliers de feux s'allument chaque nuit. Les nains forgent. Les dragons volent. Les elfes tendent leurs arcs."},{"qui":"narrateur","expression":"neutre","dit":"La guerre des Cendres commence au printemps."}],"effets":[{"xp":600,"terminer_quete":"q-ch4-feu","journal":"Aurore 1023 : {groupe} affrontent le Grand Prieur Auréliath au Temple du Seuil. L'alliance des peuples est prête pour la guerre."},{"fin_chapitre":4}],"choix":[],"fin":true}}},"sq-forge-durna":{"id":"sq-forge-durna","titre":"La forge qui s'éteint","type":"groupe","lieu":"karak-forge","decor":"karak-forge","debut":"debut","disponible_si":{"flag":"karak-recus","pas_flag":"forge-commencee"},"repetable":false,"romance":false,"quete":"q-forge-froide","pnj":"durna","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"durna","expression":"neutre","dit":"Maîtresse Durna frappe un lingot, le regarde, et le jette dans un seau avec dégoût. « Tiède. TIÈDE ! Le feu de la Grande Forge brûle depuis mille ans, et le voilà qui tousse comme un vieux nain. »"},{"qui":"durna","expression":"neutre","dit":"« La Braise-mère. Le cœur du feu. Elle vient de la Coulée de lave, là-haut. Et les salamandres l'ont volée, j'en mettrais ma barbe au feu. Enfin, si j'avais une barbe. »"}],"effets":[],"choix":[{"texte":"« Nous irons chercher votre Braise-mère. »","visible_si_bloque":false,"effets":[{"flag":"forge-commencee","quete":{"id":"q-forge-froide","etape":"coulee"}}],"aller":"fin"}],"fin":false},"fin":{"repliques":[{"qui":"durna","expression":"neutre","dit":"« Rapportez-la dans ça. » Elle vous tend une lanterne de bronze aux parois épaisses comme un pouce. « Et ne la touchez pas avec les doigts. Vous n'en aurez plus. »"}],"effets":[],"choix":[],"fin":true}}},"sq-forge-coulee":{"id":"sq-forge-coulee","titre":"La Coulée de lave","type":"groupe","lieu":"coulee-de-lave","decor":"coulee-de-lave","debut":"debut","disponible_si":{"quete_etape":{"q-forge-froide":"coulee"}},"repetable":false,"romance":false,"quete":"q-forge-froide","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La lave descend en grosses vagues lentes. Au milieu, sur un rocher noir, une braise grosse comme un poing pulse comme un cœur. Autour d'elle, des salamandres dorment, enroulées."}],"effets":[],"choix":[{"texte":"Se glisser jusqu'à la braise sans les réveiller. (Agilité, difficulté 26)","visible_si_bloque":false,"test":{"carac":"AGI","difficulte":26,"reussite":"prise","echec":"combat"},"effets":[]},{"texte":"Attaquer les salamandres.","visible_si_bloque":false,"effets":[],"aller":"combat"}],"fin":false},"combat":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"grisfer-salamandres","victoire":"prise","defaite":"prise-dure"},"fin":false},"prise-dure":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les salamandres vous chassent de la coulée, les vêtements fumants. Mais dans la bousculade, la braise a roulé jusqu'à vos pieds. Vous l'attrapez avec la lanterne."}],"effets":[],"choix":[],"suite":"prise","fin":false},"prise":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La Braise-mère entre dans la lanterne avec un soupir de contentement. Le bronze devient rouge, puis se calme."}],"effets":[{"xp":500,"quete":{"id":"q-forge-froide","etape":"retour"}}],"choix":[],"fin":true}}},"sq-forge-retour":{"id":"sq-forge-retour","titre":"Le feu de mille ans","type":"groupe","lieu":"karak-forge","decor":"karak-forge","debut":"debut","disponible_si":{"quete_etape":{"q-forge-froide":"retour"}},"repetable":false,"romance":false,"quete":"q-forge-froide","pnj":"durna","rend_quete":true,"noeuds":{"debut":{"repliques":[{"qui":"durna","expression":"neutre","dit":"Durna verse la Braise-mère dans le foyer. Le feu rugit si fort que toute la forge recule d'un pas. Puis tous les forgerons de Karak-Dûm se mettent à frapper en même temps, comme un tambour de victoire."},{"qui":"durna","expression":"neutre","dit":"« Les armes de cette guerre sortiront d'ici, et elles seront chaudes. » Elle vous tend un petit paquet. « Et ça, c'est pour vous. Un nain ne doit jamais rien à personne. »"}],"effets":[{"reputation":{"nains":10},"xp":600,"or":400,"objet":"potion-soin-supreme","terminer_quete":"q-forge-froide"}],"choix":[],"fin":true}}},"sq-cave-grumli":{"id":"sq-cave-grumli","titre":"La cave de Grumli","type":"groupe","lieu":"karak-taverne","decor":"karak-taverne","debut":"debut","disponible_si":{"flag":"karak-recus","pas_flag":"cave-commencee"},"repetable":false,"romance":false,"quete":"q-cave-grumli","pnj":"grumli","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"grumli","expression":"neutre","dit":"Grumli pleure dans sa barbe, et ce n'est pas une image. « Trois tonneaux ! Trois ! Vidés par en dessous, avec un petit trou rond. Et des traces de pattes. Des PETITES pattes ! »"},{"qui":"grumli","expression":"neutre","dit":"« Il y a un vieux tunnel sous la cave. Il descend jusqu'aux Mines profondes. Je n'ose pas y aller. Les mines, c'est plein de kobolds. Et moi, je suis tavernier, pas guerrier. »"}],"effets":[],"choix":[{"texte":"« Nous allons retrouver vos voleurs de bière. »","visible_si_bloque":false,"effets":[{"flag":"cave-commencee","quete":{"id":"q-cave-grumli","etape":"mines"}}],"aller":"fin"}],"fin":false},"fin":{"repliques":[{"qui":"grumli","expression":"neutre","dit":"« Et s'ils ont tout bu, ramenez-moi au moins les tonneaux ! Ce sont des tonneaux de famille ! »"}],"effets":[],"choix":[],"fin":true}}},"sq-cave-mines":{"id":"sq-cave-mines","titre":"Les voleurs de bière","type":"groupe","lieu":"mines-profondes","decor":"mines-profondes","debut":"debut","disponible_si":{"quete_etape":{"q-cave-grumli":"mines"}},"repetable":false,"romance":false,"quete":"q-cave-grumli","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Au bout du tunnel, une galerie. Des dizaines de kobolds (petits, écailleux, avec de grandes oreilles) sont assis autour des trois tonneaux de Grumli. Ils ont l'air… très joyeux."},{"qui":"narrateur","expression":"neutre","dit":"Plus loin dans la galerie, une lueur rouge : des gelées de magma qui avancent lentement. Les kobolds n'ont pas volé la bière pour s'amuser. Ils fuient leurs mines, envahies."}],"effets":[],"choix":[{"texte":"Chasser les gelées de magma pour rendre leurs mines aux kobolds.","visible_si_bloque":false,"effets":[],"aller":"gelees"},{"texte":"Attaquer les kobolds et reprendre les tonneaux.","visible_si_bloque":false,"effets":[],"aller":"kobolds"}],"fin":false},"gelees":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"grisfer-magma","victoire":"merci","defaite":"merci-dur"},"fin":false},"merci-dur":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les gelées vous repoussent… mais les kobolds se jettent dans la mêlée avec des pioches et des seaux d'eau. À vous tous, vous en venez à bout."}],"effets":[],"choix":[],"suite":"merci","fin":false},"merci":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les kobolds rentrent chez eux en chantant (très faux). Le plus vieux vous rend les tonneaux vides, avec une pépite d'or dans chacun, en guise d'excuse."}],"effets":[{"flag":"kobolds-amis","xp":500,"or":150,"quete":{"id":"q-cave-grumli","etape":"retour"}}],"choix":[],"fin":true},"kobolds":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"grisfer-kobolds","victoire":"chasses","defaite":"chasses"},"fin":false},"chasses":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les kobolds s'enfuient dans les galeries… vers les gelées de magma. Vous entendez leurs cris longtemps. Vous récupérez les tonneaux."}],"effets":[{"xp":400,"quete":{"id":"q-cave-grumli","etape":"retour"}}],"choix":[],"fin":true}}},"sq-cave-retour":{"id":"sq-cave-retour","titre":"Une tournée pour la maison","type":"groupe","lieu":"karak-taverne","decor":"karak-taverne","debut":"debut","disponible_si":{"quete_etape":{"q-cave-grumli":"retour"}},"repetable":false,"romance":false,"quete":"q-cave-grumli","pnj":"grumli","rend_quete":true,"noeuds":{"debut":{"repliques":[{"qui":"grumli","expression":"neutre","dit":"Grumli serre ses tonneaux dans ses bras comme des enfants retrouvés. « Mes tonneaux ! »"},{"qui":"grumli","expression":"neutre","dit":"Il écoute l'histoire des kobolds, et se gratte la tête. « Des voisins qui aiment la bière… Bon. Je leur laisserai un tonneau par mois. Au fond du tunnel. C'est bon pour les affaires, les voisins. »","si":{"flag":"kobolds-amis"}},{"qui":"grumli","expression":"neutre","dit":"« Tournée générale ! Pour les héros ! » Personne, dans toute la taverne, ne refuse."}],"effets":[{"reputation":{"nains":8},"xp":500,"or":300,"objet":"biere-de-karak","terminer_quete":"q-cave-grumli"}],"choix":[],"fin":true}}},"sq-phare-brann":{"id":"sq-phare-brann","titre":"La lumière du Phare noyé","type":"groupe","lieu":"port-taverne","decor":"port-taverne","debut":"debut","disponible_si":{"flag":"carte-du-nid","pas_flag":"phare-commence"},"repetable":false,"romance":false,"quete":"q-phare","pnj":"brann","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"brann","expression":"neutre","dit":"Le vieux Brann essuie le même verre depuis une heure. « Mon fils Tobby. Seize ans, la tête pleine de vent. Le Phare noyé s'est allumé, il y a trois nuits. Il a pris une barque pour aller voir qui l'allume. »"},{"qui":"brann","expression":"neutre","dit":"« Personne ne revient du Phare. On dit que l'équipage du Vent-Noir y monte la garde, depuis qu'il a coulé. Cinquante ans sous l'eau, et ils montent encore la garde. »"}],"effets":[],"choix":[{"texte":"« Nous ramènerons Tobby. »","visible_si_bloque":false,"effets":[{"flag":"phare-commence","quete":{"id":"q-phare","etape":"phare"}}],"aller":"fin"}],"fin":false},"fin":{"repliques":[],"effets":[],"choix":[],"fin":true}}},"sq-phare":{"id":"sq-phare","titre":"Le Phare noyé","type":"groupe","lieu":"phare-noye","decor":"phare-noye","debut":"debut","disponible_si":{"quete_etape":{"q-phare":"phare"}},"repetable":false,"romance":false,"quete":"q-phare","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"La mer arrive au deuxième étage du phare. Vous montez par l'escalier en colimaçon, couvert d'algues. En haut, la lanterne brille d'une lumière verte, froide, qui ne chauffe rien."},{"qui":"narrateur","expression":"neutre","dit":"Un garçon est assis contre la lanterne, terrifié mais vivant : Tobby. Entre vous et lui, des marins ruisselants se lèvent, les yeux vides. L'équipage du Vent-Noir."}],"effets":[],"choix":[{"texte":"Se battre pour passer.","visible_si_bloque":false,"effets":[],"aller":"combat"},{"texte":"« Votre navire a coulé il y a cinquante ans. Vous pouvez vous reposer. » (Esprit, difficulté 26)","visible_si_bloque":false,"test":{"carac":"ESP","difficulte":26,"reussite":"repos","echec":"combat"},"effets":[]}],"fin":false},"combat":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"archipel-noyes","victoire":"tobby","defaite":"tobby-dur"},"fin":false},"tobby-dur":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les noyés vous repoussent vers l'escalier… mais le soleil se lève, et ils s'effondrent en flaques d'eau de mer. Tobby se jette dans vos bras."}],"effets":[],"choix":[],"suite":"tobby","fin":false},"repos":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le capitaine noyé vous regarde longtemps. Puis il retire son chapeau. « Cinquante ans… » La lanterne s'éteint. Quand vous rouvrez les yeux, il n'y a plus que de l'eau sur les marches."}],"effets":[{"flag":"noyes-apaises"}],"choix":[],"suite":"tobby","fin":false},"tobby":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Tobby claque des dents. « Ils… ils voulaient juste que quelqu'un allume la lumière pour eux. Pour retrouver le port. »"}],"effets":[{"xp":600,"quete":{"id":"q-phare","etape":"retour"}}],"choix":[],"fin":true}}},"sq-phare-retour":{"id":"sq-phare-retour","titre":"Le retour de Tobby","type":"groupe","lieu":"port-taverne","decor":"port-taverne","debut":"debut","disponible_si":{"quete_etape":{"q-phare":"retour"}},"repetable":false,"romance":false,"quete":"q-phare","pnj":"brann","rend_quete":true,"noeuds":{"debut":{"repliques":[{"qui":"brann","expression":"neutre","dit":"Le vieux Brann lâche son verre, qui se brise. Il serre Tobby si fort que le garçon proteste. Puis il lui donne une claque derrière la tête, et le serre encore."},{"qui":"brann","expression":"neutre","dit":"« Au Requin Ivre, vous ne paierez plus jamais une chope. Jamais. Et prenez ça. » Il vous tend une vieille bourse, lourde de doublons."}],"effets":[{"xp":600,"or":450,"objet":"rhum-des-brumes","terminer_quete":"q-phare"}],"choix":[],"fin":true}}},"sq-sirene-corail":{"id":"sq-sirene-corail","titre":"Le chant de Néréa","type":"groupe","lieu":"port-marche","decor":"port-marche","debut":"debut","disponible_si":{"flag":"carte-du-nid","pas_flag":"sirene-commencee"},"repetable":false,"romance":false,"quete":"q-sirene","pnj":"corail","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"corail","expression":"neutre","dit":"Corail polit une perle sans vous regarder. « Les marins disent que la sirène du Récif chante pour les noyer. Les marins sont idiots. »"},{"qui":"corail","expression":"neutre","dit":"« Néréa chante depuis un mois. Toujours le même chant : un appel au secours, en langue des sirènes. Je suis la seule ici à la comprendre. » Elle lève enfin les yeux. « Et moi, je ne sais pas me battre. »"}],"effets":[],"choix":[{"texte":"« Nous irons au Récif. »","visible_si_bloque":false,"effets":[{"flag":"sirene-commencee","quete":{"id":"q-sirene","etape":"recif"}}],"aller":"fin"}],"fin":false},"fin":{"repliques":[],"effets":[],"choix":[],"fin":true}}},"sq-sirene-recif":{"id":"sq-sirene-recif","titre":"Le Récif des sirènes","type":"groupe","lieu":"recif-des-sirenes","decor":"recif-des-sirenes","debut":"debut","disponible_si":{"quete_etape":{"q-sirene":"recif"}},"repetable":false,"romance":false,"quete":"q-sirene","pnj":"sirene","rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Le soir tombe sur le Récif. Une voix s'élève, belle à en avoir mal. Sur un rocher, une sirène aux cheveux d'algue chante, les yeux fermés. Sa queue est prise dans un filet de fer."},{"qui":"sirene","expression":"neutre","dit":"Elle ouvre les yeux. « Enfin, des gens qui ne sautent pas à l'eau. » Sa voix parlée est rauque. « Les crabes du récif gardent le filet. Ils m'apportent à manger pour que je reste grasse. Pour la Concorde, qui paie cher les écailles de sirène. »"}],"effets":[],"choix":[{"texte":"Attaquer les crabes qui gardent le filet.","visible_si_bloque":false,"effets":[],"aller":"combat"}],"fin":false},"combat":{"repliques":[],"effets":[],"choix":[],"combat":{"rencontre":"archipel-crabes","victoire":"libre","defaite":"libre-dur"},"fin":false},"libre-dur":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les crabes vous repoussent dans l'eau. Mais pendant qu'ils s'occupent de vous, Néréa a rongé le filet. Elle plonge, libre, en riant."}],"effets":[],"choix":[],"suite":"libre","fin":false},"libre":{"repliques":[{"qui":"sirene","expression":"neutre","dit":"Néréa vous offre un coquillage nacré. « Quand tu voudras une chanson, souffle dedans. Je viendrai. » Elle hésite. « Et si un jour un barde vient au Récif… je lui apprendrai le dernier couplet. »"}],"effets":[{"flag":"nerea-libre","xp":550,"objet":"coquillage-chantant","quete":{"id":"q-sirene","etape":"retour"}}],"choix":[],"fin":true}}},"sq-sirene-retour":{"id":"sq-sirene-retour","titre":"Une dette de sirène","type":"groupe","lieu":"port-marche","decor":"port-marche","debut":"debut","disponible_si":{"quete_etape":{"q-sirene":"retour"}},"repetable":false,"romance":false,"quete":"q-sirene","pnj":"corail","rend_quete":true,"noeuds":{"debut":{"repliques":[{"qui":"corail","expression":"neutre","dit":"Corail écoute, et pour la première fois, elle sourit franchement. « Néréa est ma cousine. Très éloignée. » Elle vous tend une écaille dorée, polie comme un miroir. « Ne la vendez jamais. »"}],"effets":[{"reputation":{"dragons":5},"xp":550,"or":300,"objet":"ecaille-de-dragon-polie","terminer_quete":"q-sirene"}],"choix":[],"fin":true}}},"prologue-6-ans":{"id":"prologue-6-ans","titre":"Prologue — Les souvenirs d'avant (6 ans, 1000 AV)","type":"individuel","decor":"prologue-campagne","debut":"debut","disponible_si":{"pas_flag":"prologue-6","origine":"reincarne"},"repetable":false,"romance":false,"rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Tu as six ans. Ce matin, en regardant ton reflet dans une flaque, une vague d'images te submerge : des rues éclairées la nuit, des écrans, un nom qui n'est pas le tien… une autre vie, terminée trop tôt."},{"qui":"narrateur","expression":"neutre","dit":"Tu comprends, avec une clarté effrayante, que tu as déjà vécu. Et que ce monde-ci n'est pas le même."},{"qui":"narrateur","expression":"neutre","dit":"Mais d'abord : où as-tu grandi, dans cette nouvelle vie ?"}],"effets":[],"choix":[{"texte":"Dans une ferme près de la Combe-aux-Saules. Des champs de blé à perte de vue.","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-6","origine_enfance":"fermier","journal":"{heros} grandit dans une ferme d'Aubeclaire."}],"aller":"ferme"},{"texte":"Dans le manoir d'une petite famille noble, entre précepteurs et étiquette.","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-6","origine_enfance":"noble","journal":"{heros} grandit dans un manoir de petite noblesse."}],"aller":"manoir"},{"texte":"À l'orphelinat de l'Ordre, sous les cloches de la chapelle blanche.","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-6","origine_enfance":"orphelin","journal":"{heros} grandit à l'orphelinat de l'Ordre."}],"aller":"orphelinat"},{"texte":"Dans l'arrière-boutique encombrée d'un marchand ambulant.","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-6","origine_enfance":"marchand","journal":"{heros} grandit parmi les caisses d'un marchand."}],"aller":"boutique"}],"fin":false},"ferme":{"decor":"prologue-campagne","repliques":[{"qui":"narrateur","expression":"neutre","dit":"La ferme sent le foin et le pain chaud. Ta mère d'ici chante faux, ton père d'ici rit fort. Tu décides de garder ton secret… pour l'instant."}],"effets":[],"choix":[],"suite":"fin","fin":false},"manoir":{"decor":"prologue-manoir","repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les couloirs du manoir résonnent de leçons de maintien. Ton précepteur trouve que tu poses « de bien étranges questions » sur l'électricité."}],"effets":[],"choix":[],"suite":"fin","fin":false},"orphelinat":{"decor":"prologue-orphelinat","repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les sœurs sont strictes mais justes. Tu apprends vite à lire — trop vite, murmure-t-on. Une prêtresse note ton nom dans un registre."}],"effets":[],"choix":[],"suite":"fin","fin":false},"boutique":{"decor":"prologue-boutique","repliques":[{"qui":"narrateur","expression":"neutre","dit":"Entre les épices et les tapis roulés, tu apprends à compter plus vite que les adultes. Le marchand jure que tu lui porteras chance."}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Les souvenirs de ton ancienne vie s'estompent un peu, comme un rêve au réveil. Mais ils ne partent jamais tout à fait."}],"effets":[],"choix":[],"fin":true}}},"prologue-10-ans":{"id":"prologue-10-ans","titre":"Prologue — Le premier secret (10 ans, 1004 AV)","type":"individuel","decor":"prologue-campagne","debut":"debut","disponible_si":{"flag":"prologue-6","pas_flag":"prologue-10","origine":"reincarne"},"repetable":false,"romance":false,"rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Tu as dix ans. Une nuit d'orage, quelque chose s'éveille en toi : ton don. Il frémit sous ta peau, impatient."},{"qui":"narrateur","expression":"neutre","dit":"Un adulte entre dans la pièce au moment exact où ton don se manifeste."}],"effets":[],"choix":[{"texte":"Cacher ton don à tout prix. Personne ne doit savoir.","visible_si_bloque":false,"effets":[{"flag":["heros:prologue-10","heros:enfance-discrete"]}],"aller":"discret"},{"texte":"Lui montrer. Tu as besoin de confier ce secret à quelqu'un.","visible_si_bloque":false,"effets":[{"flag":["heros:prologue-10","heros:enfance-confiance"]}],"aller":"confiance"},{"texte":"T'en servir pour aider : le toit de la grange s'effondre sous la pluie.","visible_si_bloque":false,"effets":[{"flag":["heros:prologue-10","heros:enfance-heroique"]}],"aller":"heroique"}],"fin":false},"discret":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Tu inventes une excuse maladroite. L'adulte hausse les épaules. Tu apprends ce soir-là l'art de te taire — il te servira."}],"effets":[],"choix":[],"suite":"fin","fin":false},"confiance":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"L'adulte reste longtemps silencieux, puis te serre contre lui. « Ce sera notre secret. » Tu n'as jamais été aussi soulagé."}],"effets":[],"choix":[],"suite":"fin","fin":false},"heroique":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Ton don retient la charpente juste assez longtemps pour que les bêtes sortent. On parle de miracle au village. Toi, tu trembles toute la nuit."}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Dès lors, chaque jour, tu t'entraînes en cachette. Ton corps d'enfant apprend ce que ton âme sait déjà."}],"effets":[],"choix":[],"fin":true}}},"prologue-14-ans":{"id":"prologue-14-ans","titre":"Prologue — La rencontre (14 ans, 1008 AV)","type":"individuel","decor":"prologue-campagne","debut":"debut","disponible_si":{"flag":"prologue-10","pas_flag":"prologue-14","origine":"reincarne"},"repetable":false,"romance":false,"rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Tu as quatorze ans. Cette année-là, quelqu'un entre dans ta vie et ne la quitte plus vraiment."}],"effets":[],"choix":[{"texte":"Maître Orlo, un vieux bibliothécaire bourru, qui devine ce que tu es et t'enseigne les légendes de l'Appel.","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-14","contact":"mentor","journal":"{heros} devient l'élève de Maître Orlo."}],"aller":"mentor"},{"texte":"Cassian, fils de garde, fier et rapide. Il te bat à la course, tu le bats aux échecs. Rivaux pour la vie.","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-14","contact":"rival","journal":"{heros} se trouve un rival : Cassian."}],"aller":"rival"},{"texte":"Pipa, rieuse et intrépide, qui t'entraîne dans toutes les bêtises du canton.","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-14","contact":"ami-enfance","journal":"{heros} et Pipa deviennent inséparables."}],"aller":"amie"}],"fin":false},"mentor":{"repliques":[{"qui":"mentor","expression":"neutre","dit":"« Les Appelés d'autrefois… on les dit héros. Moi, je me demande surtout ce qu'ils ont payé pour l'être. »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"rival":{"repliques":[{"qui":"rival","expression":"neutre","dit":"« La prochaine fois, je gagne. Et un jour, je serai dans la garde royale. Toi, tu feras quoi ? »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"amie":{"repliques":[{"qui":"ami-enfance","expression":"neutre","dit":"« Promets-moi qu'un jour on partira voir la mer. Promets ! »"}],"effets":[],"choix":[],"suite":"fin","fin":false},"fin":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Ce lien te suivra jusqu'à Lysmont. Peut-être même au-delà."}],"effets":[],"choix":[],"fin":true}}},"prologue-17-ans":{"id":"prologue-17-ans","titre":"Prologue — Le départ (17 ans, 1011 AV)","type":"individuel","decor":"prologue-route-lysmont","debut":"debut","disponible_si":{"flag":"prologue-14","pas_flag":"prologue-17","origine":"reincarne"},"repetable":false,"romance":false,"rend_quete":false,"noeuds":{"debut":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Tu as dix-sept ans. Depuis des semaines, une vibration te réveille la nuit, venue de la capitale. L'Ordre prépare quelque chose."},{"qui":"narrateur","expression":"neutre","dit":"Tu prends la route de Lysmont au lever du soleil. Avant de partir, tu reçois un dernier conseil… ou un dernier cadeau."}],"effets":[],"choix":[{"texte":"Une lettre de recommandation pour la Guilde (Guilde +10).","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-17","reputation":{"guilde":10},"atout":"lettre-guilde"}],"aller":"fin"},{"texte":"Le sceau d'une famille noble qui te doit service (Couronne +10).","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-17","reputation":{"couronne":10},"atout":"sceau-noble"}],"aller":"fin"},{"texte":"La bénédiction d'une prêtresse de l'orphelinat (Ordre +10).","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-17","reputation":{"ordre":10},"atout":"benediction"}],"aller":"fin"},{"texte":"Une bourse bien remplie, économisée sou après sou (+60 or).","visible_si_bloque":false,"effets":[{"flag":"heros:prologue-17","or":60,"atout":"bourse"}],"aller":"fin"}],"fin":false},"fin":{"repliques":[{"qui":"narrateur","expression":"neutre","dit":"Au loin, les tours blanches de Lysmont. Dans quelques mois, au printemps 1012, tu auras dix-huit ans… et le Temple du Seuil s'illuminera."},{"qui":"narrateur","expression":"neutre","dit":"(Fin du prologue. Ton histoire rejoint celle des autres héros au chapitre 1.)"}],"effets":[],"choix":[],"fin":true}}}},"quetes":{"q-ch2-routes":{"id":"q-ch2-routes","titre":"Chapitre 2 — Les Routes du Sud","type":"principale","chapitre":2,"niveau":8,"region":"marche-des-sables","resume":"Une mission diplomatique à Qarzim, avec la princesse Séraphine. Mais dans la cité de la Concorde, les cristaux d'éther cachent quelque chose.","etapes":[{"id":"depart","objectif":"Répondre à la convocation de la princesse Séraphine, au château de Lysmont (Germinal 1015).","scene":"ch2-depart","lieu":"chateau"},{"id":"caravane","objectif":"Escorter la caravane sur la Route des Caravanes.","scene":"ch2-caravane","lieu":"route-des-caravanes","niveau":9},{"id":"palais","objectif":"Être reçus par le Prévôt Hassad au Palais de la Concorde.","scene":"ch2-palais","lieu":"qarzim-palais","niveau":9},{"id":"complot","objectif":"Assister au banquet de la Résidence d'Aubeclaire (10 Ardent 1016).","scene":"ch2-complot","lieu":"qarzim-residence","niveau":11},{"id":"bazar","objectif":"Enquêter pendant le Grand Bazar de Qarzim (1er Brumaire 1016).","scene":"ch2-bazar","lieu":"qarzim-bazar","niveau":12},{"id":"tempete","objectif":"Traverser le désert vers les Ruines de Sel (Solaire 1017).","scene":"ch2-tempete","lieu":"ruines-de-sel","niveau":14},{"id":"revolte","objectif":"Rejoindre le campement Lunecroc : la révolte gronde (Aurore 1017).","scene":"ch2-revolte","lieu":"campement-lunecroc","niveau":14},{"id":"fin","objectif":"Chapitre terminé."}]},"q-matriarche":{"id":"q-matriarche","titre":"La Grande Mère des chacals","type":"secondaire","chapitre":2,"niveau":10,"region":"marche-des-sables","resume":"Les caravanes qui passent par le canyon perdent des chameaux. Une meute énorme, menée par une matriarche presque blanche.","etapes":[{"id":"guilde","objectif":"Écouter Ibrek au Comptoir de la Guilde de Qarzim.","scene":"sq-chacals-guilde","lieu":"guilde-qarzim"},{"id":"canyon","objectif":"Descendre dans le Canyon des Chacals.","scene":"sq-chacals-canyon","lieu":"canyon-des-chacals"},{"id":"taniere","objectif":"Affronter la matriarche au fond du canyon.","scene":"sq-chacals","lieu":"canyon-des-chacals","niveau":11},{"id":"retour","objectif":"Revenir au Comptoir de la Guilde.","scene":"sq-chacals-retour","lieu":"guilde-qarzim"}]},"q-puits":{"id":"q-puits","titre":"Les puits asséchés","type":"secondaire","chapitre":2,"niveau":11,"region":"marche-des-sables","resume":"Le bassin de l'Oasis Bleue baisse chaque semaine. Mère Ziyane soupçonne quelqu'un de voler l'eau de Qarzim.","etapes":[{"id":"ziyane","objectif":"Parler à Mère Ziyane, à l'auberge de l'Oasis Bleue.","scene":"sq-puits-ziyane","lieu":"qarzim-oasis"},{"id":"puits","objectif":"Suivre l'ancien canal jusqu'aux puits asséchés.","scene":"sq-puits-canal","lieu":"puits-asseches"},{"id":"mines","objectif":"Trouver où va l'eau, du côté des mines d'éther.","scene":"sq-puits-mines","lieu":"mines-ether","niveau":12},{"id":"retour","objectif":"Rapporter la vérité à Mère Ziyane.","scene":"sq-puits-retour","lieu":"qarzim-oasis"}]},"q-caravane-fantome":{"id":"q-caravane-fantome","titre":"La caravane fantôme","type":"secondaire","chapitre":2,"niveau":12,"region":"marche-des-sables","resume":"Une caravane disparue il y a vingt ans réapparaît certaines nuits dans les Dunes chantantes.","etapes":[{"id":"rumeur","objectif":"Écouter Maître Ouzram, au Grand Bazar.","scene":"sq-fantome-rumeur","lieu":"qarzim-bazar"},{"id":"dunes","objectif":"Attendre la nuit dans les Dunes chantantes.","scene":"sq-fantome-dunes","lieu":"dunes-chantantes","niveau":13},{"id":"oasis","objectif":"Rapporter les cendres du marchand à l'Oasis perdue.","scene":"sq-fantome-oasis","lieu":"oasis-perdue"}]},"q-pillards":{"id":"q-pillards","titre":"Le repaire des pillards","type":"secondaire","chapitre":2,"niveau":10,"region":"marche-des-sables","resume":"Les pillards qui ont attaqué votre caravane ont un repaire. Et quelqu'un, à Qarzim, les paie.","etapes":[{"id":"indice","objectif":"Faire parler le prisonnier, à la Porte des Caravanes.","scene":"sq-pillards-prisonnier","lieu":"qarzim-porte"},{"id":"repaire","objectif":"Attaquer le repaire des pillards.","scene":"sq-pillards-repaire","lieu":"repaire-pillards","niveau":11},{"id":"retour","objectif":"Montrer les preuves à Nadja, à la Porte des Caravanes.","scene":"sq-pillards-retour","lieu":"qarzim-porte"}]},"q-kaya":{"id":"q-kaya","titre":"Le Hurlement des Ancêtres","type":"compagnon","chapitre":2,"niveau":10,"region":"marche-des-sables","resume":"Kaya revient chez les siens, chassés de leurs terres. Elle veut devenir rang S pour leur rendre leur fierté.","etapes":[{"id":"tribu","objectif":"Accompagner Kaya au campement Lunecroc (palier « Proche »).","scene":"ky-hurlement","lieu":"campement-lunecroc"},{"id":"terres","objectif":"Aider Kaya à reprendre une part des terres de sa tribu (chapitre 4)."},{"id":"rang-s","objectif":"Passer l'épreuve du rang S avec Kaya (chapitre 5)."}]},"q-nadja":{"id":"q-nadja","titre":"Le Grand Livre rouge","type":"compagnon","chapitre":2,"niveau":11,"region":"marche-des-sables","resume":"La dette de Nadja est écrite dans un livre de comptes secret de la Concorde. Ce livre dit aussi qui achète les cristaux.","etapes":[{"id":"livre","objectif":"Aider Nadja à copier le Grand Livre rouge (palier « Proche »).","scene":"nd-livre","lieu":"qarzim-palais"},{"id":"acheteurs","objectif":"Suivre la piste des acheteurs de cristaux (chapitre 4)."},{"id":"liberte","objectif":"Libérer Nadja de sa dette (chapitre 5)."}]},"q-seraphine":{"id":"q-seraphine","titre":"La Couronne et le Masque","type":"compagnon","chapitre":2,"niveau":11,"region":"marche-des-sables","resume":"Séraphine n'a jamais cru à la mort de son frère Aldric. À Qarzim, quelqu'un a vu un homme portant son anneau.","etapes":[{"id":"anneau","objectif":"Suivre la piste de l'anneau d'Aldric avec Séraphine (palier « Proche »).","scene":"sr-anneau","lieu":"qarzim-bazar"},{"id":"rumeurs","objectif":"Trouver où l'anneau a été vendu (chapitre 4)."},{"id":"aldric","objectif":"Retrouver Aldric (chapitre 5)."}]},"q-classe-lame-runique":{"id":"q-classe-lame-runique","titre":"Classe — La rune perdue","type":"classe","chapitre":2,"niveau":10,"region":"marche-des-sables","resume":"Une rune gravée sur une colonne des Ruines de Sel ne ressemble à aucune autre.","etapes":[{"id":"etape1","objectif":"Déchiffrer la rune de la colonne brisée (Lame runique).","scene":"cl-lame-runique-1","lieu":"qarzim-bazar"},{"id":"etape2","objectif":"Forger la rune à Karak-Dûm (chapitre 4)."},{"id":"etape3","objectif":"Graver la rune des Mille Sceaux (chapitre 5)."}]},"q-classe-arcaniste":{"id":"q-classe-arcaniste","titre":"Classe — Le feu du désert","type":"classe","chapitre":2,"niveau":10,"region":"marche-des-sables","resume":"Un ermite du désert dit savoir dompter la foudre des tempêtes de sable.","etapes":[{"id":"etape1","objectif":"Trouver l'ermite des dunes (Arcaniste).","scene":"cl-arcaniste-1","lieu":"qarzim-porte"},{"id":"etape2","objectif":"Capturer le feu d'un volcan de Grisfer (chapitre 4)."},{"id":"etape3","objectif":"Faire converger les quatre éléments (chapitre 5)."}]},"q-classe-invocateur":{"id":"q-classe-invocateur","titre":"Classe — Le pacte des bêtes","type":"classe","chapitre":2,"niveau":10,"region":"marche-des-sables","resume":"Les esprits des bêtes du désert répondent mal à l'appel. Il faut leur parler, pas leur ordonner.","etapes":[{"id":"etape1","objectif":"Parler à l'esprit du grand fennec (Invocateur).","scene":"cl-invocateur-1","lieu":"campement-lunecroc"},{"id":"etape2","objectif":"Gagner la confiance d'un esprit-dragon (chapitre 4)."},{"id":"etape3","objectif":"Ouvrir la Porte du Bestiaire (chapitre 5)."}]},"q-classe-ombre":{"id":"q-classe-ombre","titre":"Classe — La Main et l'Ombre","type":"classe","chapitre":2,"niveau":10,"region":"marche-des-sables","resume":"La Main de Sable recrute. Pour une Ombre, c'est une occasion… ou un piège.","etapes":[{"id":"etape1","objectif":"Répondre à l'invitation sur les toits de Qarzim (Ombre).","scene":"cl-ombre-1","lieu":"qarzim-porte"},{"id":"etape2","objectif":"Retrouver le maître qui a formé Kezir (chapitre 4)."},{"id":"etape3","objectif":"Apprendre les Mille Coupures (chapitre 5)."}]},"q-classe-gardien":{"id":"q-classe-gardien","titre":"Classe — Le serment du bouclier","type":"classe","chapitre":2,"niveau":10,"region":"marche-des-sables","resume":"Un vieux paladin de l'Ordre vit en ermite près des puits. Il garde un bouclier sans blason.","etapes":[{"id":"etape1","objectif":"Trouver le paladin des puits (Gardien).","scene":"cl-gardien-1","lieu":"qarzim-oasis"},{"id":"etape2","objectif":"Tenir la passe des Mille Marches (chapitre 4)."},{"id":"etape3","objectif":"Prêter le serment du Bastion éternel (chapitre 5)."}]},"q-classe-alchimiste":{"id":"q-classe-alchimiste","titre":"Classe — L'atelier d'airain","type":"classe","chapitre":2,"niveau":10,"region":"marche-des-sables","resume":"Au fond du Bazar, un atelier vend des plans d'automates. Il manque toujours une pièce.","etapes":[{"id":"etape1","objectif":"Racheter les plans de l'atelier du Bazar (Alchimiste).","scene":"cl-alchimiste-1","lieu":"qarzim-bazar"},{"id":"etape2","objectif":"Trouver un cœur de forge à Karak-Dûm (chapitre 4)."},{"id":"etape3","objectif":"Achever le Golem d'airain (chapitre 5)."}]},"q-classe-archer":{"id":"q-classe-archer","titre":"Classe — Le chant des ancêtres","type":"classe","chapitre":2,"niveau":10,"region":"marche-des-sables","resume":"Les Ourvalis disent que les ancêtres guident les flèches de ceux qui savent écouter le vent.","etapes":[{"id":"etape1","objectif":"Écouter le vent avec l'Ancienne Sorha (Archer).","scene":"cl-archer-1","lieu":"campement-lunecroc"},{"id":"etape2","objectif":"Tirer sur la cible des vents, dans l'Archipel (chapitre 4)."},{"id":"etape3","objectif":"Appeler la Pluie des Ancêtres (chapitre 5)."}]},"q-classe-guerisseur":{"id":"q-classe-guerisseur","titre":"Classe — Le souffle des vivants","type":"classe","chapitre":2,"niveau":10,"region":"marche-des-sables","resume":"Une fièvre touche les mineurs de l'éther. Les guérisseurs de la Concorde refusent de les soigner.","etapes":[{"id":"etape1","objectif":"Soigner les mineurs malades (Guérisseur).","scene":"cl-guerisseur-1","lieu":"mines-ether"},{"id":"etape2","objectif":"Trouver la source sacrée de l'Archipel (chapitre 4)."},{"id":"etape3","objectif":"Apprendre le Second Souffle (chapitre 5)."}]},"q-classe-berserker":{"id":"q-classe-berserker","titre":"Classe — Le sang qui chante","type":"classe","chapitre":2,"niveau":10,"region":"marche-des-sables","resume":"Dans les fosses de combat de Qarzim, un vieux sang-dragon défie quiconque prétend avoir du feu dans les veines.","etapes":[{"id":"etape1","objectif":"Relever le défi des fosses de Qarzim (Berserker).","scene":"cl-berserker-1","lieu":"qarzim-porte"},{"id":"etape2","objectif":"Écouter le sang au Nid des Wyrms (chapitre 4)."},{"id":"etape3","objectif":"Prendre la Forme du Wyrm (chapitre 5)."}]},"q-classe-barde":{"id":"q-classe-barde","titre":"Classe — La chanson perdue","type":"classe","chapitre":2,"niveau":10,"region":"marche-des-sables","resume":"Les Dunes chantantes chantent une mélodie que personne n'a jamais su noter.","etapes":[{"id":"etape1","objectif":"Noter le chant des dunes (Barde).","scene":"cl-barde-1","lieu":"qarzim-oasis"},{"id":"etape2","objectif":"Trouver le dernier couplet chez les sirènes (chapitre 4)."},{"id":"etape3","objectif":"Jouer la Symphonie du dernier acte (chapitre 5)."}]},"q-ch3-foret":{"id":"q-ch3-foret","titre":"Chapitre 3 — La Forêt qui se souvient","type":"principale","chapitre":3,"niveau":14,"region":"sylvenoire","resume":"Les elfes de Sylvenoire détiennent la vérité sur la Déchirure. Mais Ithrael ne s'ouvre pas aux humains, et la Légion Cendrée rôde déjà sous les arbres.","etapes":[{"id":"domaines","objectif":"Se présenter au château de Lysmont : la Couronne a des nouvelles (Germinal 1018).","scene":"ch3-domaines","lieu":"chateau"},{"id":"lisiere","objectif":"Entrer en Sylvenoire par la lisière.","scene":"ch3-lisiere","lieu":"lisiere-sylvenoire","niveau":15},{"id":"reine","objectif":"Être reçus par la Reine-Sève, à Ithrael (Floréal 1019).","scene":"ch3-reine","lieu":"ithrael-cour","niveau":16},{"id":"bibliotheque","objectif":"Descendre dans la Bibliothèque des Racines (Solaire 1020).","scene":"ch3-bibliotheque","lieu":"bibliotheque-racines","niveau":19},{"id":"nuitlongue","objectif":"Défendre la Clairière de la Déchirure pendant la Nuitlongue (30 Nuitlongue 1020).","scene":"ch3-nuitlongue","lieu":"clairiere-dechirure","niveau":21},{"id":"verdict","objectif":"Retourner à la Cour de la Reine-Sève.","scene":"ch3-verdict","lieu":"ithrael-cour"},{"id":"fin","objectif":"Chapitre terminé."}]},"q-follets":{"id":"q-follets","titre":"Les lumières du bois","type":"secondaire","chapitre":3,"niveau":15,"region":"sylvenoire","resume":"Un enfant d'Ithrael a suivi les feux follets. Personne n'ose aller le chercher.","etapes":[{"id":"thaliel","objectif":"Écouter Thaliel, à la Feuille d'Argent.","scene":"sq-follets-thaliel","lieu":"ithrael-auberge"},{"id":"bois","objectif":"Chercher l'enfant dans le Bois des Feux follets.","scene":"sq-follets-bois","lieu":"bois-des-feux-follets","niveau":16},{"id":"retour","objectif":"Ramener l'enfant à la Feuille d'Argent.","scene":"sq-follets-retour","lieu":"ithrael-auberge"}]},"q-vieux-chene":{"id":"q-vieux-chene","titre":"Le Vieux-Chêne malade","type":"secondaire","chapitre":3,"niveau":17,"region":"sylvenoire","resume":"La sève du Vieux-Chêne est devenue violette, et les sylvains autour de lui deviennent fous.","etapes":[{"id":"mirwen","objectif":"Écouter Mirwen, au Marché des Graines.","scene":"sq-chene-mirwen","lieu":"ithrael-marche"},{"id":"chene","objectif":"Examiner le Vieux-Chêne.","scene":"sq-chene","lieu":"vieux-chene","niveau":19},{"id":"retour","objectif":"Rapporter le remède à Mirwen.","scene":"sq-chene-retour","lieu":"ithrael-marche"}]},"q-graine":{"id":"q-graine","titre":"La graine volée","type":"secondaire","chapitre":3,"niveau":16,"region":"sylvenoire","resume":"Une graine sacrée a disparu du Cercle des dryades. Les dryades accusent les elfes ; les elfes accusent les humains.","etapes":[{"id":"vaelor","objectif":"Parler au capitaine Vaelor, à la Porte des Racines.","scene":"sq-graine-vaelor","lieu":"ithrael-racines"},{"id":"cercle","objectif":"Interroger les dryades au Cercle.","scene":"sq-graine-cercle","lieu":"cercle-des-dryades"},{"id":"marais","objectif":"Retrouver le voleur dans le Marais de brume.","scene":"sq-graine-marais","lieu":"marais-de-brume","niveau":17}]},"q-domaine":{"id":"q-domaine","titre":"Les gens du domaine","type":"secondaire","chapitre":3,"niveau":16,"region":"sylvenoire","resume":"Votre nouveau domaine a besoin d'un seigneur : des fermes pillées, un manoir en ruine, et des gens qui attendent de voir ce que vous valez.","etapes":[{"id":"arrivee","objectif":"Découvrir votre domaine.","scene":"sq-domaine-arrivee","lieu":"domaine-lisiere"},{"id":"pillards","objectif":"Chasser ceux qui pillent vos fermes, au camp avancé de la Légion.","scene":"sq-domaine-pillards","lieu":"camp-legion-sylve","niveau":17},{"id":"milice","objectif":"Organiser la défense du domaine avec Maître Aubin.","scene":"sq-domaine-milice","lieu":"domaine-lisiere"}]},"q-elianne":{"id":"q-elianne","titre":"Ce que la Lumière cache","type":"compagnon","chapitre":3,"niveau":15,"region":"sylvenoire","resume":"Elianne a trouvé, dans les archives du Temple, des lettres qui parlent d'un « tribut du Voile ». Elle n'arrive plus à prier.","etapes":[{"id":"lettres","objectif":"Écouter les doutes d'Elianne (palier « Proche »).","scene":"el-lettres","lieu":"ithrael-auberge"},{"id":"revelation","objectif":"Découvrir ce que l'Ordre cache sur les invocations (chapitre 4)."},{"id":"choix","objectif":"Aider Elianne à choisir entre sa foi et la vérité (chapitre 5)."}]},"q-ilysse":{"id":"q-ilysse","titre":"La Bibliothèque des Racines","type":"compagnon","chapitre":3,"niveau":16,"region":"sylvenoire","resume":"Ilyssë a été bannie pour avoir étudié la Déchirure. Elle veut retrouver ses propres notes, confisquées et cachées par la Reine.","etapes":[{"id":"notes","objectif":"Aider Ilyssë à reprendre ses notes confisquées (palier « Proche »).","scene":"il-notes","lieu":"ithrael-cour"},{"id":"voile","objectif":"Étudier le Voile là où il est le plus fin (chapitre 4)."},{"id":"recoudre","objectif":"Trouver comment recoudre le Voile (chapitre 5)."}]},"q-ch4-feu":{"id":"q-ch4-feu","titre":"Chapitre 4 — Feu et Écailles","type":"principale","chapitre":4,"niveau":21,"region":"monts-grisfer","resume":"La guerre approche. Il faut l'alliance des nains de Grisfer et des dragons de l'Archipel. Et Elianne cherche toujours ses preuves.","etapes":[{"id":"depart","objectif":"Se présenter au château de Lysmont (Germinal 1021).","scene":"ch4-depart","lieu":"chateau"},{"id":"karak","objectif":"Être reçus par le Roi-sous-la-Montagne, à Karak-Dûm.","scene":"ch4-karak","lieu":"karak-trone","niveau":22},{"id":"marches","objectif":"Descendre les Mille Marches (Floréal 1022).","scene":"ch4-marches","lieu":"mille-marches","niveau":23},{"id":"port","objectif":"Trouver un navire pour le Nid des Wyrms, à Port-Vérane.","scene":"ch4-port","lieu":"port-quais","niveau":24},{"id":"nid","objectif":"Aborder au Nid des Wyrms (Solaire 1023).","scene":"ch4-nid","lieu":"nid-des-wyrms","niveau":25},{"id":"deserteur","objectif":"Quelqu'un vous attend à la Porte de Karak-Dûm (Brumaire 1023).","scene":"ch4-deserteur","lieu":"karak-porte","niveau":26},{"id":"conseil","objectif":"Affronter le Grand Prieur au Temple du Seuil (Aurore 1023).","scene":"ch4-conseil","lieu":"temple-du-seuil"},{"id":"fin","objectif":"Chapitre terminé."}]},"q-forge-froide":{"id":"q-forge-froide","titre":"La forge qui s'éteint","type":"secondaire","chapitre":4,"niveau":22,"region":"monts-grisfer","resume":"Le feu de la Grande Forge brûle depuis mille ans. Il est en train de mourir.","etapes":[{"id":"durna","objectif":"Écouter Maîtresse Durna, à la Grande Forge.","scene":"sq-forge-durna","lieu":"karak-forge"},{"id":"coulee","objectif":"Trouver la Braise-mère à la Coulée de lave.","scene":"sq-forge-coulee","lieu":"coulee-de-lave","niveau":23},{"id":"retour","objectif":"Rap