ue","titre":"Premiers pas au Comptoir","type":"secondaire","chapitre":1,"niveau":1,"region":"aubeclaire","resume":"Dame Halvine vous montre comment acheter et vendre dans sa boutique.","etapes":[{"id":"acheter","objectif":"Acheter un objet utile au Comptoir de Halvine (une petite potion de soin, par exemple).","lieu":"boutique","declencheur":{"acheter":"boutique"}},{"id":"vendre","objectif":"Vendre la breloque cabossée (onglet « Vendre » de la boutique).","lieu":"boutique","declencheur":{"vendre":true}},{"id":"retour","objectif":"Retourner parler à Dame Halvine.","scene":"sq-boutique-fin","lieu":"boutique"}]},"q-loups":{"id":"q-loups","titre":"Les loups de la Combe-aux-Saules","type":"secondaire","chapitre":1,"niveau":1,"region":"aubeclaire","resume":"Gareth le fermier perd ses moutons, et sa fille n'ose plus sortir.","etapes":[{"id":"contrat","objectif":"Prendre l'affaire auprès de Dame Rowena, à la Guilde.","scene":"sq-loups-guilde","lieu":"guilde"},{"id":"ferme","objectif":"Aller voir Gareth à la Combe-aux-Saules.","scene":"sq-loups-ferme","lieu":"combe-aux-saules"},{"id":"traces","objectif":"Suivre les traces à la lisière de la Combe.","scene":"sq-loups-traces","lieu":"combe-lisiere"},{"id":"taniere","objectif":"Trouver la meute au vieux saule creux.","scene":"sq-loups","lieu":"combe-taniere"},{"id":"retour","objectif":"Revenir à la Guilde raconter la fin de l'affaire.","scene":"sq-loups-retour","lieu":"guilde"}]},"q-reliques":{"id":"q-reliques","titre":"Le marchand de reliques","type":"secondaire","chapitre":1,"niveau":2,"region":"aubeclaire","resume":"Au Chaudron Fêlé, un marchand vend des « os de saint » à prix d'or.","etapes":[{"id":"enqueter","objectif":"Approcher Ferrand à la taverne.","scene":"sq-reliques","lieu":"taverne"}]},"q-tanneurs":{"id":"q-tanneurs","titre":"Les disparus du quartier des Tanneurs","type":"secondaire","chapitre":1,"niveau":3,"region":"aubeclaire","resume":"Trois personnes ont disparu en un mois dans les ruelles des Tanneurs.","etape