":"toujours","qui":"garde","texte":"La cour reçoit sur rendez-vous. Ou sur convocation du roi."},"q-chaleur":{"id":"q-chaleur","lieu":"qarzim-porte","moment":"jour","qui":"villageois","texte":"Quelle chaleur… Même les chameaux se plaignent.","si":{"flag":"sables-ouverts"}},"q-cristaux":{"id":"q-cristaux","lieu":"qarzim-bazar","moment":"toujours","qui":"marchand","texte":"Cristaux d'éther ! Contre la fatigue, contre la tristesse, contre tout !","si":{"flag":"sables-ouverts"}},"q-concorde":{"id":"q-concorde","lieu":"qarzim-bazar","moment":"toujours","qui":"villageois","texte":"La Concorde fixe les prix, et nous, on paie.","si":{"flag":"sables-ouverts"}},"q-lunecroc":{"id":"q-lunecroc","lieu":"qarzim-porte","moment":"toujours","qui":"villageois","texte":"Les Lunecroc ont perdu leurs terres pour les mines. Pauvres gens.","si":{"flag":"sables-ouverts","pas_flag":"mines-lunecroc"}},"q-lunecroc-ok":{"id":"q-lunecroc-ok","lieu":"qarzim-porte","moment":"toujours","qui":"villageois","texte":"Les loups du désert ont repris une part des mines ! On n'avait jamais vu ça.","si":{"flag":"mines-lunecroc"}},"q-princesse":{"id":"q-princesse","lieu":"qarzim-residence","moment":"toujours","qui":"garde","texte":"La princesse est sous bonne garde. On ne la touchera pas deux fois.","si":{"flag":"vashti-denoncee"}},"q-banquet":{"id":"q-banquet","lieu":"qarzim-residence","moment":"toujours","qui":"villageois","texte":"Un banquet à la Résidence d'Aubeclaire, en Ardent ! Tout le monde y sera.","si":{"flag":"sables-ouverts","quete_etape":{"q-ch2-routes":"complot"}}},"q-ruines":{"id":"q-ruines","lieu":"qarzim-oasis","moment":"toujours","qui":"client","texte":"On dit que les Appelés sont revenus vivants des Ruines de Sel. Personne ne revient des Ruines.","si":{"flag":"ruines-explorees"}},"q-oasis":{"id":"q-oasis","lieu":"qarzim-oasis","moment":"toujours","qui":"client","texte":"L'eau de l'Oasis Bleue est revenue. Mère Ziyane offre la tournée !","si":{"flag":"eau-rendue"}},"q-nuit":{"id":"q-nuit",